INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, '.... (𐍀𐍂𐌰𐌿𐍆𐌴)𐍄𐌴, 𐌸𐌰𐌹𐌴𐌹 𐌸𐍂𐌰𐍆𐍃𐍄𐌹𐌳𐌴𐌳𐌿𐌽 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, '𐌾𐌰𐌷 𐌿𐍃𐍄𐌰𐌿𐌷𐌰𐌽𐌰 𐍅𐌰𐍂𐌸 𐍃𐍉 𐌱𐌰𐌿𐍂𐌲𐍃𐍅𐌰𐌳𐌳𐌾𐌿𐍃 ·𐌴· 𐌾𐌰𐌷 ·𐌺· 𐌳𐌰𐌲𐌰 𐌼𐌴𐌽𐍉(𐌸𐌹𐍃 𐌰𐌻𐌿𐌻𐌹𐍃), ·𐌽· 𐌳𐌰𐌲𐌴 𐌾𐌰𐌷 ·𐌱·');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, '𐌾𐌰𐌷 𐍅𐌰𐍂𐌸, 𐍃𐍅𐌴 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌽 𐍆𐌹𐌰𐌽𐌳𐍃 𐌿𐌽𐍃𐌰𐍂𐌰𐌹 𐌰𐌻𐌻𐌰𐌹, 𐌾𐌰𐌷 𐍉𐌷𐍄𐌴𐌳𐌿𐌽 𐌰𐌻𐌻𐍉𐍃 𐌸𐌹𐌿𐌳𐍉𐍃 𐌸𐍉𐍃 𐌱𐌹𐍃𐌿𐌽𐌾𐌰𐌽𐌴 𐌿𐌽𐍃𐌹𐍃, 𐌾𐌰𐌷 𐌰𐍄𐌳𐍂𐌰𐌿𐍃 𐌰𐌲𐌹𐍃 𐌹𐌽 𐌰𐌿(𐌲)𐍉𐌽𐌰 𐌹𐌶𐌴 𐌰𐌱𐍂𐌰𐌱𐌰; 𐌾𐌰𐌷 𐌿𐍆𐌺𐌿𐌽𐌸𐌴𐌳𐌿𐌽 𐌸𐌰𐍄𐌴𐌹 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰 𐍅𐌰𐍂𐌸 𐌿𐍃𐍆𐌿𐌻𐌻𐌹𐌸 𐌸𐌰𐍄𐌰 𐍅𐌰𐌿𐍂𐍃𐍄𐍅.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, '𐌾𐌰𐌷 𐌹𐌽 𐌳𐌰𐌲𐌰𐌼 𐌾𐌰𐌹𐌽𐌰𐌹𐌼 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐍅𐌴𐌹𐍃𐌿𐌽 𐌸𐌹𐌶𐌴 𐍂𐌴𐌹𐌺𐌾𐌰𐌽𐌴 𐌹𐌿𐌳𐌰𐌹𐌴, 𐌸𐌰𐌹𐌴𐌹 𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐌳𐌿𐌽 𐌰𐌹𐍀𐌹𐍃𐍄𐌿𐌻𐌰𐌽𐍃 𐌳𐌿 𐍄𐍉𐌱𐌴𐌹𐌹𐌽, 𐌾𐌰𐌷 𐍄𐍉𐌱𐌴𐌹𐌰𐍃 𐌳𐌿 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, '𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌰𐌿𐌺 𐌹𐌽 𐌹𐌿𐌳𐌰𐌹𐌰 𐌿𐍆𐌰𐌹𐌸𐌾𐌰𐌹 𐍅𐌴𐌹𐍃𐌿𐌽 𐌹𐌼𐌼𐌰, 𐌿𐌽𐍄𐌴 𐌼𐌴𐌲𐍃 𐍅𐌰𐍃 𐍃𐌰𐌹𐍇𐌰𐌹𐌽𐌴𐌹𐌹𐌽𐍃, 𐍃𐌿𐌽𐌰𐌿𐍃 𐌰𐌹𐌴𐌹𐍂𐌹𐌽𐍃, 𐌾𐌰𐌷 𐌹𐍉𐌰𐌽𐌰𐌽 𐍃𐌿𐌽𐌿𐍃 𐌹𐍃 𐌽𐌰𐌼 𐌳𐌰𐌿𐌷𐍄𐌰𐍂 𐌼𐌰𐌹𐍃𐌰𐌿𐌻𐌻𐌰𐌼𐌹𐍃, 𐍃𐌿𐌽𐌰𐌿𐍃 𐌱𐌰𐍂𐌰𐌺𐌴𐌹𐌹𐌽𐍃, 𐌳𐌿 𐌵𐌴𐌽𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, '𐌾𐌰𐌷 𐍂𐍉𐌳𐌹𐌳𐌴𐌳𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰 𐍅𐌰𐌹(𐌻𐌰) 𐌹𐌽 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐌾𐌰 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌾𐌰𐌷 𐍅𐌰𐌿𐍂𐌳𐌰 𐌼𐌴𐌹𐌽𐌰 𐍃𐍀𐌹𐌻𐌻𐍉𐌳𐌴𐌳𐌿𐌽 𐌹𐌼𐌼𐌰, 𐌾𐌰𐌷 𐌰𐌹𐍀𐌹𐍃𐍄𐌿𐌻𐌰𐌽𐍃 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐍄𐍉𐌱𐌴𐌹𐌰𐍃 𐍉𐌲𐌾𐌰𐌽 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, '𐌾𐌰𐌷 𐍅𐌰𐍂𐌸, 𐍃𐍅𐌴 𐌲𐌰𐍄𐌹𐌼𐍂𐌹𐌳𐌰 𐍅𐌰𐍂𐌸 𐍃𐍉 𐌱𐌰𐌿𐍂𐌲𐍃𐍅𐌰𐌳𐌳𐌾𐌿𐍃, 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐍄𐌹𐌳𐌰 𐌷𐌰𐌿𐍂𐌳𐌹𐌽𐍃, 𐌾𐌰𐌷 𐌲𐌰𐍅𐌴𐌹𐍃𐍉𐌳𐌰𐌹 𐍅𐌰𐌿𐍂𐌸𐌿𐌽 𐌳𐌰𐌿𐍂𐌰𐍅𐌰𐍂𐌳𐍉𐍃 𐌾𐌰𐌷 𐌻𐌹𐌿𐌸𐌰𐍂𐌾𐍉𐍃 𐌾𐌰𐌷 𐌻𐌰𐌹𐍅𐍅𐌴𐌹𐍄𐌴𐌹𐍃;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, '𐌾𐌰𐌷 𐌰𐌽𐌰𐌱𐌰𐌿𐌸 𐌰𐌽𐌰𐌹𐌹𐌽 𐌱𐍂𐍉𐌸𐍂 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌾𐌰𐌷 𐌰𐌽𐌰𐌽𐌴𐌹𐌹𐌽 𐍆𐌰𐌿𐍂𐌰𐌼𐌰𐌸𐌻𐌾𐌰 𐌱𐌰𐌿𐍂𐌲𐍃 𐌹𐌰𐌹𐍂𐌿𐍃𐌰𐌻𐌴𐌼𐍃, 𐌿𐌽𐍄𐌴 𐍃𐌰 𐍅𐌰𐍃 𐍅𐌰𐌹𐍂 𐍃𐌿𐌽𐌾𐌴𐌹𐌽𐍃 𐌾𐌰𐌷 𐍉𐌲𐌰𐌽𐌳𐍃 𐍆𐍂𐌰𐌿𐌾𐌰𐌽 𐌿𐍆𐌰𐍂 𐌼𐌰𐌽𐌰𐌲𐌰𐌽𐍃;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, '𐌾𐌰𐌷 𐌵𐌰𐌸 𐌹𐌼: 𐌽𐌹 𐌿𐍃𐌻𐌿𐌺𐌰𐌹𐌽𐌳𐌰𐌿 𐌳𐌰𐌿𐍂𐍉𐌽𐍃 𐌹𐌰𐌹𐍂𐌿𐍃𐌰𐌻𐌴𐌼𐍃, 𐌿𐌽𐌳 𐌸𐌰𐍄𐌴𐌹 𐌿𐍂𐍂𐌹𐌽𐌽𐌰𐌹 𐍃𐌿𐌽𐌽𐍉....');
