INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, '𐍈𐌰𐌽𐌿𐌷 𐌸𐌰𐌽 𐌸𐌿𐌺 𐍃𐌴𐍈𐌿𐌼 𐌲𐌰𐍃𐍄 𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌸𐍉𐌳𐌴𐌳𐌿𐌼? 𐌰𐌹𐌸𐌸𐌰𐌿 𐌽𐌰𐌵𐌰𐌳𐌰𐌽𐌰 𐌾𐌰𐌷 𐍅𐌰𐍃𐌹𐌳𐌴𐌳𐌿𐌼?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, '𐍈𐌰𐌽𐌿𐌷 𐌸𐌰𐌽 𐌸𐌿𐌺 𐍃𐌴𐍈𐌿𐌼 𐍃𐌹𐌿𐌺𐌰𐌽𐌰 𐌰𐌹𐌸𐌸𐌰𐌿 𐌹𐌽 𐌺𐌰𐍂𐌺𐌰𐍂𐌰𐌹 𐌾𐌰𐌷 𐌰𐍄𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌼 𐌳𐌿 𐌸𐌿𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, '𐌾𐌰𐌷 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌰𐌽𐌳𐍃 𐍃𐌰 𐌸𐌹𐌿𐌳𐌰𐌽𐍃 𐌵𐌹𐌸𐌹𐌸 𐌳𐌿 𐌹𐌼: 𐌰𐌼𐌴𐌽, 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃: 𐌾𐌰𐌷 𐌸𐌰𐌽𐌴𐌹 𐍄𐌰𐍅𐌹𐌳𐌴𐌳𐌿𐌸 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌸𐌹𐌶𐌴 𐌼𐌹𐌽𐌽𐌹𐍃𐍄𐌰𐌽𐌴 𐌱𐍂𐍉𐌸𐍂𐌴 𐌼𐌴𐌹𐌽𐌰𐌹𐌶𐌴, 𐌼𐌹𐍃 𐍄𐌰𐍅𐌹𐌳𐌴𐌳𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌹𐌸𐌹𐌸 𐌾𐌰𐌷 𐌸𐌰𐌹𐌼 𐌰𐍆 𐌷𐌻𐌴𐌹𐌳𐌿𐌼𐌴𐌹𐌽 𐍆𐌴𐍂𐌰𐌹: 𐌲𐌰𐌲𐌲𐌹𐌸 𐍆𐌰𐌹𐍂𐍂𐌰 𐌼𐌹𐍃, 𐌾𐌿𐍃 𐍆𐍂𐌰𐌵𐌹𐌸𐌰𐌽𐌰𐌽𐍃, 𐌹𐌽 𐍆𐍉𐌽 𐌸𐌰𐍄𐌰 𐌰𐌹𐍅𐌴𐌹𐌽𐍉, 𐌸𐌰𐍄𐌰 𐌼𐌰𐌽𐍅𐌹𐌳𐍉 𐌿𐌽𐌷𐌿𐌻𐌸𐌹𐌽 𐌾𐌰𐌷 𐌰𐌲𐌲𐌹𐌻𐌿𐌼 𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, '𐌿𐌽𐍄𐌴 𐌲𐍂𐌴𐌳𐌰𐌲𐍃 𐍅𐌰𐍃 𐌾𐌰𐌽~𐌽𐌹 𐌲𐌴𐌱𐌿𐌸 𐌼𐌹𐍃 𐌼𐌰𐍄𐌾𐌰𐌽; 𐌰𐍆𐌸𐌰𐌿𐍂𐍃𐌹𐌸𐍃 𐍅𐌰𐍃 𐌾𐌰𐌽~𐌽𐌹 𐌳𐍂𐌰𐌲𐌺𐌹𐌳𐌴𐌳𐌿𐌸 𐌼𐌹𐌺;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, '𐌲𐌰𐍃𐍄𐍃 𐌾𐌰𐌽~𐌽𐌹 𐌲𐌰𐌻𐌰𐌸(𐍉𐌳𐌴)𐌳𐌿𐌸 𐌼𐌹𐌺; 𐌽𐌰𐌵𐌰𐌸𐍃 𐌾𐌰𐌽~𐌽𐌹 𐍅𐌰𐍃𐌹𐌳𐌴(𐌳𐌿𐌸) 𐌼𐌹𐌺; 𐍃𐌹𐌿𐌺𐍃 𐌾𐌰𐌷 𐌹𐌽 𐌺𐌰𐍂𐌺𐌰𐍂𐌰𐌹 𐌾𐌰𐌽~𐌽𐌹 𐌲𐌰𐍅𐌴𐌹𐍃𐍉𐌳𐌴𐌳𐌿𐌸 𐌼𐌴𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, '𐌸𐌰𐌽𐌿𐌷 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌰𐌽𐌳 𐌾𐌰𐌷 𐌸𐌰𐌹 𐌵𐌹𐌸𐌰𐌽𐌳𐌰𐌽𐍃: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐍈𐌰𐌽 𐌸𐌿𐌺 𐍃𐌴𐍈𐌿𐌼 𐌲𐍂𐌴𐌳𐌰𐌲𐌰𐌽𐌰 𐌰𐌹𐌸𐌸𐌰𐌿 𐌰𐍆𐌸𐌰𐌿𐍂𐍃𐌹𐌳𐌰𐌽𐌰 𐌰𐌹𐌸𐌸𐌰𐌿 𐌲𐌰𐍃𐍄 𐌰𐌹𐌸𐌸𐌰𐌿 𐌽𐌰𐌵𐌰𐌳𐌰𐌽𐌰 𐌰𐌹𐌸𐌸𐌰𐌿 𐍃𐌹𐌿𐌺𐌰𐌽𐌰 𐌰𐌹𐌸𐌸𐌰𐌿 𐌹𐌽 𐌺𐌰𐍂𐌺𐌰𐍂𐌰𐌹 𐌾𐌰𐌽~𐌽𐌹 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐌹𐌳𐌴𐌳𐌴𐌹𐌼𐌰 𐌸𐌿𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, '𐌸𐌰𐌽𐌿𐌷 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌹𐌸 𐌹𐌼 𐌵𐌹𐌸𐌰𐌽𐌳𐍃: 𐌰𐌼𐌴𐌽, 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌾𐌰𐌷 𐌸𐌰𐌽𐌴𐌹 𐌽𐌹 𐍄𐌰𐍅𐌹𐌳𐌴𐌳𐌿𐌸 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌸𐌹𐌶𐌴 𐌻𐌴𐌹𐍄𐌹𐌻𐌰𐌽𐌴, 𐌼𐌹𐍃 𐌽𐌹 𐍄𐌰𐍅𐌹𐌳𐌴𐌳𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, '𐌾𐌰𐌷 𐌲𐌰𐌻𐌴𐌹𐌸𐌰𐌽𐌳 𐌸𐌰𐌹 𐌹𐌽 𐌱𐌰𐌻𐍅𐌴𐌹𐌽 𐌰𐌹𐍅𐌴𐌹𐌽𐍉𐌽, 𐌹𐌸 𐌸𐌰𐌹 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌰𐌽𐍃 𐌹𐌽 𐌻𐌹𐌱𐌰𐌹𐌽 𐌰𐌹𐍅𐌴𐌹𐌽𐍉𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, '𐌾𐌰𐌷 𐍅𐌰𐍂𐌸, 𐌱𐌹𐌸𐌴 𐌿𐍃𐍄𐌰𐌿𐌷 𐌹𐌴𐍃𐌿𐍃 𐌰𐌻𐌻𐌰 𐌸𐍉 𐍅𐌰𐌿𐍂𐌳𐌰, 𐌵𐌰𐌸 𐍃𐌹𐍀𐍉𐌽𐌾𐌰𐌼 𐍃𐌴𐌹𐌽(𐌰𐌹𐌼):');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '𐍅𐌹𐍄𐌿𐌸 𐌸𐌰𐍄𐌴𐌹 𐌰𐍆𐌰𐍂 𐍄𐍅𐌰𐌽𐍃 𐌳𐌰𐌲𐌰𐌽𐍃 𐍀(𐌰𐍃𐌺𐌰) 𐍅𐌰𐌹𐍂𐌸𐌹𐌸, 𐌾𐌰𐍃~𐍃𐌰 𐍃𐌿𐌽𐌿𐍃 𐌼𐌰𐌽𐍃 𐌰𐍄𐌲(𐌹𐌱𐌰)𐌳𐌰 𐌳𐌿 𐌿𐍃𐌷𐍂𐌰𐌼𐌾𐌰𐌽.');
