INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, '.... _𐍄𐌴𐌹𐌽𐍃 𐌸𐌹𐍃 𐌱𐌰𐌻𐍃𐌰𐌽𐌹𐍃 𐍅𐌰𐍂𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, '𐌼𐌰𐌷𐍄 𐍅𐌴𐍃𐌹 𐌰𐌿𐌺 𐌸𐌰𐍄𐌰 𐌱𐌰𐌻𐍃𐌰𐌽 𐍆𐍂𐌰𐌱𐌿𐌲𐌾𐌰𐌽 𐌹𐌽 𐌼𐌰𐌽𐌰𐌲𐌹𐌶𐍉 𐌸𐌰𐌿 𐌸𐍂𐌹𐌾𐌰 𐌷𐌿𐌽𐌳𐌰 𐍃𐌺𐌰𐍄𐍄𐌴 𐌾𐌰𐌷 𐌲𐌹𐌱𐌰𐌽 𐌿𐌽𐌻𐌴𐌳𐌰𐌹𐌼. 𐌾𐌰𐌷 𐌰𐌽𐌳𐍃𐍄𐌰𐌿𐍂𐍂𐌰𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, '𐌹𐌸 𐌹𐌴𐍃𐌿𐍃 𐌵𐌰𐌸: 𐌻𐌴𐍄𐌹𐌸 𐌸𐍉; 𐌳𐌿𐍈𐌴 𐌹𐌶𐌰𐌹 𐌿𐍃𐌸𐍂𐌹𐌿𐍄𐌹𐌸? 𐌸𐌰𐌽𐌽𐌿 𐌲𐍉𐌸 𐍅𐌰𐌿𐍂𐍃𐍄𐍅 𐍅𐌰𐌿𐍂𐌷𐍄𐌰 𐌱𐌹 𐌼𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, '𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌰𐌿𐌺 𐌸𐌰𐌽𐍃 𐌿𐌽𐌻𐌴𐌳𐌰𐌽𐍃 𐌷𐌰𐌱𐌰𐌹𐌸 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃, 𐌾𐌰𐌷 𐌸𐌰𐌽 𐍅𐌹𐌻𐌴𐌹𐌸, 𐌼𐌰𐌲𐌿𐌸 𐌹𐌼 𐍅𐌰𐌹𐌻𐌰 𐍄𐌰𐌿𐌾𐌰𐌽; 𐌹𐌸 𐌼𐌹𐌺 𐌽𐌹 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌷𐌰𐌱𐌰𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, '𐌸𐌰𐍄𐌴𐌹 𐌷𐌰𐌱𐌰𐌹𐌳𐌰 𐍃𐍉 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰; 𐍆𐌰𐌿𐍂𐍃𐌽𐌰𐌿 𐍃𐌰𐌻𐌱𐍉𐌽 𐌼𐌴𐌹𐌽 𐌻𐌴𐌹𐌺 𐌳𐌿 𐌿𐍃𐍆𐌹𐌻𐌷𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, '𐌰𐌼𐌴𐌽, 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃: 𐌸𐌹𐍃𐍈𐌰𐍂𐌿𐌷 𐌸𐌴𐌹 𐌼𐌴𐍂𐌾𐌰𐌳𐌰 𐍃𐍉 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉 𐌰𐌽𐌳 𐌰𐌻𐌻𐌰 𐌼𐌰𐌽𐌰𐍃𐌴𐌸, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐍃𐍉 𐍂𐍉𐌳𐌾𐌰𐌳𐌰 𐌳𐌿 𐌲𐌰𐌼𐌿𐌽𐌳𐌰𐌹 𐌹𐌶𐍉𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, '𐌾𐌰𐌷 𐌹𐌿𐌳𐌰𐍃 𐌹𐍃𐌺𐌰𐍂𐌹𐍉𐍄𐌴𐌹𐍃, 𐌰𐌹𐌽𐍃 𐌸𐌹𐌶𐌴 𐍄𐍅𐌰𐌻𐌹𐌱𐌴, 𐌲𐌰𐌻𐌰𐌹𐌸 𐌳𐌿 𐌸𐌰𐌹𐌼 𐌲𐌿𐌳𐌾𐌰𐌼, 𐌴𐌹 𐌲𐌰𐌻𐌴𐍅𐌹𐌳𐌴𐌳𐌹 𐌹𐌽𐌰 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, '𐌹𐌸 𐌴𐌹𐍃 𐌲𐌰𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍆𐌰𐌲𐌹𐌽𐍉𐌳𐌴𐌳𐌿𐌽 𐌾𐌰𐌷 𐌲𐌰𐌷𐌰𐌹𐌷𐌰𐌹𐍄𐌿𐌽 𐌹𐌼𐌼𐌰 𐍆𐌰𐌹𐌷𐌿 𐌲𐌹𐌱𐌰𐌽; 𐌾𐌰𐌷 𐍃𐍉𐌺𐌹𐌳𐌰 𐍈𐌰𐌹𐍅𐌰 𐌲𐌰𐍄𐌹𐌻𐌰𐌱𐌰 𐌹𐌽𐌰 𐌲𐌰𐌻𐌴𐍅𐌹𐌳𐌴𐌳𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, '𐌾𐌰𐌷 𐌸𐌰𐌼𐌼𐌰 𐍆𐍂𐌿𐌼𐌹𐍃𐍄𐌹𐌽 𐌳𐌰𐌲𐌰 𐌰𐌶𐍅𐌼𐌴, 𐌸𐌰𐌽 𐍀𐌰𐍃𐌺𐌰 𐍃𐌰𐌻𐌹𐌳𐌴𐌳𐌿𐌽, 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌸𐌰𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐌹𐍃: 𐍈𐌰𐍂 𐍅𐌹𐌻𐌴𐌹𐍃 𐌴𐌹 𐌲𐌰𐌻𐌴𐌹𐌸𐌰𐌽𐌳𐌰𐌽𐍃 𐌼𐌰𐌽𐍅𐌾𐌰𐌹𐌼𐌰, 𐌴𐌹 𐌼𐌰𐍄𐌾𐌰𐌹𐍃 𐍀𐌰𐍃𐌺𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, '𐌾𐌰𐌷 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐍄𐍅𐌰𐌽𐍃 𐍃𐌹𐍀𐍉𐌽𐌾𐌴 𐍃𐌴𐌹𐌽𐌰𐌹𐌶𐌴 𐌵𐌰𐌸𐌿𐌷 𐌳𐌿 𐌹𐌼: 𐌲𐌰𐌲𐌲𐌰𐍄𐍃 𐌹𐌽 𐌸𐍉 𐌱𐌰𐌿𐍂𐌲, 𐌾𐌰𐌷 𐌲𐌰𐌼𐍉𐍄𐌴𐌹𐌸 𐌹𐌲𐌵𐌹𐍃 𐌼𐌰𐌽𐌽𐌰 𐌺𐌰𐍃 𐍅𐌰𐍄𐌹𐌽𐍃 𐌱𐌰𐌹𐍂𐌰𐌽𐌳𐍃: 𐌲𐌰𐌲𐌲𐌰𐍄𐍃 𐌰𐍆𐌰𐍂 𐌸𐌰𐌼𐌼𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, '𐌾𐌰𐌷 𐌸𐌰𐌳𐌴𐌹 𐌹𐌽𐌽𐌲𐌰𐌻𐌴𐌹𐌸𐌰𐌹, 𐌵𐌹𐌸𐌰𐌹𐍄𐍃 𐌸𐌰𐌼𐌼𐌰 𐌷𐌴𐌹𐍅𐌰𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌸𐌰𐍄𐌴𐌹 𐌻𐌰𐌹𐍃𐌰𐍂𐌴𐌹𐍃 𐌵𐌹𐌸𐌹𐌸: 𐍈𐌰𐍂 𐍃𐌹𐌽𐌳 𐍃𐌰𐌻𐌹𐌸𐍅𐍉𐍃 𐌸𐌰𐍂𐌴𐌹 𐍀𐌰𐍃𐌺𐌰 𐌼𐌹𐌸 𐍃𐌹𐍀𐍉𐌽𐌾𐌰𐌼 𐌼𐌴𐌹𐌽𐌰𐌹𐌼 𐌼𐌰𐍄𐌾𐌰𐌿?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, '𐌾𐌰𐌷 𐍃𐌰 𐌹𐌶𐍅𐌹𐍃 𐍄𐌰𐌹𐌺𐌽𐌴𐌹𐌸 𐌺𐌴𐌻𐌹𐌺𐌽 𐌼𐌹𐌺𐌹𐌻𐌰𐍄𐌰, 𐌲𐌰𐍃𐍄𐍂𐌰𐍅𐌹𐌸, 𐌼𐌰𐌽𐍅𐌾𐌰𐍄𐌰; 𐌾𐌰𐌷 𐌾𐌰𐌹𐌽𐌰𐍂 𐌼𐌰𐌽𐍅𐌾𐌰𐌹𐌸 𐌿𐌽𐍃𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, '𐌾𐌰𐌷 𐌿𐍃𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌽 𐌸𐌰𐌹 𐍃𐌹𐍀𐍉𐌽(𐌾𐍉𐍃)....');
