INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, '𐌰𐍆𐍄𐍂𐌰 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃 𐍂𐍉𐌳𐌹𐌳𐌰 𐌵𐌰𐌸𐌿𐌷: 𐌹𐌺 𐌹𐌼 𐌻𐌹𐌿𐌷𐌰𐌸 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐌰𐌹𐍃; 𐍃𐌰𐌴𐌹 𐌻𐌰𐌹𐍃𐍄𐌴𐌹𐌸 𐌼𐌹𐌺 𐌽𐌹 𐌲𐌰𐌲𐌲𐌹𐌸 𐌹𐌽 𐍂𐌹𐌵𐌹𐌶𐌰, 𐌰𐌺 𐌷𐌰𐌱𐌰𐌹𐌸 𐌻𐌹𐌿𐌷𐌰𐌸 𐌻𐌹𐌱𐌰𐌹𐌽𐌰𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌸𐌰𐌹 𐍆𐌰𐍂𐌴𐌹𐍃𐌰𐌹𐌴𐌹𐍃: 𐌸𐌿 𐌱𐌹 𐌸𐌿𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌴𐌹𐍃; 𐍃𐍉 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌹𐌸𐌰 𐌸𐌴𐌹𐌽𐌰 𐌽𐌹𐍃𐍄 𐍃𐌿𐌽𐌾𐌴𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼: 𐌾𐌰𐌷 𐌾𐌰𐌱𐌰𐌹 𐌹𐌺 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰 𐌱𐌹 𐌼𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽, 𐍃𐌿𐌽𐌾𐌰 𐌹𐍃𐍄 𐍃𐍉 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌹𐌸𐌰 𐌼𐌴𐌹𐌽𐌰, 𐌿𐌽𐍄𐌴 𐍅𐌰𐌹𐍄 𐍈𐌰𐌸𐍂𐍉 𐌵𐌰𐌼 𐌾𐌰𐌷 𐍈𐌰𐌸 𐌲𐌰𐌻𐌴𐌹𐌸𐌰, 𐌹𐌸 𐌾𐌿𐍃 𐌽𐌹 𐍅𐌹𐍄𐌿𐌸 𐍈𐌰𐌸𐍂𐍉 𐌵𐌹𐌼𐌰, 𐌰𐌹𐌸𐌸𐌰𐌿 𐍈𐌰𐌸 𐌲𐌰𐌻𐌴𐌹𐌸𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, '𐌾𐌿𐍃 𐌱𐌹 𐌻𐌴𐌹𐌺𐌰 𐍃𐍄𐍉𐌾𐌹𐌸, 𐌹𐌸 𐌹𐌺 𐌽𐌹 𐍃𐍄𐍉𐌾𐌰 𐌰𐌹𐌽𐌽𐍉𐌷𐌿𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, '𐌾𐌰𐌸~𐌸𐌰𐌽 𐌾𐌰𐌱𐌰𐌹 𐍃𐍄𐍉𐌾𐌰 𐌹𐌺, 𐍃𐍄𐌰𐌿𐌰 𐌼𐌴𐌹𐌽𐌰 𐍃𐌿𐌽𐌾𐌴𐌹𐌽𐌰 𐌹𐍃𐍄, 𐌿𐌽𐍄𐌴 𐌰𐌹𐌽𐍃 𐌽𐌹 𐌹𐌼, 𐌰𐌺 𐌹𐌺 𐌾𐌰𐌷 𐍃𐌰𐌴𐌹 𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌼𐌹𐌺 𐌰𐍄𐍄𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, '𐌾𐌰𐌷 𐌸𐌰𐌽 𐌹𐌽 𐍅𐌹𐍄𐍉𐌳𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄 𐌸𐌰𐍄𐌴𐌹 𐍄𐍅𐌰𐌳𐌳𐌾𐌴 𐌼𐌰𐌽𐌽𐌴 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌹𐌸𐌰 𐍃𐌿𐌽𐌾𐌰 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, '𐌹𐌺 𐌹𐌼 𐍃𐌰𐌴𐌹 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰 𐌱𐌹 𐌼𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽, 𐌾𐌰𐌷 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌴𐌹𐌸 𐌱𐌹 𐌼𐌹𐌺 𐍃𐌰𐌴𐌹 𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌼𐌹𐌺 𐌰𐍄𐍄𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, '𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐍈𐌰𐍂 𐌹𐍃𐍄 𐍃𐌰 𐌰𐍄𐍄𐌰 𐌸𐌴𐌹𐌽𐍃? 𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌽𐌹 𐌼𐌹𐌺 𐌺𐌿𐌽𐌽𐌿𐌸 𐌽𐌹𐌷 𐌰𐍄𐍄𐌰𐌽 𐌼𐌴𐌹𐌽𐌰𐌽𐌰; 𐌹𐌸 𐌼𐌹𐌺 𐌺𐌿𐌽𐌸𐌴𐌳𐌴𐌹𐌸, 𐌾𐌰𐌷 𐌸𐌰𐌿 𐌰𐍄𐍄𐌰𐌽 𐌼𐌴𐌹𐌽𐌰𐌽𐌰 𐌺𐌿𐌽𐌸𐌴𐌳𐌴𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, '𐌸𐍉 𐍅𐌰𐌿𐍂𐌳𐌰 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌽 𐌲𐌰𐌶𐌰𐌿𐍆𐍅𐌻𐌰𐌺𐌹𐍉, 𐌻𐌰𐌹𐍃𐌾𐌰𐌽𐌳𐍃 𐌹𐌽 𐌰𐌻𐌷; 𐌾𐌰𐌷 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌽𐌹 𐍆𐌰𐌹𐍆𐌰𐌷 𐌹𐌽𐌰, 𐌿𐌽𐍄𐌴 𐌽𐌰𐌿𐌷𐌸𐌰𐌽𐌿𐌷 𐌽𐌹 𐌵𐌰𐌼 𐍈𐌴𐌹𐌻𐌰 𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌰𐌸 𐌰𐍆𐍄𐍂𐌰 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌺 𐌲𐌰𐌻𐌴𐌹𐌸𐌰, 𐌾𐌰𐌷 𐍃𐍉𐌺𐌴𐌹𐌸 𐌼𐌹𐌺, 𐌾𐌰𐌷 𐌹𐌽 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰𐌹 𐌹𐌶𐍅𐌰𐍂𐌰𐌹 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐌹𐌸. 𐌸𐌰𐌳𐌴𐌹 𐌹𐌺 𐌲𐌰𐌲𐌲𐌰, 𐌾𐌿𐍃 𐌽𐌹 𐌼𐌰𐌲𐌿𐌸 𐌵𐌹𐌼𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, '𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌽 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃: 𐌽𐌹𐌱𐌰𐌹 𐌿𐍃𐌵𐌹𐌼𐌰𐌹 𐍃𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽, 𐌴𐌹 𐌵𐌹𐌸𐌹𐌸: 𐌸𐌰𐌳𐌴𐌹 𐌹𐌺 𐌲𐌰𐌲𐌲𐌰, 𐌾𐌿𐍃 𐌽𐌹 𐌼𐌰𐌲𐌿𐌸 𐌵𐌹𐌼𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, '𐌾𐌰𐌷 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌾𐌿𐍃 𐌿𐍃 𐌸𐌰𐌹𐌼 𐌳𐌰𐌻𐌰𐌸𐍂𐍉 𐍃𐌹𐌾𐌿𐌸, 𐌹𐌸 𐌹𐌺 𐌿𐍃 𐌸𐌰𐌹𐌼 𐌹𐌿𐍀𐌰𐌸𐍂𐍉 𐌹𐌼; 𐌾𐌿𐍃 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐍃𐌹𐌾𐌿𐌸, 𐌹𐌸 𐌹𐌺 𐌽𐌹 𐌹𐌼 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, '𐌵𐌰𐌸 𐌽𐌿 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐌹𐌸 𐌹𐌽 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌹𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼; 𐌾𐌰𐌱𐌰𐌹 𐌰𐌿𐌺 𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌼, 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐌹𐌸 𐌹𐌽 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌹𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌸𐌿 𐍈𐌰𐍃 𐌹𐍃? 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌰𐌽𐌰𐍃𐍄𐍉𐌳𐌴𐌹𐌽𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌾𐌰𐌷 𐍂𐍉𐌳𐌾𐌰 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, '𐌼𐌰𐌽𐌰𐌲 𐍃𐌺𐌰𐌻 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃 𐍂𐍉𐌳𐌾𐌰𐌽 𐌾𐌰𐌷 𐍃𐍄𐍉𐌾𐌰𐌽; 𐌰𐌺𐌴𐌹 𐍃𐌰𐌴𐌹 𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌼𐌹𐌺 𐍃𐌿𐌽𐌾𐌴𐌹𐌽𐍃 𐌹𐍃𐍄; 𐌾𐌰𐌷 𐌹𐌺 𐌸𐌰𐍄𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌰 𐌰𐍄 𐌹𐌼𐌼𐌰 𐌸𐌰𐍄𐌰 𐍂𐍉𐌳𐌾𐌰 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, '𐌽𐌹 𐍆𐍂𐍉𐌸𐌿𐌽 𐌸𐌰𐍄𐌴𐌹 𐌰𐍄𐍄𐌰𐌽 𐌹𐌼 𐌵𐌰𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, '𐌵𐌰𐌸𐌿𐌷 𐌸𐌰𐌽 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌸𐌰𐌽 𐌿𐍃𐌷𐌰𐌿𐌷𐌴𐌹𐌸 𐌸𐌰𐌽𐌰 𐍃𐌿𐌽𐌿 𐌼𐌰𐌽𐍃, 𐌸𐌰𐌽𐌿𐌷 𐌿𐍆𐌺𐌿𐌽𐌽𐌰𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌼, 𐌾𐌰𐌷 𐌰𐍆 𐌼𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐍄𐌰𐌿𐌾𐌰 𐌽𐌹 𐍅𐌰𐌹𐌷𐍄, 𐌰𐌺 𐍃𐍅𐌰𐍃𐍅𐌴 𐌻𐌰𐌹𐍃𐌹𐌳𐌰 𐌼𐌹𐌺 𐌰𐍄𐍄𐌰 𐌼𐌴𐌹𐌽𐍃, 𐌸𐌰𐍄𐌰 𐍂𐍉𐌳𐌾𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, '𐌾𐌰𐌷 𐍃𐌰𐌴𐌹 𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌼𐌹𐌺 𐌼𐌹𐌸 𐌼𐌹𐍃 𐌹𐍃𐍄; 𐌽𐌹 𐌱𐌹𐌻𐌰𐌹𐌸 𐌼𐌹𐍃 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌰𐍄𐍄𐌰, 𐌿𐌽𐍄𐌴 𐌹𐌺 𐌸𐌰𐍄𐌴𐌹 𐌻𐌴𐌹𐌺𐌰𐌹𐌸 𐌹𐌼𐌼𐌰 𐍄𐌰𐌿𐌾𐌰 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, '𐌸𐌰𐍄𐌰 𐌹𐌼𐌼𐌰 𐍂𐍉𐌳𐌾𐌰𐌽𐌳𐌹𐌽 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌴𐌳𐌿𐌽 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌰𐌸 𐌹𐌴𐍃𐌿𐍃 𐌳𐌿 𐌸𐌰𐌹𐌼 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌼 𐍃𐌹𐍃 𐌹𐌿𐌳𐌰𐌹𐌿𐌼: 𐌾𐌰𐌱𐌰𐌹 𐌾𐌿𐍃 𐌲𐌰𐍃𐍄𐌰𐌽𐌳𐌹𐌸 𐌹𐌽 𐍅𐌰𐌿𐍂𐌳𐌰 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌱𐌹 𐍃𐌿𐌽𐌾𐌰𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐌼𐌴𐌹𐌽𐌰𐌹 𐍃𐌹𐌾𐌿𐌸,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, '𐌾𐌰𐌷 𐌿𐍆𐌺𐌿𐌽𐌽𐌰𐌹𐌸 𐍃𐌿𐌽𐌾𐌰, 𐌾𐌰𐌷 𐍃𐍉 𐍃𐌿𐌽𐌾𐌰 𐍆𐍂𐌹𐌾𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌱𐍂𐌹𐌲𐌲𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, '𐌰𐌽𐌳𐌷𐍉𐍆𐌿𐌽 𐌹𐌼𐌼𐌰: 𐍆𐍂𐌰𐌹𐍅 𐌰𐌱𐍂𐌰𐌷𐌰𐌼𐌹𐍃 𐍃𐌹𐌾𐌿𐌼 𐌾𐌰𐌷 𐌽𐌹 𐌼𐌰𐌽𐌽𐌷𐌿𐌽 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐍉𐌳𐌴𐌳𐌿𐌼 𐌰𐌹𐍅 𐍈𐌰𐌽𐌷𐌿𐌽; 𐍈𐌰𐌹𐍅𐌰 𐌸𐌿 𐌵𐌹𐌸𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐍆𐍂𐌹𐌾𐌰𐌹 𐍅𐌰𐌹𐍂𐌸𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽, 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐍈𐌰𐌶𐌿𐌷 𐍃𐌰𐌴𐌹 𐍄𐌰𐌿𐌾𐌹𐌸 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄, 𐍃𐌺𐌰𐌻𐌺𐍃 𐌹𐍃𐍄 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, '𐍃𐌰𐌷 𐌸𐌰𐌽 𐍃𐌺𐌰𐌻𐌺𐍃 𐌽𐌹 𐍅𐌹𐍃𐌹𐌸 𐌹𐌽 𐌲𐌰𐍂𐌳𐌰 𐌳𐌿 𐌰𐌹𐍅𐌰, 𐍃𐌿𐌽𐌿𐍃 𐍅𐌹𐍃𐌹𐌸 𐌳𐌿 𐌰𐌹𐍅𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, '𐌾𐌰𐌱𐌰𐌹 𐌽𐌿 𐍃𐌿𐌽𐌿𐍃 𐌹𐌶𐍅𐌹𐍃 𐍆𐍂𐌹𐌾𐌰𐌽𐍃 𐌱𐍂𐌹𐌲𐌲𐌹𐌸, 𐌱𐌹 𐍃𐌿𐌽𐌾𐌰𐌹 𐍆𐍂𐌹𐌾𐌰𐌹 𐍃𐌹𐌾𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, '𐍅𐌰𐌹𐍄 𐌸𐌰𐍄𐌴𐌹 𐍆𐍂𐌰𐌹𐍅 𐌰𐌱𐍂𐌰𐌷𐌰𐌼𐌹𐍃 𐍃𐌹𐌾𐌿𐌸; 𐌰𐌺𐌴𐌹 𐍃𐍉𐌺𐌴𐌹𐌸 𐌼𐌹𐍃 𐌿𐍃𐌵𐌹𐌼𐌰𐌽, 𐌿𐌽𐍄𐌴 𐍅𐌰𐌿𐍂𐌳 𐌼𐌴𐌹𐌽 𐌽𐌹 𐌲𐌰𐌼𐍉𐍄 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, '𐌹𐌺 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐍃𐌰𐍈 𐌰𐍄 𐌰𐍄𐍄𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐍂𐍉𐌳𐌾𐌰, 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌸𐌰𐍄𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌸 𐍆𐍂𐌰𐌼 𐌰𐍄𐍄𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰 𐍄𐌰𐌿𐌾𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, '𐌰𐌽𐌳𐌷𐍉𐍆𐌿𐌽 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌰𐍄𐍄𐌰 𐌿𐌽𐍃𐌰𐍂 𐌰𐌱𐍂𐌰𐌷𐌰𐌼 𐌹𐍃𐍄. 𐌵𐌰𐌸 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌸 𐌱𐌰𐍂𐌽𐌰 𐌰𐌱𐍂𐌰𐌷𐌰𐌼𐌹𐍃 𐍅𐌴𐍃𐌴𐌹𐌸, 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌰𐌱𐍂𐌰𐌷𐌰𐌼𐌹𐍃 𐍄𐌰𐍅𐌹𐌳𐌴𐌳𐌴𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, '𐌹𐌸 𐌽𐌿 𐍃𐍉𐌺𐌴𐌹𐌸 𐌼𐌹𐌺 𐌿𐍃𐌵𐌹𐌼𐌰𐌽, 𐌼𐌰𐌽𐌽𐌰𐌽 𐌹𐌶𐌴𐌹 𐍃𐌿𐌽𐌾𐌰 𐌹𐌶𐍅𐌹𐍃 𐍂𐍉𐌳𐌹𐌳𐌰, 𐌸𐍉𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌰 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰; 𐌸𐌰𐍄𐌿𐌷 𐌰𐌱𐍂𐌰𐌷𐌰𐌼 𐌽𐌹 𐍄𐌰𐍅𐌹𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, '𐌾𐌿𐍃 𐍄𐌰𐌿𐌾𐌹𐌸 𐍄𐍉𐌾𐌰 𐌰𐍄𐍄𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌹𐍃. 𐌸𐌰𐌽𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌹𐌼𐌼𐌰: 𐍅𐌴𐌹𐍃 𐌿𐍃 𐌷𐍉𐍂𐌹𐌽𐌰𐍃𐍃𐌰𐌿 𐌽𐌹 𐍃𐌹𐌾𐌿𐌼 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐌰𐌹; 𐌰𐌹𐌽𐌰𐌽𐌰 𐌰𐍄𐍄𐌰𐌽 𐌰𐌹𐌲𐌿𐌼, 𐌲𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, '𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌾𐌰𐌱𐌰𐌹 𐌲𐌿𐌸 𐌰𐍄𐍄𐌰 𐌹𐌶𐍅𐌰𐍂 𐍅𐌴𐍃𐌹, 𐍆𐍂𐌹𐍉𐌳𐌴𐌳𐌴𐌹𐌸 𐌸𐌰𐌿 𐌼𐌹𐌺, 𐌿𐌽𐍄𐌴 𐌹𐌺 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰 𐌿𐍂𐍂𐌰𐌽𐌽 𐌾𐌰𐌷 𐌵𐌰𐌼; 𐌽𐌹𐌷 𐌸𐌰𐌽 𐌰𐌿𐌺 𐍆𐍂𐌰𐌼 𐌼𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌽𐌹 𐌵𐌰𐌼, 𐌰𐌺 𐌹𐍃 𐌼𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, '𐌳𐌿𐍈𐌴 𐌼𐌰𐌸𐌻𐌴𐌹𐌽 𐌼𐌴𐌹𐌽𐌰 𐌽𐌹 𐌺𐌿𐌽𐌽𐌿𐌸? 𐌿𐌽𐍄𐌴 𐌽𐌹 𐌼𐌰𐌲𐌿𐌸 𐌷𐌰𐌿𐍃𐌾𐌰𐌽 𐍅𐌰𐌿𐍂𐌳 𐌼𐌴𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, '𐌾𐌿𐍃 𐌿𐍃 𐌰𐍄𐍄𐌹𐌽 𐌳𐌹𐌰𐌱𐌰𐌿𐌻𐌰𐌿 𐍃𐌹𐌾𐌿𐌸 𐌾𐌰𐌷 𐌻𐌿𐍃𐍄𐌿𐌽𐍃 𐌸𐌹𐍃 𐌰𐍄𐍄𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌹𐍃 𐍅𐌹𐌻𐌴𐌹𐌸 𐍄𐌰𐌿𐌾𐌰𐌽. 𐌾𐌰𐌹𐌽𐍃 𐌼𐌰𐌽𐌰𐌼𐌰𐌿𐍂𐌸𐍂𐌾𐌰 𐍅𐌰𐍃 𐍆𐍂𐌰𐌼 𐍆𐍂𐌿𐌼𐌹𐍃𐍄𐌾𐌰 𐌾𐌰𐌷 𐌹𐌽 𐍃𐌿𐌽𐌾𐌰𐌹 𐌽𐌹 𐌲𐌰𐍃𐍄𐍉𐌸; 𐌿𐌽𐍄𐌴 𐌽𐌹𐍃𐍄 𐍃𐌿𐌽𐌾𐌰 𐌹𐌽 𐌹𐌼𐌼𐌰. 𐌸𐌰𐌽 𐍂𐍉𐌳𐌴𐌹𐌸 𐌻𐌹𐌿𐌲𐌽, 𐌿𐍃 𐍃𐌴𐌹𐌽𐌰𐌹𐌼 𐍂𐍉𐌳𐌴𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌻𐌹𐌿𐌲𐌽𐌾𐌰 𐌹𐍃𐍄 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, '𐌹𐌸 𐌹𐌺, 𐌸𐌰𐍄𐌴𐌹 𐍃𐌿𐌽𐌾𐌰 𐍂𐍉𐌳𐌹𐌳𐌰, 𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌼𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, '𐍈𐌰𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐌲𐌰𐍃𐌰𐌺𐌹𐌸 𐌼𐌹𐌺 𐌱𐌹 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄? 𐌸𐌰𐌽𐌳𐌴 𐍃𐌿𐌽𐌾𐌰 𐌵𐌹𐌸𐌰, 𐌳𐌿𐍈𐌴 𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌼𐌹𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, '𐍃𐌰 𐍅𐌹𐍃𐌰𐌽𐌳𐍃 𐌿𐍃 𐌲𐌿𐌳𐌰 𐍅𐌰𐌿𐍂𐌳𐌰 𐌲𐌿𐌳𐌹𐍃 𐌷𐌰𐌿𐍃𐌴𐌹𐌸; 𐌳𐌿𐌸𐌴 𐌾𐌿𐍃 𐌽𐌹 𐌷𐌰𐌿𐍃𐌴𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌿𐍃 𐌲𐌿𐌳𐌰 𐌽𐌹 𐍃𐌹𐌾𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, '𐌰𐌽𐌳𐌷𐍉𐍆𐌿𐌽 𐌸𐌰𐌽 𐌸𐌰𐌹 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌽𐌹𐌿 𐍅𐌰𐌹𐌻𐌰 𐌵𐌹𐌸𐌰𐌼 𐍅𐌴𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐍃𐌰𐌼𐌰𐍂𐌴𐌹𐍄𐌴𐍃 𐌹𐍃 𐌸𐌿 𐌾𐌰𐌷 𐌿𐌽𐌷𐌿𐌻𐌸𐍉𐌽 𐌷𐌰𐌱𐌰𐌹𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌺 𐌿𐌽𐌷𐌿𐌻𐌸𐍉𐌽 𐌽𐌹 𐌷𐌰𐌱𐌰, 𐌰𐌺 𐍃𐍅𐌴𐍂𐌰 𐌰𐍄𐍄𐌰𐌽 𐌼𐌴𐌹𐌽𐌰𐌽𐌰, 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌿𐌽𐍃𐍅𐌴𐍂𐌰𐌹𐌸 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, '𐌹𐌺 𐌽𐌹 𐍃𐍉𐌺𐌾𐌰 𐌷𐌰𐌿𐌷𐌴𐌹𐌽 𐌼𐌴𐌹𐌽𐌰; 𐌹𐍃𐍄 𐍃𐌰𐌴𐌹 𐍃𐍉𐌺𐌴𐌹𐌸 𐌾𐌰𐌷 𐍃𐍄𐍉𐌾𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, '𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃: 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐍅𐌰𐌿𐍂𐌳 𐌼𐌴𐌹𐌽 𐍆𐌰𐍃𐍄𐌰𐌹𐌸, 𐌳𐌰𐌿𐌸𐌿 𐌽𐌹 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐌸 𐌰𐌹𐍅𐌰 𐌳𐌰𐌲𐌴.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌸𐌰𐌹 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃: 𐌽𐌿 𐌿𐍆𐌺𐌿𐌽𐌸𐌴𐌳𐌿𐌼 𐌸𐌰𐍄𐌴𐌹 𐌿𐌽𐌷𐌿𐌻𐌸𐍉𐌽 𐌷𐌰𐌱𐌰𐌹𐍃. 𐌰𐌱𐍂𐌰𐌷𐌰𐌼 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐍉𐌳𐌰 𐌾𐌰𐌷 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌴𐌹𐍃, 𐌾𐌰𐌷 𐌸𐌿 𐌵𐌹𐌸𐌹𐍃: 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐌼𐌴𐌹𐌽 𐍅𐌰𐌿𐍂𐌳 𐍆𐌰𐍃𐍄𐌰𐌹, 𐌽𐌹 𐌺𐌰𐌿𐍃𐌾𐌰𐌹 𐌳𐌰𐌿𐌸𐌰𐌿 𐌰𐌹𐍅𐌰 𐌳𐌰𐌲𐌴.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, '𐌹𐌱𐌰𐌹 𐌸𐌿 𐌼𐌰𐌹𐌶𐌰 𐌹𐍃 𐌰𐍄𐍄𐌹𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰 𐌰𐌱𐍂𐌰𐌷𐌰𐌼𐌰, 𐍃𐌰𐌴𐌹 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐍉𐌳𐌰? 𐌾𐌰𐌷 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌴𐌹𐍃 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐍉𐌳𐌴𐌳𐌿𐌽. 𐍈𐌰𐌽𐌰 𐌸𐌿𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐍄𐌰𐌿𐌾𐌹𐍃 𐌸𐌿?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌾𐌰𐌱𐌰𐌹 𐌹𐌺 𐌷𐌰𐌿𐌷𐌾𐌰 𐌼𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽, 𐍃𐍉 𐌷𐌰𐌿𐌷𐌴𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐌰 𐌽𐌹 𐍅𐌰𐌹𐌷𐍄𐍃 𐌹𐍃𐍄; 𐌹𐍃𐍄 𐌰𐍄𐍄𐌰 𐌼𐌴𐌹𐌽𐍃 𐍃𐌰𐌴𐌹 𐌷𐌰𐌿𐌷𐌴𐌹𐌸 𐌼𐌹𐌺, 𐌸𐌰𐌽𐌴𐌹 𐌾𐌿𐍃 𐌵𐌹𐌸𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌲𐌿𐌸 𐌿𐌽𐍃𐌰𐍂 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, '𐌾𐌰𐌷 𐌽𐌹 𐌺𐌿𐌽𐌽𐌿𐌸 𐌹𐌽𐌰; 𐌹𐌸 𐌹𐌺 𐌺𐌰𐌽𐌽 𐌹𐌽𐌰; 𐌾𐌰𐌷 𐌾𐌰𐌱𐌰𐌹 𐌵𐌴𐌸𐌾𐌰𐌿 𐌸𐌰𐍄𐌴𐌹 𐌽𐌹 𐌺𐌿𐌽𐌽𐌾𐌰𐌿 𐌹𐌽𐌰, 𐍃𐌹𐌾𐌰𐌿 𐌲𐌰𐌻𐌴𐌹𐌺𐍃 𐌹𐌶𐍅𐌹𐍃 𐌻𐌹𐌿𐌲𐌽𐌾𐌰; 𐌰𐌺 𐌺𐌰𐌽𐌽 𐌹𐌽𐌰 𐌾𐌰𐌷 𐍅𐌰𐌿𐍂𐌳 𐌹𐍃 𐍆𐌰𐍃𐍄𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, '𐌰𐌱𐍂𐌰𐌷𐌰𐌼 𐌰𐍄𐍄𐌰 𐌹𐌶𐍅𐌰𐍂 𐍃𐌹𐍆𐌰𐌹𐌳𐌰 𐌴𐌹 𐌲𐌰𐍃𐌴𐍈𐌹 𐌳𐌰𐌲 𐌼𐌴𐌹𐌽𐌰𐌽𐌰, 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐍈 𐌾𐌰𐌷 𐍆𐌰𐌲𐌹𐌽𐍉𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌹 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐍆𐌹𐌼𐍆 𐍄𐌹𐌲𐌿𐌽𐍃 𐌾𐌴𐍂𐌴 𐌽𐌰𐌿𐌷 𐌽𐌹 𐌷𐌰𐌱𐌰𐌹𐍃 𐌾𐌰𐌷 𐌰𐌱𐍂𐌰𐌷𐌰𐌼 𐍃𐌰𐍈𐍄?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, '𐌵𐌰𐌸 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃: 𐍆𐌰𐌿𐍂𐌸𐌹𐌶𐌴𐌹 𐌰𐌱𐍂𐌰𐌷𐌰𐌼 𐍅𐌰𐌿𐍂𐌸𐌹, 𐌹𐌼 𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, '𐌸𐌰𐌽𐌿𐌷 𐌽𐌴𐌼𐌿𐌽 𐍃𐍄𐌰𐌹𐌽𐌰𐌽𐍃, 𐌴𐌹 𐍅𐌰𐌿𐍂𐍀𐌴𐌹𐌽𐌰 𐌰𐌽𐌰 𐌹𐌽𐌰; 𐌹𐌸 𐌹𐌴𐍃𐌿𐍃 𐌸𐌰𐌽 𐌲𐌰𐍆𐌰𐌻𐌷 𐍃𐌹𐌺 𐌾𐌰𐌷 𐌿𐍃𐌹𐌳𐌳𐌾𐌰 𐌿𐍃 𐌰𐌻𐌷 𐌿𐍃𐌻𐌴𐌹𐌸𐌰𐌽𐌳𐍃 𐌸𐌰𐌹𐍂𐌷 𐌼𐌹𐌳𐌾𐌰𐌽𐍃 𐌹𐌽𐍃, 𐌾𐌰𐌷 𐍈𐌰𐍂𐌱𐍉𐌳𐌰 𐍃𐍅𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, '𐌾𐌰𐌷 𐌸𐌰𐌹𐍂𐌷𐌲𐌰𐌲𐌲𐌰𐌽𐌳𐍃 𐌲𐌰𐌿𐌼𐌹𐌳𐌰 𐌼𐌰𐌽𐌽 𐌱𐌻𐌹𐌽𐌳𐌰𐌼𐌼𐌰 𐌿𐍃 𐌲𐌰𐌱𐌰𐌿𐍂𐌸𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, '𐌸𐌰𐍂𐌿𐌷 𐍆𐍂𐌴𐌷𐌿𐌽 𐌹𐌽𐌰 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐌹𐍃 𐌵𐌹𐌸𐌰𐌽𐌳𐌰𐌽𐍃: 𐍂𐌰𐌱𐌱𐌴𐌹, 𐍈𐌰𐍃 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰, 𐍃𐌰𐌿 𐌸𐌰𐌿 𐍆𐌰𐌳𐍂𐌴𐌹𐌽 𐌹𐍃, 𐌴𐌹 𐌱𐌻𐌹𐌽𐌳𐍃 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐍃 𐍅𐌰𐍂𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌽𐌹𐌷 𐍃𐌰 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰 𐌽𐌹𐌷 𐍆𐌰𐌳𐍂𐌴𐌹𐌽 𐌹𐍃, 𐌰𐌺 𐌴𐌹 𐌱𐌰𐌹𐍂𐌷𐍄𐌰 𐍅𐌰𐌿𐍂𐌸𐌴𐌹𐌽𐌰 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌲𐌿𐌳𐌹𐍃 𐌰𐌽𐌰 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, '𐌹𐌺 𐍃𐌺𐌰𐌻 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌸𐌹𐍃 𐍃𐌰𐌽𐌳𐌾𐌰𐌽𐌳𐌹𐌽𐍃 𐌼𐌹𐌺, 𐌿𐌽𐍄𐌴 𐌳𐌰𐌲𐍃 𐌹𐍃𐍄; 𐌵𐌹𐌼𐌹𐌸 𐌽𐌰𐌷𐍄𐍃, 𐌸𐌰(𐌽)𐌴𐌹 𐌽𐌹 𐌼𐌰𐌽𐌽𐌰 𐌼𐌰𐌲 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, '𐌸𐌰𐌽 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌹𐌼, 𐌻𐌹𐌿𐌷𐌰𐌸 𐌹𐌼 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, '𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌰𐌽𐌳𐍃 𐌲𐌰𐍃𐍀𐌰𐌹𐍅 𐌳𐌰𐌻𐌰𐌸, 𐌾𐌰𐌷 𐌲𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰 𐍆𐌰𐌽𐌹 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍃𐍀𐌰𐌹𐍃𐌺𐌿𐌻𐌳𐍂𐌰, 𐌾𐌰𐌷 𐌲𐌰𐍃𐌼𐌰𐌹𐍄 𐌹𐌼𐌼𐌰 𐌰𐌽𐌰 𐌰𐌿𐌲𐍉𐌽𐌰 𐌸𐌰𐍄𐌰 𐍆𐌰𐌽𐌹 𐌸𐌰𐌼𐌼𐌰 𐌱𐌻𐌹𐌽𐌳𐌹𐌽,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, '𐌾𐌰𐌷 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌲𐌰𐌲𐌲 𐌸𐍅𐌰𐌷𐌰𐌽 𐌹𐌽 𐍃𐍅𐌿𐌼𐍃𐌻 𐍃𐌹𐌻𐍉𐌰𐌼𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐍃𐌺𐌴𐌹𐍂𐌾𐌰𐌳𐌰 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌸𐍃. 𐌲𐌰𐌻𐌰𐌹𐌸 𐌾𐌰𐌷 𐌰𐍆𐌸𐍅𐍉𐌷 𐌾𐌰𐌷 𐌵𐌰𐌼 𐍃𐌰𐌹𐍈𐌰𐌽𐌳𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, '𐌸𐌰𐌽𐌿𐌷 𐌲𐌰𐍂𐌰𐌶𐌽𐌰𐌽𐍃 𐌾𐌰𐌷 𐌸𐌰𐌹 𐍃𐌰𐌹𐍈𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽𐌰 𐍆𐌰𐌿𐍂𐌸𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃 𐌱𐌹𐌳𐌰𐌲𐍅𐌰 𐍅𐌰𐍃, 𐌵𐌴𐌸𐌿𐌽: 𐌽𐌹𐌿 𐍃𐌰 𐌹𐍃𐍄 𐍃𐌰𐌴𐌹 𐍃𐌰𐍄 𐌰𐌹𐌷𐍄𐍂𐍉𐌽𐌳𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, '𐍃𐌿𐌼𐌰𐌹𐌷 𐌵𐌴𐌸𐌿𐌽: 𐌸𐌰𐍄𐌴𐌹 𐍃𐌰 𐌹𐍃𐍄; 𐍃𐌿𐌼𐌰𐌹𐌷 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐌻𐌴𐌹𐌺𐍃 𐌸𐌰𐌼𐌼𐌰 𐌹𐍃𐍄; 𐌹𐌸 𐌹𐍃 𐌵𐌰𐌸: 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐍈𐌰𐌹𐍅𐌰 𐌿𐍃𐌻𐌿𐌺𐌽𐍉𐌳𐌴𐌳𐌿𐌽 𐌸𐌿𐍃 𐌸𐍉 𐌰𐌿𐌲𐍉𐌽𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌾𐌰𐌹𐌽𐍃 𐌾𐌰𐌷 𐌵𐌰𐌸: 𐌼𐌰𐌽𐌽𐌰 𐌷𐌰𐌹𐍄𐌰𐌽𐍃 𐌹𐌴𐍃𐌿𐍃 𐍆𐌰𐌽𐌹 𐌲𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰 𐌾𐌰𐌷 𐌱𐌹𐍃𐌼𐌰𐌹𐍄 𐌼𐌹𐍃 𐌰𐌿𐌲𐍉𐌽𐌰 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌼𐌹𐍃: 𐌲𐌰𐌲𐌲 𐌰𐍆𐌸𐍅𐌰𐌷𐌰𐌽 𐌹𐌽 𐌸𐌰𐍄𐌰 𐍃𐍅𐌿𐌼𐍆𐍃𐌻 𐍃𐌹𐌻𐍉𐌰𐌼𐌹𐍃; 𐌹𐌸 𐌹𐌺 𐌲𐌰𐌻𐌰𐌹𐌸 𐌾𐌰𐌷 𐌱𐌹𐌸𐍅𐌰𐌷𐌰𐌽𐌳𐍃 𐌿𐍃𐍃𐌰𐍈.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, '𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐍈𐌰𐍂 𐌹𐍃𐍄 𐍃𐌰? 𐌹𐌸 𐌹𐍃 𐌵𐌰𐌸: 𐌽𐌹 𐍅𐌰𐌹𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, '𐌲𐌰𐍄𐌹𐌿𐌷𐌰𐌽𐌳 𐌹𐌽𐌰 𐌳𐌿 𐍆𐌰𐍂𐌴𐌹𐍃𐌰𐌹𐌿𐌼, 𐌸𐌰𐌽𐌰 𐍃𐌰𐌴𐌹 𐍅𐌰𐍃 𐌱𐌻𐌹𐌽𐌳𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, '𐍅𐌰𐍃𐌿𐌷 𐌸𐌰𐌽 𐍃𐌰𐌱𐌱𐌰𐍄𐍉, 𐌸𐌰𐌽 𐌸𐌰𐍄𐌰 𐍆𐌰𐌽𐌹 𐌲𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰 𐌹𐌴𐍃𐌿𐍃 𐌾𐌰𐌷 𐌿𐍃𐌻𐌰𐌿𐌺 𐌹𐌼𐌼𐌰 𐌰𐌿𐌲𐍉𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, '𐌰𐍆𐍄𐍂𐌰 𐌸𐌰𐌽 𐍆𐍂𐌴𐌷𐌿𐌽 𐌹𐌽𐌰 𐌾𐌰𐌷 𐌸𐌰𐌹 𐍆𐌰𐍂𐌴𐌹𐍃𐌰𐌹𐌴𐌹𐍃 𐍈𐌰𐌹𐍅𐌰 𐌿𐍃𐍃𐌰𐍈; 𐌹𐌸 𐌹𐍃 𐌵𐌰𐌸 𐌾𐌰𐌷 𐌸𐌰𐌹𐌼: 𐍆𐌰𐌽𐌹 𐌲𐌰𐌻𐌰𐌲𐌹𐌳𐌰 𐌼𐌹𐍃 𐌰𐌽𐌰 𐌰𐌿𐌲𐍉𐌽𐌰 𐌾𐌰𐌷 𐌰𐍆𐌸𐍅𐍉𐌷, 𐌾𐌰𐌷 𐍃𐌰𐌹𐍈𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, '𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌽 𐍃𐌿𐌼𐌰𐌹 𐌸𐌹𐌶𐌴 𐍆𐌰𐍂𐌴𐌹𐍃𐌰𐌹𐌴: 𐍃𐌰 𐌼𐌰𐌽𐌽𐌰 𐌽𐌹𐍃𐍄 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰, 𐌸𐌰𐌽𐌳𐌴 𐍃𐌰𐌱𐌱𐌰𐍄𐌴 𐌳𐌰𐌲𐌰 𐌽𐌹 𐍅𐌹𐍄𐌰𐌹𐌸. 𐍃𐌿𐌼𐌰𐌹𐌷 𐌵𐌴𐌸𐌿𐌽: 𐍈𐌰𐌹𐍅𐌰 𐌼𐌰𐌲 𐌼𐌰𐌽𐌽𐌰 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐍃 𐍃𐍅𐌰𐌻𐌴𐌹𐌺𐍉𐍃 𐍄𐌰𐌹𐌺𐌽𐌹𐌽𐍃 𐍄𐌰𐌿𐌾𐌰𐌽? 𐌾𐌰𐌷 𐌼𐌹𐍃𐍃𐌰𐌵𐌹𐍃𐍃 𐍅𐌰𐍂𐌸 𐌼𐌹𐌸 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, '𐌵𐌴𐌸𐌿𐌽𐌿𐌷 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌿𐍂𐌸𐌹𐍃 𐌱𐌻𐌹𐌽𐌳𐌹𐌽 𐌰𐍆𐍄𐍂𐌰: 𐌸𐌿 𐍈𐌰 𐌵𐌹𐌸𐌹𐍃 𐌱𐌹 𐌸𐌰𐌽𐌰 𐌴𐌹 𐌿𐍃𐌻𐌰𐌿𐌺 𐌸𐌿𐍃 𐌰𐌿𐌲𐍉𐌽𐌰? 𐌹𐌸 𐌹𐍃 𐌵𐌰𐌸𐌿𐌷: 𐌸𐌰𐍄𐌴𐌹 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌿𐍃 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, '𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐌰𐌽 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐌱𐌹 𐌹𐌽𐌰 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃 𐌱𐌻𐌹𐌽𐌳𐍃 𐍅𐌴𐍃𐌹 𐌾𐌰𐌷 𐌿𐍃𐍃𐌴𐍈𐌹, 𐌿𐌽𐍄𐌴 𐌰𐍄𐍅𐍉𐍀𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐌰𐌽𐍃 𐍆𐌰𐌳𐍂𐌴𐌹𐌽 𐌹𐍃, 𐌸𐌹𐍃 𐌿𐍃𐍃𐌰𐌹𐍈𐌰𐌽𐌳𐌹𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, '𐌾𐌰𐌷 𐍆𐍂𐌴𐌷𐌿𐌽 𐌹𐌽𐍃 𐌵𐌹𐌸𐌰𐌽𐌳𐌰𐌽𐍃: 𐍃𐌰𐌿 𐌹𐍃𐍄 𐍃𐌰 𐍃𐌿𐌽𐌿𐍃 𐌹𐌶𐍅𐌰𐍂 𐌸𐌰𐌽𐌴𐌹 𐌾𐌿𐍃 𐌵𐌹𐌸𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌱𐌻𐌹𐌽𐌳𐍃 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐍃 𐍅𐌰𐌿𐍂𐌸𐌹? 𐍈𐌰𐌹𐍅𐌰 𐌽𐌿 𐍃𐌰𐌹𐍈𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, '𐌰𐌽𐌳𐌷𐍉𐍆𐌿𐌽 𐌸𐌰𐌽 𐌹𐌼 𐌸𐌰𐌹 𐍆𐌰𐌳𐍂𐌴𐌹𐌽 𐌹𐍃 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽: 𐍅𐌹𐍄𐌿𐌼 𐌸𐌰𐍄𐌴𐌹 𐍃𐌰 𐌹𐍃𐍄 𐍃𐌿𐌽𐌿𐍃 𐌿𐌽𐍃𐌰𐍂, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌴𐌹 𐌱𐌻𐌹𐌽𐌳𐍃 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐍃 𐍅𐌰𐍂𐌸;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, '𐌹𐌸 𐍈𐌰𐌹𐍅𐌰 𐌽𐌿 𐍃𐌰𐌹𐍈𐌹𐌸 𐌽𐌹 𐍅𐌹𐍄𐌿𐌼, 𐌰𐌹𐌸𐌸𐌰𐌿 𐍈𐌰𐍃 𐌿𐍃𐌻𐌰𐌿𐌺 𐌹𐌼𐌼𐌰 𐌸𐍉 𐌰𐌿𐌲𐍉𐌽𐌰 𐍅𐌴𐌹𐍃 𐌽𐌹 𐍅𐌹𐍄𐌿𐌼; 𐍃𐌹𐌻𐌱𐌰 𐌿𐍃𐍅𐌰𐌷𐍃𐌰𐌽𐍃 𐌹𐍃𐍄, 𐌹𐌽𐌰 𐍆𐍂𐌰𐌹𐌷𐌽𐌹𐌸, 𐍃𐌹𐌻𐌱𐌰 𐌱𐌹 𐍃𐌹𐌺 𐍂𐍉𐌳𐌾𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, '𐌸𐌰𐍄𐌰 𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌹 𐍆𐌰𐌳𐍂𐌴𐌹𐌽 𐌹𐍃, 𐌿𐌽𐍄𐌴 𐍉𐌷𐍄𐌴𐌳𐌿𐌽 𐍃𐌹𐍃 𐌹𐌿𐌳𐌰𐌹𐌿𐌽𐍃; 𐌾𐌿𐌸𐌰𐌽 𐌰𐌿𐌺 𐌲𐌰𐌵𐌴𐌸𐌿𐌽 𐍃𐌹𐍃 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃, 𐌴𐌹, 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐌹𐌽𐌰 𐌰𐌽𐌳𐌷𐌰𐌹𐌷𐌰𐌹𐍄𐌹 𐍇𐍂𐌹𐍃𐍄𐌿, 𐌿𐍄𐌰𐌽𐌰 𐍃𐍅𐌽𐌰𐌲𐍉𐌲𐌰𐌹𐍃 𐍅𐌰𐌹𐍂𐌸𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, '𐌳𐌿𐌷𐌸𐌴 𐌸𐌰𐌹 𐌱𐌴𐍂𐌿𐍃𐌾𐍉𐍃 𐌹𐍃 𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐍄𐌴𐌹 𐌿𐍃𐍅𐌰𐌷𐍃𐌰𐌽𐍃 𐌹𐍃𐍄, 𐍃𐌹𐌻𐌱𐌰𐌽 𐍆𐍂𐌰𐌹𐌷𐌽𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, '𐌰𐍄𐍅𐍉𐍀𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐌰𐌽 𐌰𐌽𐌸𐌰𐍂𐌰𐌼𐌼𐌰 𐍃𐌹𐌽𐌸𐌰 𐌸𐌰𐌽𐌰 𐌼𐌰𐌽𐌽𐌰𐌽 𐍃𐌰𐌴𐌹 𐍅𐌰𐍃 𐌱𐌻𐌹𐌽𐌳𐍃, 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌲𐌹𐍆 𐌷𐌰𐌿𐌷𐌴𐌹𐌽 𐌲𐌿𐌳𐌰! 𐍅𐌴𐌹𐍃 𐍅𐌹𐍄𐌿𐌼 𐌸𐌰𐍄𐌴𐌹 𐍃𐌰 𐌼𐌰𐌽𐌽𐌰 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐍃 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, '𐌸𐌰𐌽𐌿𐌷 𐌰𐌽𐌳𐌷𐍉𐍆 𐌾𐌰𐌹𐌽𐍃: 𐌾𐌰𐌱𐌰𐌹 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐍃 𐌹𐍃𐍄, 𐌹𐌺 𐌽𐌹 𐍅𐌰𐌹𐍄; 𐌸𐌰𐍄~𐌰𐌹𐌽 𐍅𐌰𐌹𐍄 𐌴𐌹 𐌱𐌻𐌹𐌽𐌳𐍃 𐍅𐌰𐍃, 𐌹𐌸 𐌽𐌿 𐍃𐌰𐌹𐍈𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌰𐍆𐍄𐍂𐌰: 𐍈𐌰 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌸𐌿𐍃? 𐍈𐌰𐌹𐍅𐌰 𐌿𐍃𐌻𐌰𐌿𐌺 𐌸𐌿𐍃 𐌰𐌿𐌲𐍉𐌽𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌼: 𐌵𐌰𐌸 𐌹𐌶𐍅𐌹𐍃 𐌾𐌿 𐌾𐌰𐌷 𐌽𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌸; 𐍈𐌰 𐌰𐍆𐍄𐍂𐌰 𐍅𐌹𐌻𐌴𐌹𐌸 𐌷𐌰𐌿𐍃𐌾𐌰𐌽? 𐌹𐌱𐌰𐌹 𐌾𐌰𐌷 𐌾𐌿𐍃 𐍅𐌹𐌻𐌴𐌹𐌸 𐌸𐌰𐌼𐌼𐌰 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐍅𐌰𐌹𐍂𐌸𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, '𐌸𐌰𐌽𐌿𐌷 𐌻𐌰𐌹𐌻𐍉𐌿𐌽 𐌹𐌼𐌼𐌰 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽: 𐌸𐌿 𐌹𐍃 𐍃𐌹𐍀𐍉𐌽𐌴𐌹𐍃 𐌸𐌰𐌼𐌼𐌰, 𐌹𐌸 𐍅𐌴𐌹𐍃 𐌼𐍉𐍃𐌴 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐍃𐌹𐌾𐌿𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, '𐍅𐌴𐌹𐍃 𐍅𐌹𐍄𐌿𐌼 𐌸𐌰𐍄𐌴𐌹 𐌳𐌿 𐌼𐍉𐍃𐌴 𐍂𐍉𐌳𐌹𐌳𐌰 𐌲𐌿𐌸, 𐌹𐌸 𐌸𐌰𐌽𐌰 𐌽𐌹 𐌺𐌿𐌽𐌽𐌿𐌼, 𐍈𐌰𐌸𐍂𐍉 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, '𐌰𐌽𐌳𐌷𐍉𐍆 𐍃𐌰 𐌼𐌰𐌽𐌽𐌰 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼: 𐌰𐌿𐌺 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍃𐌹𐌻𐌳𐌰𐌻𐌴𐌹𐌺 𐌹𐍃𐍄, 𐌸𐌰𐍄𐌴𐌹 𐌾𐌿𐍃 𐌽𐌹 𐍅𐌹𐍄𐌿𐌸 𐍈𐌰𐌸𐍂𐍉 𐌹𐍃𐍄, 𐌾𐌰𐌷 𐌿𐍃𐌻𐌰𐌿𐌺 𐌼𐌹𐍃 𐌰𐌿𐌲𐍉𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, '𐍅𐌹𐍄𐌿𐌼𐌿𐌷 𐌸𐌰𐌽 𐌸𐌰𐍄𐌴𐌹 𐌲𐌿𐌸 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰𐌹𐌼 𐌽𐌹 𐌰𐌽𐌳𐌷𐌰𐌿𐍃𐌴𐌹𐌸, 𐌰𐌺 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐌲𐌿𐌳𐌱𐌻𐍉𐍃𐍄𐍂𐌴𐌹𐍃 𐌹𐍃𐍄 𐌾𐌰𐌷 𐍅𐌹𐌻𐌾𐌰𐌽 𐌹𐍃 𐍄𐌰𐌿𐌾𐌹𐌸, 𐌸𐌰𐌼𐌼𐌰 𐌷𐌰𐌿𐍃𐌴𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, '𐍆𐍂𐌰𐌼 𐌰𐌹𐍅𐌰 𐌽𐌹 𐌲𐌰𐌷𐌰𐌿𐍃𐌹𐌸 𐍅𐌰𐍃 𐌸𐌰𐍄𐌴𐌹 𐌿𐍃𐌻𐌿𐌺𐌹𐌸 𐍈𐌰𐍃 𐌰𐌿𐌲𐍉𐌽𐌰 𐌱𐌻𐌹𐌽𐌳𐌰𐌼𐌼𐌰 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐌰𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, '𐌽𐌹𐌷 𐍅𐌴𐍃𐌹 𐍃𐌰 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰, 𐌽𐌹 𐌼𐌰𐌷𐍄𐌴𐌳𐌹 𐍄𐌰𐌿𐌾𐌰𐌽 𐌽𐌹 𐍅𐌰𐌹𐌷𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, '𐌰𐌽𐌳𐌷𐍉𐍆𐌿𐌽 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌹𐌽 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌹𐌼 𐌸𐌿 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐍃 𐍅𐌰𐍂𐍃𐍄 𐌰𐌻𐌻𐍃 𐌾𐌰𐌷 𐌸𐌿 𐌻𐌰𐌹𐍃𐌴𐌹𐍃 𐌿𐌽𐍃𐌹𐍃? 𐌾𐌰𐌷 𐌿𐍃𐍅𐌰𐌿𐍂𐍀𐌿𐌽 𐌹𐌼𐌼𐌰 𐌿𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, '𐌷𐌰𐌿𐍃𐌹𐌳𐌰 𐌹𐌴𐍃𐌿𐍃 𐌸𐌰𐍄𐌴𐌹 𐌿𐍃𐍅𐌰𐌿𐍂𐍀𐌿𐌽 𐌹𐌼𐌼𐌰 𐌿𐍄, 𐌾𐌰𐌷 𐌱𐌹𐌲𐌰𐍄 𐌹𐌽𐌰 𐌵𐌰𐌸𐌿𐌷 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌸𐌿 𐌲𐌰~𐌿~𐌻𐌰𐌿𐌱𐌴𐌹𐍃 𐌳𐌿 𐍃𐌿𐌽𐌰𐌿 𐌲𐌿𐌳𐌹𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌾𐌰𐌹𐌽𐍃 𐌾𐌰𐌷 𐌵𐌰𐌸: 𐌰𐌽 𐍈𐌰𐍃 𐌹𐍃𐍄, 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌿 𐌳𐌿 𐌹𐌼𐌼𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, '𐌵𐌰𐌸 𐌸𐌰𐌽 𐌹𐌼𐌼𐌰 𐌹𐌴𐍃𐌿𐍃: 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐍈𐍄 𐌹𐌽𐌰 𐌾𐌰𐌷 𐍃𐌰𐌴𐌹 𐍂𐍉𐌳𐌴𐌹𐌸 𐌼𐌹𐌸 𐌸𐌿𐍃, 𐍃𐌰 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, '𐌹𐌸 𐌹𐍃 𐌵𐌰𐌸𐌿𐌷: 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰, 𐍆𐍂𐌰𐌿𐌾𐌰; 𐌾𐌰𐌷 𐌹𐌽𐍅𐌰𐌹𐍄 𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, '𐌾𐌰𐌷 𐌵𐌰𐌸 𐌹𐌴𐍃𐌿𐍃: 𐌳𐌿 𐍃𐍄𐌰𐌿𐌰𐌹 𐌹𐌺 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌵𐌰𐌼, 𐌴𐌹 𐌸𐌰𐌹 𐌿𐌽𐍃𐌰𐌹𐍈𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐌰𐌹𐍈𐌰𐌹𐌽𐌰 𐌾𐌰𐌷 𐌸𐌰𐌹 𐍃𐌰𐌹𐍈𐌰𐌽𐌳𐌰𐌽𐍃 𐌱𐌻𐌹𐌽𐌳𐌰𐌹 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, '𐌾𐌰𐌷 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐌹𐌶𐌴 𐍆𐌰𐍂𐌴𐌹𐍃𐌰𐌹𐌴 𐍃𐌿𐌼𐌰𐌹 𐌸𐌰𐍄𐌰, 𐌸𐌰𐌹 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰, 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌹𐌱𐌰𐌹 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃 𐌱𐌻𐌹𐌽𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌼?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, '𐌵𐌰𐌸 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌸 𐌱𐌻𐌹𐌽𐌳𐌰𐌹 𐍅𐌴𐍃𐌴𐌹𐌸, 𐌽𐌹 𐌸𐌰𐌿 𐌷𐌰𐌱𐌰𐌹𐌳𐌴𐌳𐌴𐌹𐌸 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌰𐌹𐍃; 𐌹𐌸 𐌽𐌿 𐌵𐌹𐌸𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌼; 𐌴𐌹𐌸𐌰𐌽 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐌸𐌰𐌹𐍂𐌷𐍅𐌹𐍃𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃, 𐍃𐌰𐌴𐌹 𐌹𐌽𐌽 𐌽𐌹 𐌰𐍄𐌲𐌰𐌲𐌲𐌹𐌸 𐌸𐌰𐌹𐍂𐌷 𐌳𐌰𐌿𐍂 𐌹𐌽 𐌲𐌰𐍂𐌳𐌰𐌽 𐌻𐌰𐌼𐌱𐌴, 𐌰𐌺 𐍃𐍄𐌴𐌹𐌲𐌹𐌸 𐌰𐌻𐌾𐌰𐌸𐍂𐍉, 𐍃𐌰𐌷 𐌷𐌻𐌹𐍆𐍄𐌿𐍃 𐌹𐍃𐍄 𐌾𐌰𐌷 𐍅𐌰𐌹𐌳𐌴𐌳𐌾𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, '𐌹𐌸 𐍃𐌰 𐌹𐌽𐌽𐌲𐌰𐌲𐌲𐌰𐌽𐌳𐍃 𐌸𐌰𐌹𐍂𐌷 𐌳𐌰𐌿𐍂 𐌷𐌰𐌹𐍂𐌳𐌴𐌹𐍃 𐌹𐍃𐍄 𐌻𐌰𐌼𐌱𐌴.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, '𐌸𐌰𐌼𐌼𐌿𐌷 𐌳𐌰𐌿𐍂𐌰𐍅𐌰𐍂𐌳𐍃 𐌿𐍃𐌻𐌿𐌺𐌹𐌸, 𐌾𐌰𐌷 𐌸𐍉 𐌻𐌰𐌼𐌱𐌰 𐍃𐍄𐌹𐌱𐌽𐌰𐌹 𐌹𐍃 𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳, 𐌾𐌰𐌷 𐌸𐍉 𐍃𐍅𐌴𐍃𐍉𐌽𐌰 𐌻𐌰𐌼𐌱𐌰 𐌷𐌰𐌹𐍄𐌹𐌸 𐌱𐌹 𐌽𐌰𐌼𐌹𐌽 𐌾𐌰𐌷 𐌿𐍃𐍄𐌹𐌿𐌷𐌹𐌸 𐌸𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, '𐌾𐌰𐌷 𐌸𐌰𐌽 𐌸𐍉 𐍃𐍅𐌴𐍃𐍉𐌽𐌰 𐌿𐍃𐍄𐌹𐌿𐌷𐌹𐌸, 𐍆𐌰𐌿𐍂𐌰 𐌹𐌼 𐌲𐌰𐌲𐌲𐌹𐌸, 𐌾𐌰𐌷 𐌸𐍉 𐌻𐌰𐌼𐌱𐌰 𐌹𐌽𐌰 𐌻𐌰𐌹𐍃𐍄𐌾𐌰𐌽𐌳, 𐌿𐌽𐍄𐌴 𐌺𐌿𐌽𐌽𐌿𐌽 𐍃𐍄𐌹𐌱𐌽𐌰 𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, '𐌹𐌸 𐍆𐍂𐌰𐌼𐌰𐌸𐌾𐌰𐌽𐌰 𐌽𐌹 𐌻𐌰𐌹𐍃𐍄𐌾𐌰𐌽𐌳, 𐌰𐌺 𐌸𐌻𐌹𐌿𐌷𐌰𐌽𐌳 𐍆𐌰𐌿𐍂𐌰 𐌹𐌼𐌼𐌰, 𐌿𐌽𐍄𐌴 𐌽𐌹 𐌺𐌿𐌽𐌽𐌿𐌽 𐌸𐌹𐌶𐌴 𐍆𐍂𐌰𐌼𐌰𐌸𐌾𐌰𐌽𐌴 𐍃𐍄𐌹𐌱𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, '𐌸𐍉 𐌲𐌰𐌾𐌿𐌺𐍉𐌽 𐌵𐌰𐌸 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌸 𐌾𐌰𐌹𐌽𐌰𐌹 𐌽𐌹 𐍆𐍂𐍉𐌸𐌿𐌽 𐍈𐌰 𐍅𐌰𐍃, 𐌸𐌰𐍄𐌴𐌹 𐍂𐍉𐌳𐌹𐌳𐌰 𐌳𐌿 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌰𐌸 𐌰𐍆𐍄𐍂𐌰 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽, 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌼 𐌳𐌰𐌿𐍂 𐌸𐌹𐌶𐌴 𐌻𐌰𐌼𐌱𐌴.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, '𐌰𐌻𐌻𐌰𐌹 𐍃𐍅𐌰 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐍃𐍅𐌴 𐌵𐌴𐌼𐌿𐌽, 𐌸𐌹𐌿𐌱𐍉𐍃 𐍃𐌹𐌽𐌳 𐌾𐌰𐌷 𐍅𐌰𐌹𐌳𐌴𐌳𐌾𐌰𐌽𐍃; 𐌰𐌺𐌴𐌹 𐌽𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌽 𐌹𐌼 𐌸𐍉 𐌻𐌰𐌼𐌱𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, '𐌹𐌺 𐌹𐌼 𐌸𐌰𐍄𐌰 𐌳𐌰𐌿𐍂. 𐌸𐌰𐌹𐍂𐌷 𐌼𐌹𐌺 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐌹𐌽𐌽𐌲𐌰𐌲𐌲𐌹𐌸, 𐌲𐌰𐌽𐌹𐍃𐌹𐌸, 𐌾𐌰𐌷 𐌹𐌽𐌽𐌲𐌰𐌲𐌲𐌹𐌸 𐌾𐌰𐌷 𐌿𐍄𐌲𐌰𐌲𐌲𐌹𐌸 𐌾𐌰𐌷 𐍅𐌹𐌽𐌾𐌰 𐌱𐌹𐌲𐌹𐍄𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, '𐌸𐌹𐌿𐌱𐍃 𐌽𐌹 𐌵𐌹𐌼𐌹𐌸, 𐌽𐌹𐌱𐌰𐌹 𐌴𐌹 𐍃𐍄𐌹𐌻𐌰𐌹 𐌾𐌰𐌷 𐌿𐍆𐍃𐌽𐌴𐌹𐌸𐌰𐌹 𐌾𐌰𐌷 𐍆𐍂𐌰𐌵𐌹𐍃𐍄𐌾𐌰𐌹; 𐌹𐌸 𐌹𐌺 𐌵𐌰𐌼, 𐌴𐌹 𐌻𐌹𐌱𐌰𐌹𐌽 𐌰𐌹𐌲𐌴𐌹𐌽𐌰 𐌾𐌰𐌷 𐌼𐌰𐌽𐌰𐌲𐌹𐌶𐍉 𐌰𐌹𐌲𐌴𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, '𐌹𐌺 𐌹𐌼 𐌷𐌰𐌹𐍂𐌳𐌴𐌹𐍃 𐌲𐍉𐌳𐍃. 𐌷𐌰𐌹𐍂𐌳𐌴𐌹𐍃 𐍃𐌰 𐌲𐍉𐌳𐌰 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐍃𐌴𐌹𐌽𐌰 𐌻𐌰𐌲𐌾𐌹𐌸 𐍆𐌰𐌿𐍂 𐌻𐌰𐌼𐌱𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, '𐌹𐌸 𐌰𐍃𐌽𐌴𐌹𐍃 𐌾𐌰𐌷 𐍃𐌰𐌴𐌹 𐌽𐌹𐍃𐍄 𐌷𐌰𐌹𐍂𐌳𐌴𐌹𐍃, 𐌸𐌹𐌶𐌴𐌹 𐌽𐌹 𐍃𐌹𐌽𐌳 𐌻𐌰𐌼𐌱𐌰 𐍃𐍅𐌴𐍃𐌰, 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐌸 𐍅𐌿𐌻𐍆 𐌵𐌹𐌼𐌰𐌽𐌳𐌰𐌽 𐌾𐌰𐌷 𐌱𐌹𐌻𐌴𐌹𐌸𐌹𐌸 𐌸𐌰𐌹𐌼 𐌻𐌰𐌼𐌱𐌰𐌼 𐌾𐌰𐌷 𐌸𐌻𐌹𐌿𐌷𐌹𐌸, 𐌾𐌰𐌷 𐍃𐌰 𐍅𐌿𐌻𐍆𐍃 𐍆𐍂𐌰𐍅𐌹𐌻𐍅𐌹𐌸 𐌸𐍉 𐌾𐌰𐌷 𐌳𐌹𐍃𐍄𐌰𐌷𐌾𐌹𐌸 𐌸𐍉 𐌻𐌰𐌼𐌱𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, '𐌹𐌸 𐍃𐌰 𐌰𐍃𐌽𐌴𐌹𐍃 𐌰𐍆𐌸𐌻𐌹𐌿𐌷𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌰𐍃𐌽𐌴𐌹𐍃 𐌹𐍃𐍄 𐌾𐌰𐌷 𐌽𐌹 𐌺𐌰𐍂~𐌹𐍃𐍄 𐌹𐌽𐌰 𐌸𐌹𐌶𐌴 𐌻𐌰𐌼𐌱𐌴.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, '𐌹𐌺 𐌹𐌼 𐌷𐌰𐌹𐍂𐌳𐌴𐌹𐍃 𐍃𐌰 𐌲𐍉𐌳𐌰 𐌾𐌰𐌷 𐌺𐌰𐌽𐌽 𐌼𐌴𐌹𐌽𐌰 𐌾𐌰𐌷 𐌺𐌿𐌽𐌽𐌿𐌽 𐌼𐌹𐌺 𐌸𐍉 𐌼𐌴𐌹𐌽𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, '𐍃𐍅𐌰𐍃𐍅𐌴 𐌺𐌰𐌽𐌽 𐌼𐌹𐌺 𐌰𐍄𐍄𐌰 𐌾𐌰𐌷 𐌹𐌺 𐌺𐌰𐌽𐌽 𐌰𐍄𐍄𐌰𐌽, 𐌾𐌰𐌷 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐌼𐌴𐌹𐌽𐌰 𐌻𐌰𐌲𐌾𐌰 𐍆𐌰𐌿𐍂 𐌸𐍉 𐌻𐌰𐌼𐌱𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, '𐌾𐌰𐌷 𐌰𐌽𐌸𐌰𐍂𐌰 𐌻𐌰𐌼𐌱𐌰 𐌰𐌹𐌷 𐌸𐍉𐌴𐌹 𐌽𐌹 𐍃𐌹𐌽𐌳 𐌸𐌹𐍃 𐌰𐍅𐌹𐍃𐍄𐍂𐌹𐍃, 𐌾𐌰𐌷 𐌸𐍉 𐍃𐌺𐌰𐌻 𐌱𐍂𐌹𐌲𐌲𐌰𐌽, 𐌾𐌰𐌷 𐍃𐍄𐌹𐌱𐌽𐍉𐍃 𐌼𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃 𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳, 𐌾𐌰𐌷 𐍅𐌰𐌹𐍂𐌸𐌰𐌽𐌳 𐌰𐌹𐌽 𐌰𐍅𐌴𐌸𐌹, 𐌰𐌹𐌽𐍃 𐌷𐌰𐌹𐍂𐌳𐌴𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, '𐌳𐌿𐌷𐌸𐌴 𐌰𐍄𐍄𐌰 𐌼𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌸, 𐌿𐌽𐍄𐌴 𐌹𐌺 𐌻𐌰𐌲𐌾𐌰 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐌼𐌴𐌹𐌽𐌰, 𐌴𐌹 𐌰𐍆𐍄𐍂𐌰 𐌽𐌹𐌼𐌰𐌿 𐌸𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, '𐌽𐌹 𐍈𐌰𐍃𐌷𐌿𐌽 𐌽𐌹𐌼𐌹𐌸 𐌸𐍉 𐌰𐍆 𐌼𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽; 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐌷𐌰𐌱𐌰 𐌰𐍆𐌻𐌰𐌲𐌾𐌰𐌽 𐌸𐍉, 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐌷𐌰𐌱𐌰 𐌰𐍆𐍄𐍂𐌰 𐌽𐌹𐌼𐌰𐌽 𐌸𐍉. 𐌸𐍉 𐌰𐌽𐌰𐌱𐌿𐍃𐌽 𐌽𐌰𐌼 𐌰𐍄 𐌰𐍄𐍄𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, '𐌸𐌰𐌽𐌿𐌷 𐌼𐌹𐍃𐍃𐌰𐌵𐌹𐍃𐍃 𐌰𐍆𐍄𐍂𐌰 𐍅𐌰𐍂𐌸 𐌼𐌹𐌸 𐌹𐌿𐌳𐌰𐌹𐌿𐌼 𐌹𐌽 𐌸𐌹𐌶𐌴 𐍅𐌰𐌿𐍂𐌳𐌴.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, '𐌵𐌴𐌸𐌿𐌽𐌿𐌷 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌹𐌶𐌴: 𐌿𐌽𐌷𐌿𐌻𐌸𐍉𐌽 𐌷𐌰𐌱𐌰𐌹𐌸 𐌾𐌰𐌷 𐌳𐍅𐌰𐌻𐌼𐍉𐌸; 𐍈𐌰 𐌸𐌰𐌼𐌼𐌰 𐌷𐌰𐌿𐍃𐌴𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, '𐍃𐌿𐌼𐌰𐌹𐌷 𐌵𐌴𐌸𐌿𐌽: 𐌸𐍉 𐍅𐌰𐌿𐍂𐌳𐌰 𐌽𐌹 𐍃𐌹𐌽𐌳 𐌿𐌽𐌷𐌿𐌻𐌸𐍉𐌽 𐌷𐌰𐌱𐌰𐌽𐌳𐌹𐌽𐍃; 𐌹𐌱𐌰𐌹 𐌼𐌰𐌲 𐌿𐌽𐌷𐌿𐌻𐌸𐍉 𐌱𐌻𐌹𐌽𐌳𐌰𐌹𐌼 𐌰𐌿𐌲𐍉𐌽𐌰 𐌿𐍃𐌻𐌿𐌺𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, '𐍅𐌰𐍂𐌸 𐌸𐌰𐌽 𐌹𐌽𐌽𐌹𐌿𐌾𐌹𐌸𐌰 𐌹𐌽 𐌹𐌰𐌹𐍂𐌿𐍃𐌰𐌿𐌻𐍅𐌼𐌰𐌹, 𐌾𐌰𐌷 𐍅𐌹𐌽𐍄𐍂𐌿𐍃 𐍅𐌰𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, '𐌾𐌰𐌷 𐍈𐌰𐍂𐌱𐍉𐌳𐌰 𐌹𐌴𐍃𐌿𐍃 𐌹𐌽 𐌰𐌻𐌷 𐌹𐌽 𐌿𐌱𐌹𐌶𐍅𐌰𐌹 𐍃𐌰𐌿𐌻𐌰𐌿𐌼𐍉𐌽𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, '𐌸𐌰𐌽𐌿𐌷 𐌱𐌹𐍂𐌿𐌽𐌽𐌿𐌽 𐌹𐌽𐌰 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌿𐌽𐌳 𐍈𐌰 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐌿𐌽𐍃𐌰𐍂𐌰 𐌷𐌰𐌷𐌹𐍃? 𐌾𐌰𐌱𐌰𐌹 𐌸𐌿 𐍃𐌹𐌾𐌰𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌿𐍃, 𐌵𐌹𐌸 𐌿𐌽𐍃𐌹𐍃 𐌰𐌽𐌳𐌰𐌿𐌲𐌹𐌱𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌵𐌰𐌸 𐌹𐌶𐍅𐌹𐍃, 𐌾𐌰𐌷 𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸; 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌸𐍉𐌴𐌹 𐌹𐌺 𐍄𐌰𐌿𐌾𐌰 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌰𐍄𐍄𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐌹𐍃, 𐌸𐍉 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰𐌽𐌳 𐌱𐌹 𐌼𐌹𐌺;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, '𐌰𐌺𐌴𐌹 𐌾𐌿𐍃 𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌽𐌹 𐍃𐌹𐌾𐌿𐌸 𐌻𐌰𐌼𐌱𐌴 𐌼𐌴𐌹𐌽𐌰𐌹𐌶𐌴, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌵𐌰𐌸 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, '𐌻𐌰𐌼𐌱𐌰 𐌼𐌴𐌹𐌽𐌰 𐍃𐍄𐌹𐌱𐌽𐌰𐌹 𐌼𐌴𐌹𐌽𐌰𐌹 𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳, 𐌾𐌰𐌷 𐌹𐌺 𐌺𐌰𐌽𐌽 𐌸𐍉, 𐌾𐌰𐌷 𐌻𐌰𐌹𐍃𐍄𐌾𐌰𐌽𐌳 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, '𐌾𐌰𐌷 𐌹𐌺 𐌻𐌹𐌱𐌰𐌹𐌽 𐌰𐌹𐍅𐌴𐌹𐌽𐍉𐌽 𐌲𐌹𐌱𐌰 𐌹𐌼, 𐌾𐌰𐌷 𐌽𐌹 𐍆𐍂𐌰𐌵𐌹𐍃𐍄𐌽𐌰𐌽𐌳 𐌰𐌹𐍅; 𐌾𐌰𐌷 𐌽𐌹 𐍆𐍂𐌰𐍅𐌹𐌻𐍅𐌹𐌸 𐍈𐌰𐍃𐌷𐌿𐌽 𐌸𐍉 𐌿𐍃 𐌷𐌰𐌽𐌳𐌰𐌿 𐌼𐌴𐌹𐌽𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, '𐌰𐍄𐍄𐌰 𐌼𐌴𐌹𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐍆𐍂𐌰𐌲𐌰𐍆 𐌼𐌹𐍃, 𐌼𐌰𐌹𐌶𐍉 𐌰𐌻𐌻𐌰𐌹𐌼 𐌹𐍃𐍄, 𐌾𐌰𐌷 𐌽𐌹 𐌰𐌹𐍅 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌼𐌰𐌲 𐍆𐍂𐌰𐍅𐌹𐌻𐍅𐌰𐌽 𐌸𐍉 𐌿𐍃 𐌷𐌰𐌽𐌳𐌰𐌿 𐌰𐍄𐍄𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, '𐌹𐌺 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌼𐌴𐌹𐌽𐍃 𐌰𐌹𐌽 𐍃𐌹𐌾𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, '𐌽𐌴𐌼𐌿𐌽 𐌰𐍆𐍄𐍂𐌰 𐍃𐍄𐌰𐌹𐌽𐌰𐌽𐍃 𐌸𐌰𐌹 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃, 𐌴𐌹 𐍅𐌰𐌿𐍂𐍀𐌴𐌹𐌽𐌰 𐌰𐌽𐌰 𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌼𐌰𐌽𐌰𐌲𐌰 𐌲𐍉𐌳𐌰 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌰𐍄𐌰𐌿𐌲𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌿𐍃 𐌰𐍄𐍄𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌹𐌽 𐍈𐌰𐍂𐌾𐌹𐍃 𐌸𐌹𐌶𐌴 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌴 𐍃𐍄𐌰𐌹𐌽𐌴𐌹𐌸 𐌼𐌹𐌺?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, '𐌰𐌽𐌳𐌷𐍉𐍆𐌿𐌽 𐌹𐌼𐌼𐌰 𐌸𐌰𐌹 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃: 𐌹𐌽 𐌲𐍉𐌳𐌹𐍃 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌹𐍃 𐌽𐌹 𐍃𐍄𐌰𐌹𐌽𐌾𐌰𐌼 𐌸𐌿𐌺, 𐌰𐌺 𐌹𐌽 𐍅𐌰𐌾𐌰𐌼𐌴𐍂𐌴𐌹𐌽𐍃, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌴𐌹 𐌸𐌿 𐌼𐌰𐌽𐌽𐌰 𐍅𐌹𐍃𐌰𐌽𐌳𐍃 𐍄𐌰𐌿𐌾𐌹𐍃 𐌸𐌿𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐌳𐌿 𐌲𐌿𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌽𐌹𐌿 𐌹𐍃𐍄 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐌽 𐍅𐌹𐍄𐍉𐌳𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰: 𐌹𐌺 𐌵𐌰𐌸, 𐌲𐌿𐌳𐌰 𐍃𐌹𐌾𐌿𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, '𐌾𐌰𐌱𐌰𐌹 𐌾𐌰𐌹𐌽𐌰𐌽𐍃 𐌵𐌰𐌸 𐌲𐌿𐌳𐌰, 𐌳𐌿 𐌸𐌰𐌹𐌼𐌴𐌹 𐍅𐌰𐌿𐍂𐌳 𐌲𐌿𐌳𐌹𐍃 𐍅𐌰𐍂𐌸, 𐌾𐌰𐌷 𐌽𐌹 𐌼𐌰𐌷𐍄 𐌹𐍃𐍄 𐌲𐌰𐍄𐌰𐌹𐍂𐌰𐌽 𐌸𐌰𐍄𐌰 𐌲𐌰𐌼𐌴𐌻𐌹𐌳𐍉;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, '𐌸𐌰𐌽𐌴𐌹 𐌰𐍄𐍄𐌰 𐌲𐌰𐍅𐌴𐌹𐌷𐌰𐌹𐌳𐌰 𐌾𐌰𐌷 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌹𐌽 𐌸𐌰𐌽𐌰 𐍆𐌰𐌹𐍂𐍈𐌿, 𐌾𐌿𐍃 𐌵𐌹𐌸𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐍅𐌰𐌾𐌰𐌼𐌴𐍂𐌾𐌰𐌿, 𐌿𐌽𐍄𐌴 𐌵𐌰𐌸: 𐍃𐌿𐌽𐌿𐍃 𐌲𐌿𐌳𐌹𐍃 𐌹𐌼?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, '𐌽𐌹𐌱𐌰 𐍄𐌰𐌿𐌾𐌰𐌿 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌰𐍄𐍄𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐌹𐍃, 𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌼𐌹𐍃;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, '𐌹𐌸 𐌾𐌰𐌱𐌰𐌹 𐍄𐌰𐌿𐌾𐌰𐌿, 𐌽𐌹𐌱𐌰 𐌼𐌹𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌹𐌸, 𐌸𐌰𐌹𐌼 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌹𐌸, 𐌴𐌹 𐌿𐍆𐌺𐌿𐌽𐌽𐌰𐌹𐌸 𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌹𐌽 𐌼𐌹𐍃 𐌰𐍄𐍄𐌰 𐌾𐌰𐌷 𐌹𐌺 𐌹𐌽 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, '𐍃𐍉𐌺𐌹𐌳𐌴𐌳𐌿𐌽 𐌹𐌽𐌰 𐌰𐍆𐍄𐍂𐌰 𐌲𐌰𐍆𐌰𐌷𐌰𐌽, 𐌾𐌰𐌷 𐌿𐍃𐌹𐌳𐌳𐌾𐌰 𐌿𐍃 𐌷𐌰𐌽𐌳𐌿𐌼 𐌹𐌶𐌴.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, '𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌹𐌸 𐌰𐍆𐍄𐍂𐌰 𐌿𐍆𐌰𐍂 𐌹𐌰𐌿𐍂𐌳𐌰𐌽𐌿 𐌹𐌽 𐌸𐌰𐌽𐌰 𐍃𐍄𐌰𐌳 𐌸𐌰𐍂𐌴𐌹 𐍅𐌰𐍃 𐌹𐍉𐌷𐌰𐌽𐌽𐌴𐍃 𐍆𐍂𐌿𐌼𐌹𐍃𐍄 𐌳𐌰𐌿𐍀𐌾𐌰𐌽𐌳𐍃, 𐌾𐌰𐌷 𐍃𐌰𐌻𐌹𐌳𐌰 𐌾𐌰𐌹𐌽𐌰𐍂.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, '𐌾𐌰𐌷 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌵𐌴𐌼𐌿𐌽 𐌰𐍄 𐌹𐌼𐌼𐌰 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐍄𐌴𐌹 𐌹𐍉𐌷𐌰𐌽𐌽𐌴𐍃 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐍄𐌰𐌹𐌺𐌽𐌴 𐌽𐌹 𐌰𐌹𐌽𐍉𐌷𐌿𐌽; 𐌹𐌸 𐌰𐌻𐌻𐌰𐍄𐌰 𐌸𐌰𐍄𐌴𐌹 𐌵𐌰𐌸 𐌹𐍉𐌷𐌰𐌽𐌽𐌴𐍃 𐌱𐌹 𐌸𐌰𐌽𐌰, 𐍃𐌿𐌽𐌾𐌰 𐍅𐌰𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, '𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌴𐌳𐌿𐌽 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌾𐌰𐌹𐌽𐌰𐍂.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, '𐍅𐌰𐍃𐌿𐌷 𐌸𐌰𐌽 𐍃𐌿𐌼𐍃 𐍃𐌹𐌿𐌺𐍃, 𐌻𐌰𐌶𐌰𐍂𐌿𐍃 𐌰𐍆 𐌱𐌴𐌸𐌰𐌽𐌹𐌰𐍃, 𐌿𐍃 𐌷𐌰𐌹𐌼𐌰𐌹 𐌼𐌰𐍂𐌾𐌹𐌽𐍃 𐌾𐌰𐌷 𐌼𐌰𐍂𐌸𐌹𐌽𐍃, 𐍃𐍅𐌹𐍃𐍄𐍂𐍃 𐌹𐌶𐍉𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '𐍅𐌰𐍃𐌿𐌷 𐌸𐌰𐌽 𐌼𐌰𐍂𐌾𐌰, 𐍃𐍉𐌴𐌹 𐍃𐌰𐌻𐌱𐍉𐌳𐌰 𐍆𐍂𐌰𐌿𐌾𐌰𐌽 𐌱𐌰𐌻𐍃𐌰𐌽𐌰 𐌾𐌰𐌷 𐌱𐌹𐍃𐍅𐌰𐍂𐌱 𐍆𐍉𐍄𐌿𐌽𐍃 𐌹𐍃 𐍃𐌺𐌿𐍆𐍄𐌰 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌸𐌹𐌶𐍉𐌶𐌴𐌹 𐌱𐍂𐍉𐌸𐌰𐍂 𐌻𐌰𐌶𐌰𐍂𐌿𐍃 𐍃𐌹𐌿𐌺𐍃 𐍅𐌰𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, '𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐌰𐌽 𐌸𐍉𐍃 𐍃𐍅𐌹𐍃𐍄𐍂𐌾𐌿𐍃 𐌹𐍃 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌵𐌹𐌸𐌰𐌽𐌳𐌴𐌹𐌽𐍃: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐍃𐌰𐌹, 𐌸𐌰𐌽𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐍃 𐍃𐌹𐌿𐌺𐍃 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, '𐌹𐌸 𐌹𐍃 𐌲𐌰𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐍃 𐌵𐌰𐌸: 𐍃𐍉 𐍃𐌹𐌿𐌺𐌴𐌹 𐌽𐌹𐍃𐍄 𐌳𐌿 𐌳𐌰𐌿𐌸𐌰𐌿, 𐌰𐌺 𐌹𐌽 𐌷𐌰𐌿𐌷𐌴𐌹𐌽𐌰𐌹𐍃 𐌲𐌿𐌳𐌹𐍃, 𐌴𐌹 𐌷𐌰𐌿𐌷𐌾𐌰𐌹𐌳𐌰𐌿 𐍃𐌿𐌽𐌿𐍃 𐌲𐌿𐌳𐌹𐍃 𐌸𐌰𐌹𐍂𐌷 𐌸𐌰𐍄𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, '𐍆𐍂𐌹𐌾𐍉𐌳𐌿𐌷 𐌸𐌰𐌽 𐌹𐌴𐍃𐌿𐍃 𐌼𐌰𐍂𐌸𐌰𐌽 𐌾𐌰𐌷 𐍃𐍅𐌹𐍃𐍄𐌰𐍂 𐌹𐌶𐍉𐍃 𐌾𐌰𐌷 𐌻𐌰𐌶𐌰𐍂𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, '𐍃𐍅𐌴 𐌷𐌰𐌿𐍃𐌹𐌳𐌰 𐌸𐌰𐍄𐌴𐌹 𐍃𐌹𐌿𐌺𐍃 𐍅𐌰𐍃, 𐌸𐌰𐌽𐌿𐌷 𐌸𐌰𐌽 𐍃𐌰𐌻𐌹𐌳𐌰 𐌹𐌽 𐌸𐌰𐌼𐌼𐌴𐌹 𐍅𐌰𐍃 𐍃𐍄𐌰𐌳𐌰 𐍄𐍅𐌰𐌽𐍃 𐌳𐌰𐌲𐌰𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, '𐌸𐌰𐌸𐍂𐍉𐌷 𐌸𐌰𐌽 𐌰𐍆𐌰𐍂 𐌸𐌰𐍄𐌰 𐌵𐌰𐌸 𐌳𐌿 𐍃𐌹𐍀𐍉𐌽𐌾𐌰𐌼: 𐌲𐌰𐌲𐌲𐌰𐌼 𐌹𐌽 𐌹𐌿𐌳𐌰𐌹𐌰𐌽 𐌰𐍆𐍄𐍂𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, '𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌸𐌰𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃: 𐍂𐌰𐌱𐌱𐌴𐌹, 𐌽𐌿 𐍃𐍉𐌺𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐌿𐌺 𐌰𐍆𐍅𐌰𐌹𐍂𐍀𐌰𐌽 𐍃𐍄𐌰𐌹𐌽𐌰𐌼 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃, 𐌾𐌰𐌷 𐌰𐍆𐍄𐍂𐌰 𐌲𐌰𐌲𐌲𐌹𐍃 𐌾𐌰𐌹𐌽𐌳?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌽𐌹𐌿 𐍄𐍅𐌰𐌻𐌹𐍆 𐍃𐌹𐌽𐌳 𐍈𐌴𐌹𐌻𐍉𐍃 𐌳𐌰𐌲𐌹𐍃? 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐌲𐌰𐌲𐌲𐌹𐌸 𐌹𐌽 𐌳𐌰𐌲, 𐌽𐌹 𐌲𐌰𐍃𐍄𐌹𐌲𐌲𐌵𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌻𐌹𐌿𐌷𐌰𐌸 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐌸;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, '𐌰𐌸𐌸𐌰𐌽 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐌲𐌰𐌲𐌲𐌹𐌸 𐌹𐌽 𐌽𐌰𐌷𐍄, 𐌲𐌰𐍃𐍄𐌹𐌲𐌲𐌵𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌻𐌹𐌿𐌷𐌰𐌳 𐌽𐌹𐍃𐍄 𐌹𐌽 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, '𐌸𐍉 𐌵𐌰𐌸 𐌾𐌰𐌷 𐌰𐍆𐌰𐍂 𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌹𐌸 𐌳𐌿 𐌹𐌼: 𐌻𐌰𐌶𐌰𐍂𐌿𐍃, 𐍆𐍂𐌹𐌾𐍉𐌽𐌳𐍃 𐌿𐌽𐍃𐌰𐍂, 𐌲𐌰𐍃𐌰𐌹𐌶𐌻𐌴𐍀; 𐌰𐌺𐌴𐌹 𐌲𐌰𐌲𐌲𐌰𐌼, 𐌴𐌹 𐌿𐍃𐍅𐌰𐌺𐌾𐌰𐌿 𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐌹𐍃: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌾𐌰𐌱𐌰𐌹 𐍃𐌻𐌴𐍀𐌹𐌸, 𐌷𐌰𐌹𐌻𐍃 𐍅𐌰𐌹𐍂𐌸𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, '𐌵𐌰𐌸𐌿𐌷 𐌸𐌰𐌽 𐌹𐌴𐍃𐌿𐍃 𐌱𐌹 𐌳𐌰𐌿𐌸𐌿 𐌹𐍃; 𐌹𐌸 𐌾𐌰𐌹𐌽𐌰𐌹 𐌷𐌿𐌲𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐌰𐍄𐌴𐌹 𐌹𐍃 𐌱𐌹 𐍃𐌻𐌴𐍀 𐌵𐌴𐌸𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, '𐌸𐌰𐌽𐌿𐌷 𐌸𐌰𐌽 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃 𐍃𐍅𐌹𐌺𐌿𐌽𐌸𐌰𐌱𐌰: 𐌻𐌰𐌶𐌰𐍂𐌿𐍃 𐌲𐌰𐍃𐍅𐌰𐌻𐍄,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, '𐌾𐌰𐌷 𐍆𐌰𐌲𐌹𐌽𐍉 𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌽𐌹 𐍅𐌰𐍃 𐌾𐌰𐌹𐌽𐌰𐍂; 𐌰𐌺𐌴𐌹 𐌲𐌰𐌲𐌲𐌰𐌼 𐌳𐌿 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌰𐌸 Þ𐍉𐌼𐌰𐍃 𐍃𐌰𐌴𐌹 𐌷𐌰𐌹𐍄𐌰𐌳𐌰 𐌳𐌹𐌳𐌹𐌼𐌿𐍃 𐌸𐌰𐌹𐌼 𐌲𐌰𐌷𐌻𐌰𐌹𐌱𐌰𐌼 𐍃𐌴𐌹𐌽𐌰𐌹𐌼: 𐌲𐌰𐌲𐌲𐌰𐌼 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃, 𐌴𐌹 𐌲𐌰𐍃𐍅𐌹𐌻𐍄𐌰𐌹𐌼𐌰 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, '𐌵𐌹𐌼𐌰𐌽𐌳𐍃 𐌸𐌰𐌽 𐌹𐌴𐍃𐌿𐍃 𐌱𐌹𐌲𐌰𐍄 𐌹𐌽𐌰 𐌾𐌿𐌸𐌰𐌽 𐍆𐌹𐌳𐍅𐍉𐍂 𐌳𐌰𐌲𐌰𐌽𐍃 𐌷𐌰𐌱𐌰𐌽𐌳𐌰𐌽 𐌹𐌽 𐌷𐌻𐌰𐌹𐍅𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, '𐍅𐌰𐍃𐌿𐌷 𐌸𐌰𐌽 𐌱𐌴𐌸𐌰𐌽𐌹𐌰 𐌽𐌴𐍈𐌰 𐌹𐌰𐌹𐍂𐌿𐍃𐌰𐌿𐌻𐍅𐌼𐌹[𐌰]𐌼, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌰𐌽𐌰 𐍃𐍀𐌰𐌿𐍂𐌳𐌹𐌼 𐍆𐌹𐌼𐍆𐍄𐌰𐌹𐌷𐌿𐌽𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, '𐌾𐌰𐌷 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌹𐌿𐌳𐌰𐌹𐌴 𐌲𐌰𐌵𐌴𐌼𐌿𐌽 𐌱𐌹 𐌼𐌰𐍂𐌸𐌰𐌽 𐌾𐌰𐌷 𐌼𐌰𐍂𐌾𐌰𐌽, 𐌴𐌹 𐌲𐌰𐌸𐍂𐌰𐍆𐍃𐍄𐌹𐌳𐌴𐌳𐌴𐌹𐌽𐌰 𐌹𐌾𐍉𐍃 𐌱𐌹 𐌸𐌰𐌽𐌰 𐌱𐍂𐍉𐌸𐌰𐍂 𐌹𐌶𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, '𐌹𐌸 𐌼𐌰𐍂𐌸𐌰, 𐍃𐌿𐌽𐍃𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌰 𐌸𐌰𐍄𐌴𐌹 𐌹𐌴𐍃𐌿𐍃 𐌵𐌹𐌼𐌹𐌸, 𐍅𐌹𐌸𐍂𐌰ï𐌳𐌳𐌾𐌰 𐌹𐌽𐌰; 𐌹𐌸 𐌼𐌰𐍂𐌾𐌰 𐌹𐌽 𐌲𐌰𐍂𐌳𐌰 𐍃𐌰𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌰𐌸 𐌼𐌰𐍂𐌸𐌰 𐌳𐌿 𐌹𐌴𐍃𐌿𐌰: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌹𐌸 𐍅𐌴𐍃𐌴𐌹𐍃 𐌷𐌴𐍂, 𐌽𐌹 𐌸𐌰𐌿 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐍉𐌳𐌴𐌳𐌹 𐌱𐍂𐍉𐌸𐌰𐍂 𐌼𐌴𐌹𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, '𐌰𐌺𐌴𐌹 𐌾𐌰𐌷 𐌽𐌿 𐍅𐌰𐌹𐍄, 𐌴𐌹 𐌸𐌹𐍃𐍈𐌰𐌷 𐌸𐌴𐌹 𐌱𐌹𐌳𐌾𐌹𐍃 𐌲𐌿𐌸, 𐌲𐌹𐌱𐌹𐌸 𐌸𐌿𐍃 𐌲𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, '𐌵𐌰𐌸 𐌹𐌶𐌰𐌹 𐌹𐌴𐍃𐌿𐍃: 𐌿𐍃𐍃𐍄𐌰𐌽𐌳𐌹𐌸 𐌱𐍂𐍉𐌸𐌰𐍂 𐌸𐌴𐌹𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, '𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌼𐌰𐍂𐌸𐌰: 𐍅𐌰𐌹𐍄 𐌸𐌰𐍄𐌴𐌹 𐌿𐍃𐍃𐍄𐌰𐌽𐌳𐌹𐌸 𐌹𐌽 𐌿𐍃𐍃𐍄𐌰𐍃𐍃𐌰𐌹 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍃𐍀𐌴𐌳𐌹𐍃𐍄𐌹𐌽 𐌳𐌰𐌲𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, '𐌵𐌰𐌸 𐌸𐌰𐌽 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌺 𐌹𐌼 𐍃𐍉 𐌿𐍃𐍃𐍄𐌰𐍃𐍃 𐌾𐌰𐌷 𐌻𐌹𐌱𐌰𐌹𐌽𐍃; 𐍃𐌰𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌳𐌿 𐌼𐌹𐍃, 𐌸𐌰𐌿𐌷 𐌲𐌰~𐌱𐌰~𐌳𐌰𐌿𐌸𐌽𐌹𐌸, 𐌻𐌹𐌱𐌰𐌹𐌳;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, '𐌾𐌰𐌷 𐍈𐌰𐌶𐌿𐌷 𐍃𐌰𐌴𐌹 𐌻𐌹𐌱𐌰𐌹𐌸 𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌳𐌿 𐌼𐌹𐍃, 𐌽𐌹 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐌹𐌸 𐌰𐌹𐍅. 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐍃 𐌸𐌰𐍄𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, '𐌵𐌰𐌸 𐌹𐌼𐌼𐌰: 𐌾𐌰𐌹, 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌹𐌺 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌰 𐌸𐌰𐍄𐌴𐌹 𐌸𐌿 𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌿𐍃, 𐍃𐌿𐌽𐌿𐍃 𐌲𐌿𐌳𐌹𐍃, 𐍃𐌰 𐌹𐌽 𐌸𐌰𐌽𐌰 𐍆𐌰𐌹𐍂𐍈𐌿 𐌵𐌹𐌼𐌰𐌽𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, '𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌰𐌽𐌳𐌴𐌹 𐌲𐌰𐌻𐌰𐌹𐌸 𐌾𐌰𐌷 𐍅𐍉𐍀𐌹𐌳𐌰 𐌼𐌰𐍂𐌾𐌰𐌽, 𐍃𐍅𐌹𐍃𐍄𐌰𐍂 𐍃𐌴𐌹𐌽𐌰, 𐌸𐌹𐌿𐌱𐌾𐍉 𐌵𐌹𐌸𐌰𐌽𐌳𐌴𐌹: 𐌻𐌰𐌹𐍃𐌰𐍂𐌴𐌹𐍃 𐌵𐌰𐌼 𐌾𐌰𐌷 𐌷𐌰𐌹𐍄𐌹𐌸 𐌸𐌿𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, '𐌹𐌸 𐌾𐌰𐌹𐌽𐌰, 𐍃𐌿𐌽𐍃𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌰, 𐌿𐍂𐍂𐌰𐌹𐍃 𐍃𐍀𐍂𐌰𐌿𐍄𐍉 𐌾𐌰𐌷 𐌹𐌳𐌳𐌾𐌰 𐌳𐌿 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, '𐌽𐌹𐌸~𐌸𐌰𐌽 𐌽𐌰𐌿𐌷𐌸𐌰𐌽𐌿𐌷 𐌵𐌰𐌼 𐌹𐌴𐍃𐌿𐍃 𐌹𐌽 𐍅𐌴𐌹𐌷𐍃𐌰, 𐌰𐌺 𐍅𐌰𐍃 𐌽𐌰𐌿𐌷𐌸𐌰𐌽𐌿𐌷 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍃𐍄𐌰𐌳𐌰 𐌸𐌰𐍂𐌴𐌹 𐌲𐌰𐌼𐍉𐍄𐌹𐌳𐌰 𐌹𐌼𐌼𐌰 𐌼𐌰𐍂𐌸𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, '𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐌸𐌰𐌽 𐌸𐌰𐌹 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌼𐌹𐌸 𐌹𐌶𐌰𐌹 𐌹𐌽 𐌲𐌰𐍂𐌳𐌰 𐌸𐍂𐌰𐍆𐍃𐍄𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌾𐌰, 𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽𐌳𐌰𐌽𐍃 𐌼𐌰𐍂𐌾𐌰𐌽 𐌸𐌰𐍄𐌴𐌹 𐍃𐍀𐍂𐌰𐌿𐍄𐍉 𐌿𐍃𐍃𐍄𐍉𐌸 𐌾𐌰𐌷 𐌿𐍃𐌹𐌳𐌳𐌾𐌰, 𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌽𐌿𐌷 𐌰𐍆𐌰𐍂 𐌹𐌶𐌰𐌹 𐌵𐌹𐌸𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐌲𐌲𐌹𐌸 𐌳𐌿 𐌷𐌻𐌰𐌹𐍅𐌰, 𐌴𐌹 𐌲𐍂𐌴𐌹𐍄𐌰𐌹 𐌾𐌰𐌹𐌽𐌰𐍂.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, '𐌹𐌸 𐌼𐌰𐍂𐌾𐌰, 𐍃𐌿𐌽𐍃𐌴𐌹 𐌵𐌰𐌼 𐌸𐌰𐍂𐌴𐌹 𐍅𐌰𐍃 𐌹𐌴𐍃𐌿𐍃, 𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽𐌳𐌴𐌹 𐌹𐌽𐌰 𐌳𐍂𐌰𐌿𐍃 𐌹𐌼𐌼𐌰 𐌳𐌿 𐍆𐍉𐍄𐌿𐌼 𐌵𐌹𐌸𐌰𐌽𐌳𐌴𐌹 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌹𐌸 𐍅𐌴𐌹𐍃𐌴𐌹𐍃 𐌷𐌴𐍂, 𐌽𐌹 𐌸𐌰𐌿𐌷 𐌲𐌰𐍃𐍅𐌿𐌻𐍄𐌹 𐌼𐌴𐌹𐌽𐍃 𐌱𐍂𐍉𐌸𐌰𐍂.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, '𐌸𐌰𐌽𐌿𐌷 𐌹𐌴𐍃𐌿𐍃, 𐍃𐌿𐌽𐍃𐌴𐌹 𐌲𐌰𐍃𐌰𐍈 𐌹𐌾𐌰 𐌲𐍂𐌴𐌹𐍄𐌰𐌽𐌳𐌴𐌹𐌽 𐌾𐌰𐌷 𐌹𐌿𐌳𐌰𐌹𐌿𐌽𐍃 𐌸𐌰𐌹𐌴𐌹 𐌵𐌴𐌼𐌿𐌽 𐌼𐌹𐌸 𐌹𐌶𐌰𐌹 𐌲𐍂𐌴𐍄𐌰𐌽𐌳𐌰𐌽𐍃, 𐌹𐌽𐍂𐌰𐌿𐌷𐍄𐌹𐌳𐌰 𐌰𐌷𐌼𐌹𐌽 𐌾𐌰𐌷 𐌹𐌽𐍅𐌰𐌲𐌹𐌳𐌰 𐍃𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, '𐌾𐌰𐌷 𐌵𐌰𐌸: 𐍈𐌰𐍂 𐌻𐌰𐌲𐌹𐌳𐌴𐌳𐌿𐌸 𐌹𐌽𐌰? 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌷𐌹𐍂𐌹 𐌾𐌰𐌷 𐍃𐌰𐌹𐍈.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, '𐌾𐌰𐌷 𐍄𐌰𐌲𐍂𐌹𐌳𐌰 𐌹𐌴𐍃𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌹 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃: 𐍃𐌰𐌹, 𐍈𐌰𐌹𐍅𐌰 𐍆𐍂𐌹𐍉𐌳𐌰 𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, '𐍃𐌿𐌼𐌰𐌹 𐌸𐌰𐌽 𐌹𐌶𐌴 𐌵𐌴𐌸𐌿𐌽: 𐌽𐌹𐌿 𐌼𐌰𐌷𐍄𐌰 𐍃𐌰 𐌹𐌶𐌴𐌹 𐌿𐍃𐌻𐌰𐌿𐌺 𐌰𐌿𐌲𐍉𐌽𐌰 𐌸𐌰𐌼𐌼𐌰 𐌱𐌻𐌹𐌽𐌳𐌹𐌽 𐌲𐌰𐍄𐌰𐌿𐌾𐌰𐌽 𐌴𐌹 𐌾𐌰𐌷 𐍃𐌰 𐌽𐌹 𐌲𐌰𐌳𐌰𐌿𐌸𐌽𐍉𐌳𐌴𐌳𐌹?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, '𐌸𐌰𐌽𐌿𐌷 𐌹𐌴𐍃𐌿𐍃 𐌰𐍆𐍄𐍂𐌰 𐌹𐌽𐍂𐌰𐌿𐌷𐍄𐌹𐌸𐍃 𐌹𐌽 𐍃𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌲𐌰𐌲𐌲𐌹𐌸 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 𐌷𐌻𐌰𐌹𐍅𐌰. 𐍅𐌰𐍃𐌿𐌷 𐌸𐌰𐌽 𐌷𐌿𐌻𐌿𐌽𐌳𐌹 𐌾𐌰𐌷 𐍃𐍄𐌰𐌹𐌽𐌰 𐌿𐍆𐌰𐍂𐌻𐌰𐌲𐌹𐌳𐌰 𐍅𐌰𐍃 𐌿𐍆𐌰𐍂𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, '𐌵𐌰𐌸 𐌹𐌴𐍃𐌿𐍃: 𐌰𐍆𐌽𐌹𐌼𐌹𐌸 𐌸𐌰𐌽𐌰 𐍃𐍄𐌰𐌹𐌽. 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼𐌼𐌰 𐍃𐍅𐌹𐍃𐍄𐌰𐍂 𐌸𐌹𐍃 𐌳𐌰𐌿𐌸𐌹𐌽𐍃 𐌼𐌰𐍂𐌸𐌰: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌾𐌿 𐍆𐌿𐌻𐍃 𐌹𐍃𐍄; 𐍆𐌹𐌳𐌿𐍂𐌳𐍉𐌲𐍃 𐌰𐌿𐌺 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, '𐌵𐌰𐌸 𐌹𐌶𐌰𐌹 𐌹𐌴𐍃𐌿𐍃: 𐌽𐌹𐌿 𐌵𐌰𐌸 𐌸𐌿𐍃 𐌸𐌰𐍄𐌴𐌹 𐌾𐌰𐌱𐌰𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐍃, 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐍃 𐍅𐌿𐌻𐌸𐌿 𐌲𐌿𐌳𐌹𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, '𐌿𐍃𐌷𐍉𐍆𐌿𐌽 𐌸𐌰𐌽 𐌸𐌰𐌽𐌰 𐍃𐍄𐌰𐌹𐌽 𐌸𐌰𐍂𐌴𐌹 𐍅𐌰𐍃. 𐌹𐌸 𐌹𐌴𐍃𐌿𐍃 𐌿𐌶𐌿𐌷𐌷𐍉𐍆 𐌰𐌿𐌲𐍉𐌽𐌰 𐌹𐌿𐍀 𐌾𐌰𐌷 𐌵𐌰𐌸: 𐌰𐍄𐍄𐌰, 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉 𐌸𐌿𐍃, 𐌿𐌽𐍄𐌴 𐌰𐌽𐌳𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐍃 𐌼𐌹𐍃;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, '𐌾𐌰𐌷 𐌸𐌰𐌽 𐌹𐌺 𐍅𐌹𐍃𐍃𐌰 𐌸𐌰𐍄𐌴𐌹 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌼𐌹𐍃 𐌰𐌽𐌳𐌷𐌰𐌿𐍃𐌴𐌹𐍃; 𐌰𐌺𐌴𐌹 𐌹𐌽 𐌼𐌰𐌽𐌰𐌲𐌴𐌹𐌽𐍃 𐌸𐌹𐌶𐍉𐍃 𐌱𐌹𐍃𐍄𐌰𐌽𐌳𐌰𐌽𐌳𐌴𐌹𐌽𐍃 𐌵𐌰𐌸, 𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌹𐌽𐌰 𐌸𐌰𐍄𐌴𐌹 𐌸𐌿 𐌼𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, '𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌰𐌽𐌳𐍃 𐍃𐍄𐌹𐌱𐌽𐌰𐌹 𐌼𐌹𐌺𐌹𐌻𐌰𐌹 𐌷𐍂𐍉𐍀𐌹𐌳𐌰: 𐌻𐌰𐌶𐌰𐍂𐌿, 𐌷𐌹𐍂𐌹 𐌿𐍄!');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, '𐌾𐌰𐌷 𐌿𐍂𐍂𐌰𐌽𐌽 𐍃𐌰 𐌳𐌰𐌿𐌸𐌰 𐌲𐌰𐌱𐌿𐌽𐌳𐌰𐌽𐍃 𐌷𐌰𐌽𐌳𐌿𐌽𐍃 𐌾𐌰𐌷 𐍆𐍉𐍄𐌿𐌽𐍃 𐍆𐌰𐍃𐌺𐌾𐌰𐌼, 𐌾𐌰𐌷 𐍅𐌻𐌹𐍄𐍃 𐌹𐍃 𐌰𐌿𐍂𐌰𐌻𐌾𐌰 𐌱𐌹𐌱𐌿𐌽𐌳𐌰𐌽𐍃. 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌰𐌽𐌳𐌱𐌹𐌽𐌳𐌹𐌸 𐌹𐌽𐌰 𐌾𐌰𐌷 𐌻𐌴𐍄𐌹𐌸 𐌲𐌰𐌲𐌲𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, '𐌸𐌰𐌽𐌿𐌷 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌸𐌹𐌶𐌴 𐌾𐌿𐌳𐌰𐌹𐌴𐌹 𐌸𐌰𐌹 𐌵𐌹𐌼𐌰𐌽𐌳𐌰𐌽𐍃 𐌰𐍄 𐌼𐌰𐍂𐌾𐌹𐌽 𐌾𐌰𐌷 𐍃𐌰𐌹𐍈𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰, 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌴𐌳𐌿𐌽 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, '𐍃𐌿𐌼𐌰𐌹𐌸~𐌸𐌰𐌽 𐌹𐌶𐌴 𐌲𐌰𐌻𐌹𐌸𐌿𐌽 𐌳𐌿 𐍆𐌰𐍂𐌴𐌹𐍃𐌰𐌹𐌿𐌼 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌹𐌴𐍃𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, '𐌲𐌰𐌻𐌴𐍃𐌿𐌽 𐌸𐌰𐌽 𐌸𐌰𐌹 𐌰𐌿𐌷𐌿𐌼𐌹𐍃𐍄𐌰𐌽𐍃 𐌲𐌿𐌳𐌾𐌰𐌽𐍃 𐌾𐌰𐌷 𐌸𐌰𐌹 𐍆𐌰𐍂𐌴𐌹(𐍃𐌰𐌹𐌴𐌹𐍃)....');
