INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, '.... 𐌵𐌰𐌸: 𐌽𐌹 𐌰𐌻𐌻𐌰𐌹 𐌷𐍂𐌰𐌹𐌽𐌾𐌰𐌹 𐍃𐌹𐌾𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, '𐌱𐌹𐌸𐌴𐌷 𐌸𐌰𐌽 𐌿𐍃𐌸𐍅𐍉𐌷 𐍆𐍉𐍄𐌿𐌽𐍃 𐌹𐌶𐌴 𐌾𐌰𐌷 𐌽𐌰𐌼 𐍅𐌰𐍃𐍄𐌾𐍉𐍃 𐍃𐌴𐌹𐌽𐍉𐍃, 𐌰𐌽𐌰𐌺𐌿𐌼𐌱𐌾𐌰𐌽𐌳𐍃 𐌰𐍆𐍄𐍂𐌰 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼: 𐍅𐌹𐍄𐌿𐌳𐌿 𐍈𐌰 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, '𐌾𐌿𐍃 𐍅𐍉𐍀𐌴𐌹𐌳 𐌼𐌹𐌺: 𐌻𐌰𐌹𐍃𐌰𐍂𐌴𐌹𐍃 𐌾𐌰𐌷 𐍆𐍂𐌰𐌿𐌾𐌰. 𐍅𐌰𐌹𐌻𐌰 𐌵𐌹𐌸𐌹𐌸, 𐌹𐌼 𐌰𐌿𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, '𐌾𐌰𐌱𐌰𐌹 𐌽𐌿 𐌿𐍃𐌸𐍅𐍉𐌷 𐌹𐌶𐍅𐌹𐍃 𐍆𐍉𐍄𐌿𐌽𐍃, 𐍆𐍂𐌰𐌿𐌾𐌰 𐌾𐌰𐌷 𐌻𐌰𐌹𐍃𐌰𐍂𐌴𐌹𐍃, 𐌾𐌰𐌷 𐌾𐌿𐍃 𐍃𐌺𐌿𐌻𐌿𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌸𐍅𐌰𐌷𐌰𐌽 𐍆𐍉𐍄𐌿𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, '𐌳𐌿 𐍆𐍂𐌹𐍃𐌰𐌷𐍄𐌰𐌹 𐌰𐌿𐌺 𐌰𐍄𐌲𐌰𐍆 𐌹𐌶𐍅𐌹𐍃, 𐌴𐌹 𐍃𐍅𐌰𐍃𐍅𐌴 𐌹𐌺 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐍃𐍅𐌰 𐌾𐌿𐍃 𐍄𐌰𐌿𐌾𐌰𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, '𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃: 𐌽𐌹𐍃𐍄 𐍃𐌺𐌰𐌻𐌺𐍃 𐌼𐌰𐌹𐌶𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌽𐌹𐌷 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌿𐍃 𐌼𐌰𐌹𐌶𐌰 𐌸𐌰𐌼𐌼𐌰 𐍃𐌰𐌽𐌳𐌾𐌰𐌽𐌳𐌹𐌽 𐍃𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, '𐌸𐌰𐌽𐌳𐌴 𐌸𐌰𐍄𐌰 𐍅𐌹𐍄𐌿𐌸, 𐌰𐌿𐌳𐌰𐌲𐌰𐌹 𐍃𐌹𐌾𐌿𐌸, 𐌾𐌰𐌱𐌰𐌹 𐍄𐌰𐌿𐌾𐌹𐌸 𐌸𐌰𐍄𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, '𐌽𐌹 𐌱𐌹 𐌰𐌻𐌻𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌵𐌹𐌸𐌰. 𐌹𐌺 𐍅𐌰𐌹𐍄 𐍈𐌰𐍂𐌾𐌰𐌽𐍃 𐌲𐌰𐍅𐌰𐌻𐌹𐌳𐌰; 𐌰𐌺 𐌴𐌹 𐌿𐍃𐍆𐌿𐌻𐌻𐌹𐌸 𐍅𐌰𐌿𐍂𐌸𐌹 𐌸𐌰𐍄𐌰 𐌲𐌰𐌼𐌴𐌻𐌹𐌳𐍉: 𐍃𐌰𐌴𐌹 𐌼𐌰𐍄𐌹𐌳𐌰 𐌼𐌹𐌸 𐌼𐌹𐍃 𐌷𐌻𐌰𐌹𐌱, 𐌿𐍃𐌷𐍉𐍆 𐌰𐌽𐌰 𐌼𐌹𐌺 𐍆𐌰𐌹𐍂𐌶𐌽𐌰 𐍃𐌴𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, '𐍆𐍂𐌰𐌼 𐌷𐌹𐌼𐌼𐌰 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃, 𐍆𐌰𐌿𐍂𐌸𐌹𐌶𐌴𐌹 𐍅𐌰𐌿𐍂𐌸𐌹, 𐌴𐌹 𐌱𐌹𐌸𐌴 𐍅𐌰𐌹𐍂𐌸𐌰𐌹, 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, '𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃: 𐍃𐌰𐌴𐌹 𐌰𐌽𐌳𐌽𐌹𐌼𐌹𐌸 𐌸𐌰𐌽𐌰 𐌸𐌰𐌽𐌴𐌹 𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌾𐌰, 𐌼𐌹𐌺 𐌰𐌽𐌳𐌽𐌹𐌼𐌹𐌸; 𐌹𐌸 𐍃𐌰𐌴𐌹 𐌼𐌹𐌺 𐌰𐌽𐌳𐌽𐌹𐌼𐌹𐌸, 𐌰𐌽𐌳𐌽𐌹𐌼𐌹𐌸 𐌸𐌰𐌽𐌰 𐍃𐌰𐌽𐌳𐌾𐌰𐌽𐌳𐌰𐌽 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, '𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌰𐌽𐌳𐍃 𐌹𐌴𐍃𐌿𐍃 𐌹𐌽𐌳𐍂𐍉𐌱𐌽𐍉𐌳𐌰 𐌰𐌷𐌼𐌹𐌽 𐌾𐌰𐌷 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌹𐌳𐌰 𐌾𐌰𐌷 𐌵𐌰𐌸: 𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽, 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌰𐌹𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐌲𐌰𐌻𐌴𐍅𐌴𐌹𐌸 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, '𐌸𐌰𐌽𐌿𐌷 𐍃𐌴𐍈𐌿𐌽 𐌳𐌿 𐍃𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌸𐌰𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃, 𐌸𐌰𐌲𐌺𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌱𐌹 𐍈𐌰𐍂𐌾𐌰𐌽𐌰 𐌵𐌴𐌸𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, '𐍅𐌰𐍃𐌿𐌷 𐌸𐌰𐌽 𐌰𐌽𐌰𐌺𐌿𐌼𐌱𐌾𐌰𐌽𐌳𐍃 𐌰𐌹𐌽𐍃 𐌸𐌹𐌶𐌴 𐍃𐌹𐍀𐍉𐌽𐌾𐌴 𐌹𐍃 𐌹𐌽 𐌱𐌰𐍂𐌼𐌰 𐌹𐌴𐍃𐌿𐌹𐍃, 𐌸𐌰𐌽𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌹𐌴𐍃𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, '𐌱𐌰𐌽𐌳𐍅𐌹𐌳𐌿𐌷 𐌸𐌰𐌽 𐌸𐌰𐌼𐌼𐌰 𐍃𐌴𐌹𐌼𐍉𐌽 𐍀𐌰𐌹𐍄𐍂𐌿𐍃 𐌳𐌿 𐍆𐍂𐌰𐌹𐌷𐌽𐌰𐌽 𐍈𐌰𐍃 𐍅𐌴𐍃𐌹, 𐌱𐌹 𐌸𐌰𐌽𐌴𐌹 𐌵𐌰𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, '𐌰𐌽𐌰𐌺𐌿𐌼𐌱𐌹𐌳𐌰 𐌸𐌰𐌽 𐌾𐌰𐌹𐌽𐍃 𐍃𐍅𐌰 𐌰𐌽𐌰 𐌱𐌰𐍂𐌼𐌰 𐌹𐌴𐍃𐌿𐌹𐍃 𐌵𐌰𐌸𐌿𐌷 𐌹𐌼𐌼𐌰: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐍈𐌰𐍃 𐌹𐍃𐍄?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐍃𐌰 𐌹𐍃𐍄 𐌸𐌰𐌼𐌼𐌴𐌹 𐌹𐌺 𐌿𐍆𐌳𐌰𐌿𐍀𐌾𐌰𐌽𐌳𐍃 𐌸𐌰𐌽𐌰 𐌷𐌻𐌰𐌹𐍆 𐌲𐌹𐌱𐌰. 𐌾𐌰𐌷 𐌿𐍆𐌳𐌰𐌿𐍀𐌾𐌰𐌽𐌳𐍃 𐌸𐌰𐌽𐌰 𐌷𐌻𐌰𐌹𐍆 𐌲𐌰𐍆 𐌹𐌿𐌳𐌹𐌽 𐍃𐌴𐌹𐌼𐍉𐌽𐌹𐍃, 𐍃𐌺𐌰𐍂𐌹𐍉𐍄𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, '𐌾𐌰𐌷 𐌰𐍆𐌰𐍂 𐌸𐌰𐌼𐌼𐌰 𐌷𐌻𐌰𐌹𐌱𐌰 𐌸𐌰𐌽 𐌲𐌰𐌻𐌰𐌹𐌸 𐌹𐌽 𐌾𐌰𐌹𐌽𐌰𐌽𐌰 𐍃𐌰𐍄𐌰𐌽𐌰. 𐌵𐌰𐌸 𐌸𐌰𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌹𐌴𐍃𐌿𐍃: 𐌸𐌰𐍄𐌴𐌹 𐍄𐌰𐌿𐌾𐌹𐍃, 𐍄𐌰𐍅𐌴𐌹 𐍃𐍀𐍂𐌰𐌿𐍄𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, '𐌸𐌰𐍄𐌿𐌷 𐌸𐌰𐌽 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌽𐌹 𐍅𐌹𐍃𐍃𐌰 𐌸𐌹𐌶𐌴 𐌰𐌽𐌰𐌺𐌿𐌼𐌱𐌾𐌰𐌽𐌳𐌰𐌽𐌴, 𐌳𐌿𐍈𐌴 𐌵𐌰𐌸 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, '𐍃𐌿𐌼𐌰𐌹 𐌼𐌿𐌽𐌳𐌴𐌳𐌿𐌽, 𐌴𐌹 𐌿𐌽𐍄𐌴 𐌰𐍂𐌺𐌰 𐌷𐌰𐌱𐌰𐌹𐌳𐌰 𐌹𐌿𐌳𐌰𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌵𐌴𐌸𐌹 𐌹𐌼𐌼𐌰 𐌹𐌴𐍃𐌿𐍃: 𐌱𐌿𐌲𐌴𐌹 𐌸𐌹𐌶𐌴𐌹 𐌸𐌰𐌿𐍂𐌱𐌴𐌹𐌼𐌰 𐌳𐌿 𐌳𐌿𐌻𐌸𐌰𐌹, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌸𐌰𐌹𐌼 𐌿𐌽𐌻𐌴𐌳𐌰𐌼 𐌴𐌹 𐍈𐌰 𐌲𐌹𐌱𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, '𐌱𐌹𐌸𐌴 𐌰𐌽𐌳𐌽𐌰𐌼 𐌸𐌰𐌽𐌰 𐌷𐌻𐌰𐌹𐌱 𐌾𐌰𐌹𐌽𐍃, 𐍃𐌿𐌽𐍃 𐌲𐌰𐌻𐌰𐌹𐌸 𐌿𐍄. 𐍅𐌰𐍃𐌿𐌷 𐌸𐌰𐌽 𐌽𐌰𐌷𐍄𐍃, 𐌸𐌰𐌽 𐌲𐌰𐌻𐌰𐌹𐌸 𐌿𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, '𐌵𐌰𐌸 𐌸𐌰𐌽 𐌹𐌴𐍃𐌿𐍃: 𐌽𐌿 𐌲𐌰𐍃𐍅𐌴𐍂𐌰𐌹𐌳𐍃 𐍅𐌰𐍂𐌸 𐍃𐌿𐌽𐌿𐍃 𐌼𐌰𐌽𐍃, 𐌾𐌰𐌷 𐌲𐌿𐌸 𐌷𐌰𐌿𐌷𐌹𐌸𐍃 𐌹𐍃𐍄 𐌹𐌽 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, '𐌾𐌰𐌱𐌰𐌹 𐌽𐌿 𐌲𐌿𐌸 𐌷𐌰𐌿𐌷𐌹𐌸𐍃 𐌹𐍃𐍄 𐌹𐌽 𐌹𐌼𐌼𐌰, 𐌾𐌰𐌷 𐌲𐌿𐌸 𐌷𐌰𐌿𐌷𐌴𐌹𐌸 𐌹𐌽𐌰 𐌹𐌽 𐍃𐌹𐍃 𐌾𐌰𐌷 𐍃𐌿𐌽𐍃 𐌷𐌰𐌿𐌷𐌹𐌳𐌰 𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, '𐌱𐌰𐍂𐌽𐌹𐌻𐍉𐌽𐌰, 𐌽𐌰𐌿𐌷 𐌻𐌴𐌹𐍄𐌹𐌻 𐌼𐌴𐌻 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌹𐌼. 𐍃𐍉𐌺𐌴𐌹𐌸 𐌼𐌹𐌺, 𐌾𐌰𐌷 𐍃𐍅𐌰𐍃𐍅𐌴 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌿𐌳𐌰𐌹𐌿𐌼, 𐌴𐌹 𐌸𐌰𐌳𐌴𐌹 𐌹𐌺 𐌲𐌰𐌲𐌲𐌰, 𐌾𐌿𐍃 𐌽𐌹 𐌼𐌰𐌲𐌿𐌸 𐌵𐌹𐌼𐌰𐌽, 𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐌵𐌹𐌸𐌰 𐌽𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, '𐌰𐌽𐌰𐌱𐌿𐍃𐌽 𐌽𐌹𐌿𐌾𐌰 𐌲𐌹𐌱𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐍃𐍅𐌴 𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌸𐌴𐌹 𐌾𐌰𐌷 𐌾𐌿𐍃 𐍆𐍂𐌹𐌾𐍉𐌸 𐌼𐌹𐍃𐍃𐍉 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, '𐌱𐌹 𐌸𐌰𐌼𐌼𐌰 𐌿𐍆𐌺𐌿𐌽𐌽𐌰𐌽𐌳 𐌰𐌻𐌻𐌰𐌹, 𐌸𐌴𐌹 𐌼𐌴𐌹𐌽𐌰𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐍃𐌹𐌾𐌿𐌸, 𐌾𐌰𐌱𐌰𐌹 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌷𐌰𐌱𐌰𐌹𐌳 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼𐌼𐌰 𐍃𐌴𐌹𐌼𐍉𐌽 𐍀𐌰𐌹𐍄𐍂𐌿𐍃: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐍈𐌰𐌳 𐌲𐌰𐌲𐌲𐌹𐍃? 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌰𐌽𐌳𐍃 𐌹𐌴𐍃𐌿𐍃 𐌵𐌰𐌸: 𐌸𐌰𐌳𐌴𐌹 𐌹𐌺 𐌲𐌰𐌲𐌲𐌰, 𐌽𐌹 𐌼𐌰𐌲𐍄 𐌼𐌹𐌺 𐌽𐌿 𐌻𐌰𐌹𐍃𐍄𐌾𐌰𐌽; 𐌹𐌸 𐌱𐌹𐌸𐌴 𐌻𐌰𐌹𐍃𐍄𐌴𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, '𐌸𐌰𐍂𐌿𐌷 𐍀𐌰𐌹𐍄𐍂𐌿𐍃 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌳𐌿𐍈𐌴 𐌽𐌹 𐌼𐌰𐌲 𐌸𐌿𐌺 𐌻𐌰𐌹𐍃𐍄𐌾𐌰𐌽 𐌽𐌿? 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐌼𐌴𐌹𐌽𐌰 𐍆𐌰𐌿𐍂 𐌸𐌿𐌺 𐌻𐌰𐌲𐌾𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐌸𐌴𐌹𐌽𐌰 𐍆𐌰𐌿𐍂 𐌼𐌹𐌺 𐌻𐌰𐌲𐌾𐌹𐍃? 𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽 𐌵𐌹𐌸𐌰 𐌸𐌿𐍃, 𐌸𐌴𐌹 𐌷𐌰𐌽𐌰 𐌽𐌹 𐌷𐍂𐌿𐌺𐌴𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌸𐌿 𐌼𐌹𐌺 𐌰𐍆𐌰𐌹𐌺𐌹𐍃 𐌺𐌿𐌽𐌽𐌰𐌽 𐌸𐍂𐌹𐌼 𐍃𐌹𐌽𐌸𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '𐌽𐌹 𐌹𐌽𐌳𐍂𐍉𐌱𐌽𐌰𐌹 𐌹𐌶𐍅𐌰𐍂 𐌷𐌰𐌹𐍂𐍄𐍉; 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌳𐌿 𐌲𐌿𐌳𐌰 𐌾𐌰𐌷 𐌳𐌿 𐌼𐌹𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, '𐌹𐌽 𐌲𐌰𐍂𐌳𐌰 𐌰𐍄𐍄𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐌹𐍃 𐍃𐌰𐌻𐌹𐌸𐍅𐍉𐍃 𐌼𐌰𐌽𐌰𐌲𐍉𐍃 𐍃𐌹𐌽𐌳; 𐌰𐌸𐌸𐌰𐌽 𐌽𐌹𐌱𐌰 𐍅𐌴𐍃𐌴𐌹𐌽𐌰, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌵𐌴𐌸𐌾𐌰𐌿 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃: 𐌲𐌰𐌲𐌲𐌰 𐌼𐌰𐌽𐍅𐌾𐌰𐌽 𐍃𐍄𐌰𐌳 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, '𐌾𐌰𐌷 𐌸𐌰𐌽 𐌾𐌰𐌱𐌰𐌹 𐌲𐌰𐌲𐌲𐌰, 𐌼𐌰𐌽𐍅𐌾𐌰 𐌹𐌶𐍅𐌹𐍃 𐍃𐍄𐌰𐌳, 𐌰𐍆𐍄𐍂𐌰 𐌵𐌹𐌼𐌰 𐌾𐌰𐌷 𐍆𐍂𐌰𐌽𐌹𐌼𐌰 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐌼𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽, 𐌴𐌹 𐌸𐌰𐍂𐌴𐌹 𐌹𐌼 𐌹𐌺, 𐌸𐌰𐍂𐌿𐌷 𐍃𐌹𐌾𐌿𐌸 𐌾𐌰𐌷 𐌾𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, '𐌾𐌰𐌷 𐌸𐌰𐌳𐌴𐌹 𐌹𐌺 𐌲𐌰𐌲𐌲𐌰 𐌺𐌿𐌽𐌽𐌿𐌸 𐌾𐌰𐌷 𐌸𐌰𐌽𐌰 𐍅𐌹𐌲 𐌺𐌿𐌽𐌽𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌹𐌼𐌼𐌰 Ã𐍉𐌼𐌰𐍃: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌽𐌹 𐍅𐌹𐍄𐌿𐌼 𐍈𐌰𐌸 𐌲𐌰𐌲𐌲𐌹𐍃, 𐌾𐌰𐌷 𐍈𐌰𐌹𐍅𐌰 𐌼𐌰𐌲𐌿𐌼 𐌸𐌰𐌽𐌰 𐍅𐌹𐌲 𐌺𐌿𐌽𐌽𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, '𐌵𐌰𐌸 𐌹𐌼𐌼𐌰 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌺 𐌹𐌼 𐍃𐌰 𐍅𐌹𐌲𐍃 𐌾𐌰𐌷 𐍃𐌿𐌽𐌾𐌰 𐌾𐌰𐌷 𐌻𐌹𐌱𐌰𐌹𐌽𐍃. 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌽𐌹 𐌵𐌹𐌼𐌹𐌸 𐌰𐍄 𐌰𐍄𐍄𐌹𐌽, 𐌽𐌹𐌱𐌰 𐌸𐌰𐌹𐍂𐌷 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, '𐌹𐌸 𐌺𐌿𐌽𐌸𐌴𐌳𐌴𐌹𐌸 𐌼𐌹𐌺, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌺𐌿𐌽𐌸𐌴𐌳𐌴𐌹𐌸 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰𐌽 𐌼𐌴𐌹𐌽𐌰𐌽𐌰; 𐌾𐌰𐌷 𐌸𐌰𐌽 𐍆𐍂𐌰𐌼 𐌷𐌹𐌼𐌼𐌰 𐌺𐌿𐌽𐌽𐌿𐌸 𐌹𐌽𐌰 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐌸 𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, '𐌹𐌸 𐍆𐌹𐌻𐌹𐍀𐍀𐌿𐍃 𐌵𐌰𐌸𐌿𐌷 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌰𐌿𐌲𐌴𐌹 𐌿𐌽𐍃𐌹𐍃 𐌸𐌰𐌽𐌰 𐌰𐍄𐍄𐌰𐌽; 𐌸𐌰𐍄𐌿𐌷 𐌲𐌰𐌽𐌰𐌷 𐌿𐌽𐍃𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌹𐌼𐌼𐌰 𐌹𐌴𐍃𐌿𐍃: 𐍃𐍅𐌰𐌻𐌰𐌿𐌳 𐌼𐌴𐌻𐌹𐍃 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐍅𐌰𐍃, 𐌾𐌰𐌷 𐌽𐌹 𐌿𐍆𐌺𐌿𐌽𐌸𐌴𐍃 𐌼𐌹𐌺, 𐍆𐌹𐌻𐌹𐍀𐍀𐌿? 𐍃𐌰𐌴𐌹 𐌲𐌰𐍃𐌰𐍈 𐌼𐌹𐌺, 𐌲𐌰𐍃𐌰𐍈 𐌰𐍄𐍄𐌰𐌽, 𐌾𐌰𐌷 𐍈𐌰𐌹𐍅𐌰 𐌸𐌿 𐌵𐌹𐌸𐌹𐍃: 𐌰𐌿𐌲𐌴𐌹 𐌿𐌽𐍃𐌹𐍃 𐌸𐌰𐌽𐌰 𐌰𐍄𐍄𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, '𐌽𐌹𐌿 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌽 𐌰𐍄𐍄𐌹𐌽 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌹𐌽 𐌼𐌹𐍃 𐌹𐍃𐍄? 𐌸𐍉 𐍅𐌰𐌿𐍂𐌳𐌰 𐌸𐍉𐌴𐌹 𐌹𐌺 𐍂𐍉𐌳𐌾𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌰𐍆 𐌼𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌽𐌹 𐍂𐍉𐌳𐌾𐌰, 𐌰𐌺 𐌰𐍄𐍄𐌰 𐍃𐌰𐌴𐌹 𐌹𐌽 𐌼𐌹𐍃 𐌹𐍃𐍄, 𐍃𐌰 𐍄𐌰𐌿𐌾𐌹𐌸 𐌸𐍉 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, '𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌼𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌽 𐌰𐍄𐍄𐌹𐌽 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌹𐌽 𐌼𐌹𐍃; 𐌹𐌸 𐌾𐌰𐌱𐌰𐌹, 𐌹𐌽 𐌸𐌹𐌶𐌴 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌴 [𐌽𐌹] 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌼𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, '𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃, 𐍃𐌰𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌳 𐌼𐌹𐍃: 𐌸𐍉 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌸𐍉𐌴𐌹 𐌹𐌺 𐍄𐌰𐌿𐌾𐌰, 𐌾𐌰𐌷 𐌹𐍃 𐍄𐌰𐌿𐌾𐌹𐌸 𐌾𐌰𐌷 𐌼𐌰𐌹𐌶𐍉𐌽𐌰 𐌸𐌰𐌹𐌼 𐍄𐌰𐌿𐌾𐌹𐌸; 𐌿𐌽𐍄𐌴 𐌹𐌺 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽 𐌲𐌰𐌲𐌲𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, '𐌾𐌰𐌷 𐌸𐌰𐍄𐌴𐌹 𐍈𐌰 𐌱𐌹𐌳𐌾𐌹𐌸 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌸𐌰𐍄𐌰 𐍄𐌰𐌿𐌾𐌰, 𐌴𐌹 𐌷𐌰𐌿𐌷𐌾𐌰𐌹𐌳𐌰𐌿 𐌰𐍄𐍄𐌰 𐌹𐌽 𐍃𐌿𐌽𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, '𐌾𐌰𐌱𐌰𐌹 𐍈𐌹𐍃 𐌱𐌹𐌳𐌾𐌹𐌸 𐌼𐌹𐌺 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌹𐌺 𐍄𐌰𐌿𐌾𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, '𐌾𐌰𐌱𐌰𐌹 𐌼𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌸, 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐍉𐍃 𐍆𐌰𐍃𐍄𐌰𐌹𐌳.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, '𐌾𐌰𐌷 𐌹𐌺 𐌱𐌹𐌳𐌾𐌰 𐌰𐍄𐍄𐌰𐌽, 𐌾𐌰𐌷 𐌰𐌽𐌸𐌰𐍂𐌰𐌽𐌰 𐍀𐌰𐍂𐌰𐌺𐌻𐌴𐍄𐌿 𐌲𐌹𐌱𐌹𐌸 𐌹𐌶𐍅𐌹𐍃, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐌰𐌹𐍅𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, '𐌰𐌷𐌼𐌰 𐍃𐌿𐌽𐌾𐍉𐍃, 𐌸𐌰𐌽𐌴𐌹 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌽𐌹 𐌼𐌰𐌲 𐌽𐌹𐌼𐌰𐌽, 𐌿𐌽𐍄𐌴 𐌽𐌹 𐍃𐌰𐌹𐍈𐌹𐌸 𐌹𐌽𐌰, 𐌽𐌹𐌷 𐌺𐌰𐌽𐌽 𐌹𐌽𐌰; 𐌹𐌸 𐌾𐌿𐍃 𐌺𐌿𐌽𐌽𐌿𐌸 𐌹𐌽𐌰, 𐌿𐌽𐍄𐌴 𐌹𐍃 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐍅𐌹𐍃𐌹𐌸 𐌾𐌰𐌷 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, '𐌽𐌹 𐌻𐌴𐍄𐌰 𐌹𐌶𐍅𐌹𐍃 𐍅𐌹𐌳𐌿𐍅𐌰𐌹𐍂𐌽𐌰𐌽𐍃; 𐌵𐌹𐌼𐌰 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, '𐌽𐌰𐌿𐌷 𐌻𐌴𐌹𐍄𐌹𐌻, 𐌾𐌰𐌷 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌼𐌹𐌺 𐌽𐌹 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐍃𐌰𐌹𐍈𐌹𐌸; 𐌹𐌸 𐌾𐌿𐍃 𐍃𐌰𐌹𐍈𐌹𐌸 𐌼𐌹𐌺, 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌻𐌹𐌱𐌰, 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌻𐌹𐌱𐌰𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, '𐌹𐌽 𐌾𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌳𐌰𐌲𐌰 𐌿𐍆𐌺𐌿𐌽𐌽𐌰𐌹𐌸 𐌾𐌿𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌽 𐌰𐍄𐍄𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌾𐌰𐌷 𐌾𐌿𐍃 𐌹𐌽 𐌼𐌹𐍃 𐌾𐌰𐌷 𐌹𐌺 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, '𐍃𐌰𐌴𐌹 𐌷𐌰𐌱𐌰𐌹𐌳 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐍉𐍃 𐌾𐌰𐌷 𐍆𐌰𐍃𐍄𐌰𐌹𐌸 𐌸𐍉𐍃, 𐍃𐌰 𐌹𐍃𐍄 𐍃𐌰𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌸 𐌼𐌹𐌺: 𐌾𐌰𐌷 𐌸𐌰𐌽 𐍃𐌰𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌸 𐌼𐌹𐌺, 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐍆𐍂𐌰𐌼 𐌰𐍄𐍄𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌾𐌰𐌷 𐌹𐌺 𐍆𐍂𐌹𐌾𐍉 𐌹𐌽𐌰 𐌾𐌰𐌷 𐌲𐌰𐌱𐌰𐌹𐍂𐌷𐍄𐌾𐌰 𐌹𐌼𐌼𐌰 𐌼𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌹𐌼𐌼𐌰 𐌹𐌿𐌳𐌰𐍃, 𐌽𐌹 𐍃𐌰 𐌹𐍃𐌺𐌰𐍂𐌾𐍉𐍄𐌴𐍃: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐍈𐌰 𐍅𐌰𐍂𐌸, 𐌴𐌹 𐌿𐌽𐍃𐌹𐍃 𐌼𐌿𐌽𐌰𐌹𐍃 𐌲𐌰𐌱𐌰𐌹𐍂𐌷𐍄𐌾𐌰𐌽 𐌸𐌿𐌺 𐍃𐌹𐌻𐌱𐌰𐌽, 𐌹𐌸 𐌸𐌹𐌶𐌰𐌹 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐌰𐌹 𐌽𐌹?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐌼𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌸, [𐌾𐌰𐌷] 𐍅𐌰𐌿𐍂𐌳 𐌼𐌴𐌹𐌽 𐍆𐌰𐍃𐍄𐌰𐌹𐌸, 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌼𐌴𐌹𐌽𐍃 𐍆𐍂𐌹𐌾𐍉𐌸 𐌹𐌽𐌰, 𐌾𐌰𐌷 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌲𐌰𐌻𐌴𐌹𐌸𐍉𐍃 𐌾𐌰𐌷 𐍃𐌰𐌻𐌹𐌸𐍅𐍉𐍃 𐌰𐍄 𐌹𐌼𐌼𐌰 𐌲𐌰𐍄𐌰𐌿𐌾𐍉𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, '𐌹𐌸 𐍃𐌰𐌴𐌹 𐌽𐌹 𐍆𐍂𐌹𐍉𐌸 𐌼𐌹𐌺, 𐌸𐍉 𐍅𐌰𐌿𐍂𐌳𐌰 𐌼𐌴𐌹𐌽𐌰 𐌽𐌹 𐍆𐌰𐍃𐍄𐌰𐌹𐌸; 𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐍅𐌰𐌿𐍂𐌳 𐌸𐌰𐍄𐌴𐌹 𐌷𐌰𐌿𐍃𐌴𐌹𐌸 𐌽𐌹𐍃𐍄 𐌼𐌴𐌹𐌽, 𐌰𐌺 𐌸𐌹𐍃 𐍃𐌰𐌽𐌳𐌾𐌰𐌽𐌳𐌹𐌽𐍃 𐌼𐌹𐌺 𐌰𐍄𐍄𐌹𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, '𐌸𐌰𐍄𐌰 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, '𐌰𐌸𐌸𐌰𐌽 𐍃𐌰 𐍀𐌰𐍂𐌰𐌺𐌻𐌴𐍄𐌿𐍃, 𐌰𐌷𐌼𐌰 𐍃𐌰 𐍅𐌴𐌹𐌷𐌰, 𐌸𐌰𐌽𐌴𐌹 𐍃𐌰𐌽𐌳𐌴𐌹𐌸 𐌰𐍄𐍄𐌰 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐍃𐌰 𐌹𐌶𐍅𐌹𐍃 𐌻𐌰𐌹𐍃𐌴𐌹𐌸 𐌰𐌻𐌻𐌰𐍄𐌰 𐌾𐌰𐌷 𐌲𐌰𐌼𐌰𐌿𐌳𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌰𐌻𐌻𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, '𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌱𐌹𐌻𐌴𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌼𐌴𐌹𐌽 𐌲𐌹𐌱𐌰 𐌹𐌶𐍅𐌹𐍃; 𐌽𐌹 𐍃𐍅𐌰𐍃𐍅𐌴 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸𐍃 𐌲𐌹𐌱𐌹𐌸, 𐌹𐌺 𐌲𐌹𐌱𐌰 𐌹𐌶𐍅𐌹𐍃. 𐌽𐌹 𐌹𐌽𐌳𐍂𐍉𐌱𐌽𐌰𐌹𐌽𐌰 𐌹𐌶𐍅𐌰𐍂𐌰 𐌷𐌰𐌹𐍂𐍄𐍉𐌽𐌰 𐌽𐌹𐌷 𐍆𐌰𐌿𐍂𐌷𐍄𐌾𐌰𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, '𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌸 𐌴𐌹 𐌹𐌺 𐌵𐌰𐌸 𐌹𐌶𐍅𐌹𐍃: 𐌲𐌰𐌻𐌴𐌹𐌸𐌰 𐌾𐌰𐌷 𐌵𐌹𐌼𐌰 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃; 𐌾𐌰𐌱𐌰𐌹 𐍆𐍂𐌹𐌾𐍉𐌳𐌴𐌳𐌴𐌹𐌸 𐌼𐌹𐌺, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌾𐌿𐍃 𐍆𐌰𐌲𐌹𐌽𐍉𐌳𐌴𐌳𐌴𐌹𐌸 𐌴𐌹 𐌹𐌺 𐌲𐌰𐌲𐌲𐌰 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽: 𐌿𐌽𐍄𐌴 𐌰𐍄𐍄𐌰 𐌼𐌴𐌹𐌽𐍃 𐌼𐌰𐌹𐌶𐌰 𐌼𐌹𐍃 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, '𐌾𐌰𐌷 𐌽𐌿 𐌵𐌰𐌸 𐌹𐌶𐍅𐌹𐍃, 𐍆𐌰𐌿𐍂𐌸𐌹𐌶𐌴𐌹 𐍅𐌰𐌿𐍂𐌸𐌹, 𐌴𐌹 𐌱𐌹𐌸𐌴 𐍅𐌰𐌹𐍂𐌸𐌰𐌹, 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, '𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐍆𐌹𐌻𐌿 𐌽𐌹 𐌼𐌰𐌸𐌻𐌾𐌰 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃; 𐌵𐌹𐌼𐌹𐌸 𐍃𐌰𐌴𐌹 𐌸𐌹𐌶𐌰𐌹 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐌰𐌹 𐍂𐌴𐌹𐌺𐌹𐌽𐍉𐌸, 𐌾𐌰𐌷 𐌹𐌽 𐌼𐌹𐍃 𐌽𐌹 𐌱𐌹𐌲𐌹𐍄𐌹𐌸 𐍅𐌰𐌹𐌷𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, '𐌰𐌺 𐌴𐌹 𐌿𐍆𐌺𐌿𐌽𐌽𐌰𐌹 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌰𐍄𐍄𐌰𐌽 𐌼𐌴𐌹𐌽𐌰𐌽𐌰, 𐌾𐌰𐌷 𐍃𐍅𐌰𐍃𐍅𐌴 𐌰𐌽𐌰𐌱𐌰𐌿𐌳 𐌼𐌹𐍃 𐌰𐍄𐍄𐌰, 𐍃𐍅𐌰 𐍄𐌰𐌿𐌾𐌰. 𐌿𐍂𐍂𐌴𐌹𐍃𐌹𐌸, 𐌲𐌰𐌲𐌲𐌰𐌼 𐌸𐌰𐌸𐍂𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '𐌹𐌺 𐌹𐌼 𐍅𐌴𐌹𐌽𐌰𐍄𐍂𐌹𐌿 𐌸𐌰𐍄𐌰 𐍃𐌿𐌽𐌾𐌴𐌹𐌽𐍉, 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌼𐌴𐌹𐌽𐍃 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌾𐌰 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, '𐌰𐌻𐌻 𐍄𐌰𐌹𐌽𐌴 𐌹𐌽 𐌼𐌹𐍃 𐌿𐌽𐌱𐌰𐌹𐍂𐌰𐌽𐌳𐌰𐌽𐌴 𐌰𐌺𐍂𐌰𐌽 𐌲𐍉𐌸, 𐌿𐍃𐌽𐌹𐌼𐌹𐌸 𐌹𐍄𐌰: 𐌾𐌰𐌷 𐌰𐌻𐌻 𐌰𐌺𐍂𐌰𐌽 𐌱𐌰𐌹𐍂𐌰𐌽𐌳𐌰𐌽𐌴, 𐌲𐌰𐌷𐍂𐌰𐌹𐌽𐌴𐌹𐌸 𐌹𐍄𐌰, 𐌴𐌹 𐌼𐌰𐌽𐌰𐌲𐌹𐌶𐍉 𐌰𐌺𐍂𐌰𐌽 𐌱𐌰𐌹𐍂𐌰𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, '𐌾𐌿 𐌾𐌿𐍃 𐌷𐍂𐌰𐌹𐌽𐌾𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐌸𐌹𐍃 𐍅𐌰𐌿𐍂𐌳𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐍂𐍉𐌳𐌹𐌳𐌰 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, '𐍅𐌹𐍃𐌰𐌹𐌸 𐌹𐌽 𐌼𐌹𐍃 𐌾𐌰𐌷 𐌹𐌺 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃. 𐍃𐍅𐌴 𐍃𐌰 𐍅𐌴𐌹𐌽𐌰𐍄𐌰𐌹𐌽𐍃 𐌽𐌹 𐌼𐌰𐌲 𐌰𐌺𐍂𐌰𐌽 𐌱𐌰𐌹𐍂𐌰𐌽 𐌰𐍆 𐍃𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽, 𐌽𐌹𐌱𐌰 𐌹𐍃𐍄 𐌰𐌽𐌰 𐍅𐌴𐌹𐌽𐌰𐍄𐍂𐌹𐍅𐌰, 𐍃𐍅𐌰𐌷 𐌽𐌹𐌷 𐌾𐌿𐍃, 𐌽𐌹𐌱𐌰 𐌹𐌽 𐌼𐌹𐍃 𐍃𐌹𐌾𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, '𐌹𐌺 𐌹𐌼 𐌸𐌰𐍄𐌰 𐍅𐌴𐌹𐌽𐌰𐍄𐍂𐌹𐌿, 𐌹𐌸 𐌾𐌿𐍃 𐍅𐌴𐌹𐌽𐌰𐍄𐌰𐌹𐌽𐍉𐍃; 𐍃𐌰𐌴𐌹 𐍅𐌹𐍃𐌹𐌸 𐌹𐌽 𐌼𐌹𐍃 𐌾𐌰𐌷 𐌹𐌺 𐌹𐌽 𐌹𐌼𐌼𐌰, 𐍃𐍅𐌰 𐌱𐌰𐌹𐍂𐌹𐌸 𐌰𐌺𐍂𐌰𐌽 𐌼𐌰𐌽𐌰𐌲, 𐌸𐌰𐍄𐌴𐌹 𐌹𐌽𐌿𐌷 𐌼𐌹𐌺 𐌽𐌹 𐌼𐌰𐌲𐌿𐌸 𐍄𐌰𐌿𐌾𐌰𐌽 𐌽𐌹 𐍅𐌰𐌹𐌷𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, '𐌽𐌹𐌱𐌰 𐍃𐌰𐌴𐌹 𐍅𐌹𐍃𐌹𐌸 𐌹𐌽 𐌼𐌹𐍃, 𐌿𐍃𐍅𐌰𐌹𐍂𐍀𐌰𐌳𐌰 𐌿𐍄 𐍃𐍅𐌴 𐍅𐌴𐌹𐌽𐌰𐍄𐌰𐌹𐌽𐍃, 𐌾𐌰𐌷 𐌲𐌰𐌸𐌰𐌿𐍂𐍃𐌽𐌹𐌸 𐌾𐌰𐌷 𐌲𐌰𐌻𐌹𐍃𐌰𐌳𐌰, 𐌾𐌰𐌷 𐌹𐌽 𐍆𐍉𐌽 𐌲𐌰𐌻𐌰𐌲𐌾𐌰𐌽𐌳 𐌾𐌰𐌷 𐌹𐌽𐌱𐍂𐌰𐌽𐌽𐌾𐌰𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, '𐌰𐌸𐌸𐌰𐌽 𐌾𐌰𐌱𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐌼𐌹𐍃, 𐌾𐌰𐌷 𐍅𐌰𐌿𐍂𐌳𐌰 𐌼𐌴𐌹𐌽𐌰 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐍃𐌹𐌽𐌳, 𐌸𐌰𐍄𐌰𐍈𐌰𐌷 𐌸𐌴𐌹 𐍅𐌹𐌻𐌴𐌹𐌸 𐌱𐌹𐌳𐌾𐌹𐌸, 𐌾𐌰𐌷 𐍅𐌰𐌹𐍂𐌸𐌹𐌸 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, '𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌷𐌰𐌿𐌷𐌹𐌸𐍃 𐌹𐍃𐍄 𐌰𐍄𐍄𐌰 𐌼𐌴𐌹𐌽𐍃, 𐌴𐌹 𐌰𐌺𐍂𐌰𐌽 𐌼𐌰𐌽𐌰𐌲 𐌱𐌰𐌹𐍂𐌰𐌹𐌸 𐌾𐌰𐌷 𐍅𐌰𐌹𐍂𐌸𐌰𐌹𐌸 𐌼𐌴𐌹𐌽𐌰𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, '𐍃𐍅𐌰𐍃𐍅𐌴 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌼𐌹𐌺 𐌰𐍄𐍄𐌰, 𐍃𐍅𐌰𐌷 𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌹𐌶𐍅𐌹𐍃; 𐍅𐌹𐍃𐌰𐌹𐌸 𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹 𐌼𐌴𐌹𐌽𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, '𐌾𐌰𐌱𐌰𐌹 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐍉𐍃 𐍆𐌰𐍃𐍄𐌰𐌹𐌳, 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹 𐌼𐌴𐌹𐌽𐌰𐌹, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌹𐌺 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌽𐍃 𐌰𐍄𐍄𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐌹𐍃 𐍆𐌰𐍃𐍄𐌰𐌹𐌳𐌰, 𐌾𐌰𐌷 𐍅𐌹𐍃𐌰 𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹 𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, '𐌸𐌰𐍄𐌰 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌴𐌹 𐍆𐌰𐌷𐌴𐌸𐍃 𐌼𐌴𐌹𐌽𐌰 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐍃𐌹𐌾𐌰𐌹, 𐌾𐌰𐌷 𐍆𐌰𐌷𐌴𐌳𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰𐌹𐌳𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, '𐌸𐌰𐍄𐌰 𐌹𐍃𐍄 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐍃 𐌼𐌴𐌹𐌽𐌰, 𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌳𐌰 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, '𐌼𐌰𐌹𐌶𐌴𐌹𐌽 𐌸𐌹𐌶𐌰𐌹 𐍆𐍂𐌹𐌰𐌸𐍅𐌰[𐌹] 𐌼𐌰𐌽𐌽𐌰 𐌽𐌹 𐌷𐌰𐌱𐌰𐌹𐌸, 𐌴𐌹 𐍈𐌰𐍃 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐍃𐌴𐌹𐌽𐌰 𐌻𐌰𐌲𐌾𐌹𐌸 𐍆𐌰𐌿𐍂 𐍆𐍂𐌹𐌾𐍉𐌽𐌳𐍃 𐍃𐌴𐌹𐌽𐌰𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, '𐌾𐌿𐍃 𐍆𐍂𐌹𐌾𐍉𐌽𐌳𐍃 𐌼𐌴𐌹𐌽𐌰𐌹 𐍃𐌹𐌾𐌿𐌸, 𐌾𐌰𐌱𐌰𐌹 𐍄𐌰𐌿𐌾𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌰𐌽𐌰𐌱𐌹𐌿𐌳𐌰 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, '𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌹𐌶𐍅𐌹𐍃 𐌽𐌹 𐌵𐌹𐌸𐌰 𐍃𐌺𐌰𐌻𐌺𐌰𐌽𐍃; 𐌿𐌽𐍄𐌴 𐍃𐌺𐌰𐌻𐌺𐍃 𐌽𐌹 𐍅𐌰𐌹𐍄 𐍈𐌰 𐍄𐌰𐌿𐌾𐌹𐌸 𐌹𐍃 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌹𐌸 𐌹𐌺 𐌹𐌶𐍅𐌹𐍃 𐌵𐌰𐌸 𐍆𐍂𐌹𐌾𐍉𐌽𐌳𐍃, 𐌿𐌽𐍄𐌴 𐌰𐌻𐌻 𐌸𐌰𐍄𐌴𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌰 𐌰𐍄 𐌰𐍄𐍄𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌲𐌰𐌺𐌰𐌽𐌽𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, '𐌽𐌹 𐌾𐌿𐍃 𐌼𐌹𐌺 𐌲𐌰𐍅𐌰𐌻𐌹𐌳𐌴𐌳𐌿𐌸, 𐌰𐌺 𐌹𐌺 𐌲𐌰𐍅𐌰𐌻𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌴𐌹 𐌾𐌿𐍃 𐍃𐌽𐌹𐍅𐌰𐌹𐌸 𐌾𐌰𐌷 𐌰𐌺𐍂𐌰𐌽 𐌱𐌰𐌹𐍂𐌰𐌹𐌸, 𐌾𐌰𐌷 𐌰𐌺𐍂𐌰𐌽 𐌹𐌶𐍅𐌰𐍂 𐌳𐌿 𐌰𐌹𐍅𐌰 𐍃𐌹𐌾𐌰𐌹, 𐌴𐌹 𐌸𐌰𐍄𐌰𐍈𐌰𐌷 𐌸𐌴𐌹 𐌱𐌹𐌳𐌾𐌰𐌹𐌸 𐌰𐍄𐍄𐌰𐌽 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌲𐌹𐌱𐌹𐌸 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, '𐌸𐌰𐍄𐌰 𐌰𐌽𐌰𐌱𐌹𐌿𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, '𐌾𐌰𐌱𐌰𐌹 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐍃 𐌹𐌶𐍅𐌹𐍃 𐍆𐌹𐌾𐌰𐌹, 𐌺𐌿𐌽𐌽𐌴𐌹𐌸 𐌴𐌹 𐌼𐌹𐌺 𐍆𐍂𐌿𐌼𐌰𐌽 𐌹𐌶𐍅𐌹𐍃 𐍆𐌹𐌾𐌰𐌹𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, '𐌾𐌰𐌱𐌰𐌹 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃 𐍅𐌴𐍃𐌴𐌹𐌸, 𐌰𐌹𐌸𐌸𐌰𐌿 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐍃 𐍃𐍅𐌴𐍃𐌰𐌽𐍃 𐍆𐍂𐌹𐌾𐍉𐌳𐌴𐌳𐌹; 𐌰𐌸𐌸𐌰𐌽 𐌿𐌽𐍄𐌴 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌽𐌹 𐍃𐌹𐌾𐌿𐌸, 𐌰𐌺 𐌹𐌺 𐌲𐌰𐍅𐌰𐌻𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿, 𐌳𐌿𐌸𐌸𐌴 𐍆𐌹𐌾𐌰𐌹𐌳 𐌹𐌶𐍅𐌹𐍃 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, '𐌲𐌰𐌼𐌿𐌽𐌴𐌹𐌸 𐌸𐌹𐍃 𐍅𐌰𐌿𐍂𐌳𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃: 𐌽𐌹𐍃𐍄 𐍃𐌺𐌰𐌻𐌺𐍃 𐌼𐌰𐌹𐌶𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰. 𐌾𐌰𐌱𐌰𐌹 𐌼𐌹𐌺 𐍅𐍂𐌴𐌺𐌿𐌽, 𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐍅𐍂𐌹𐌺𐌰𐌽𐌳; 𐌾𐌰𐌱𐌰𐌹 𐌼𐌴𐌹𐌽 𐍅𐌰𐌿𐍂𐌳 𐍆𐌰𐍃𐍄𐌰𐌹𐌳𐌴𐌳𐌴𐌹𐌽𐌰, 𐌾𐌰𐌷 𐌹𐌶𐍅𐌰𐍂 𐍆𐌰𐍃𐍄𐌰𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, '𐌰𐌺 𐌸𐌰𐍄𐌰 𐌰𐌻𐌻𐌰𐍄𐌰 𐍄𐌰𐌿𐌾𐌰𐌽𐌳 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐌹𐍃, 𐌿𐌽𐍄𐌴 𐌽𐌹 𐌺𐌿𐌽𐌽𐌿𐌽 𐌸𐌰𐌽𐌰 𐍃𐌰𐌽𐌳𐌾𐌰𐌽𐌳𐌰𐌽 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, '𐌽𐌹𐌷 𐌵𐌴𐌼𐌾𐌰𐌿 𐌾𐌰𐌷 𐍂𐍉𐌳𐌹𐌳𐌴𐌳𐌾𐌰𐌿 𐌳𐌿 𐌹𐌼, 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄 𐌽𐌹 𐌷𐌰𐌱𐌰𐌹𐌳𐌴𐌳𐌴𐌹𐌽𐌰: 𐌹𐌸 𐌽𐌿 𐌹𐌽𐌹𐌻𐍉𐌽𐍃 𐌽𐌹 𐌷𐌰𐌱𐌰𐌽𐌳 𐌱𐌹 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄 𐍃𐌴𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, '𐍃𐌰𐌴𐌹 𐌼𐌹𐌺 𐍆𐌹𐌾𐌰𐌹𐌸, 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰𐌽 𐌼𐌴𐌹𐌽𐌰𐌽𐌰 𐍆𐌹𐌾𐌰𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, '𐌹𐌸 𐌸𐍉 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰 𐌽𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌴𐌳𐌾𐌰𐌿 𐌹𐌽 𐌹𐌼 𐌸𐍉𐌴𐌹 𐌰𐌽𐌸𐌰𐍂 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌽𐌹 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰, 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄 𐌽𐌹 𐌷𐌰𐌱𐌰𐌹𐌳𐌴𐌳𐌴𐌹𐌽𐌰; 𐌹𐌸 𐌽𐌿 𐌾𐌰𐌷 𐌲𐌰𐍃𐌴𐍈𐌿𐌽 𐌼𐌹𐌺 𐌾𐌰𐌷 𐍆𐌹𐌾𐌰𐌹𐌳𐌴𐌳𐌿𐌽 𐌾𐌰𐌷 𐌼𐌹𐌺 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰𐌽 𐌼𐌴𐌹𐌽𐌰𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, '𐌰𐌺 𐌴𐌹 𐌿𐍃𐍆𐌿𐌻𐌻𐌽𐍉𐌳𐌴𐌳𐌹 𐍅𐌰𐌿𐍂𐌳 𐌸𐌰𐍄𐌰 𐌲𐌰𐌼𐌴𐌻𐌹𐌳𐍉 𐌹𐌽 𐍅𐌹𐍄𐍉𐌳𐌰 𐌹𐌶𐌴: 𐌴𐌹 𐍆𐌹𐌾𐌰𐌹𐌳𐌴𐌳𐌿𐌽 𐌼𐌹𐌺 𐌰𐍂𐍅𐌾𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, '𐌰𐌸𐌸𐌰𐌽 𐌸𐌰𐌽 𐌵𐌹𐌼𐌹𐌸 𐍀𐌰𐍂𐌰𐌺𐌻𐌴𐍄𐌿𐍃 𐌸𐌰𐌽𐌴𐌹 𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌾𐌰 𐌹𐌶𐍅𐌹𐍃 𐍆𐍂𐌰𐌼 𐌰𐍄𐍄𐌹𐌽, 𐌰𐌷𐌼𐌰𐌽 𐍃𐌿𐌽𐌾𐍉𐍃 𐌹𐌶𐌴𐌹 𐍆𐍂𐌰𐌼 𐌰𐍄𐍄𐌹𐌽 𐌿𐍂𐍂𐌹𐌽𐌽𐌹𐌸, 𐍃𐌰 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌴𐌹𐌸 𐌱𐌹 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, '𐌾𐌰𐌷 𐌸𐌰𐌽 𐌾𐌿𐍃 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌴𐌹𐌸, 𐌿𐌽𐍄𐌴 𐍆𐍂𐌰𐌼 𐍆𐍂𐌿𐌼𐌰 𐌼𐌹𐌸 𐌼𐌹𐍃 𐍃𐌹𐌾𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Ã𐌰𐍄𐌰 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌴𐌹 𐌽𐌹 𐌰𐍆𐌼𐌰𐍂𐌶𐌾𐌰𐌹𐌽𐌳𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, '𐌿𐍃 𐌲𐌰𐌵𐌿𐌼𐌸𐌹𐌼 𐌳𐍂𐌴𐌹𐌱𐌰𐌽𐌳 𐌹𐌶𐍅𐌹𐍃; 𐌰𐌺𐌴𐌹 𐌵𐌹𐌼𐌹𐌸 𐍈𐌴𐌹𐌻𐌰, 𐌴𐌹 𐍃𐌰𐍈𐌰𐌶𐌿𐌷 𐌹𐌶𐌴𐌹 𐌿𐍃𐌵𐌹𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃, 𐌸𐌿𐌲𐌲𐌺𐌴𐌹𐌸 𐌷𐌿𐌽𐍃𐌻𐌰 𐍃𐌰𐌻𐌾𐌰𐌽 𐌲𐌿𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, '𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐍄𐌰𐌿𐌾𐌰𐌽𐌳, 𐌿𐌽𐍄𐌴 𐌽𐌹 𐌿𐍆𐌺𐌿𐌽𐌸𐌴𐌳𐌿𐌽 𐌰𐍄𐍄𐌰𐌽 𐌽𐌹𐌷 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, '𐌰𐌺𐌴𐌹 𐌸𐌰𐍄𐌰 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌴𐌹 𐌱𐌹𐌸𐌴 𐌵𐌹𐌼𐌰𐌹 𐍃𐍉 𐍈𐌴𐌹𐌻𐌰 𐌹𐌶𐌴, 𐌲𐌰𐌼𐌿𐌽𐌴𐌹𐌸 𐌸𐌹𐌶𐌴 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌵𐌰𐌸 𐌹𐌶𐍅𐌹𐍃. 𐌹𐌸 𐌸𐌰𐍄𐌰 𐌹𐌶𐍅𐌹𐍃 𐍆𐍂𐌰𐌼 𐍆𐍂𐌿𐌼𐌰 𐌽𐌹 𐌵𐌰𐌸, 𐌿𐌽𐍄𐌴 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐍅𐌰𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, '𐌹𐌸 𐌽𐌿 𐌲𐌰𐌲𐌲𐌰 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 𐍃𐌰𐌽𐌳𐌾𐌰𐌽𐌳𐌹𐌽 𐌼𐌹𐌺, 𐌾𐌰𐌷 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌿𐍃 𐌹𐌶𐍅𐌹𐍃 𐌽𐌹 𐍆𐍂𐌰𐌹𐌷𐌽𐌹𐌸 𐌼𐌹𐌺: 𐍈𐌰𐌸 𐌲𐌰𐌲𐌲𐌹𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, '𐌰𐌺𐌴𐌹 𐌿𐌽𐍄𐌴 𐌸𐌰𐍄𐌰 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌲𐌰𐌿𐍂𐌹𐌸𐌰 𐌲𐌰𐌳𐌰𐌿𐌱𐌹𐌳𐌰 𐌹𐌶𐍅𐌰𐍂 𐌷𐌰𐌹𐍂𐍄𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, '𐌰𐌺𐌴𐌹 𐌹𐌺 𐍃𐌿𐌽𐌾𐌰 𐌹𐌶𐍅𐌹𐍃 𐌵𐌹𐌸𐌰: 𐌱𐌰𐍄𐌹𐌶𐍉 𐌹𐍃𐍄 𐌹𐌶𐍅𐌹𐍃 𐌴𐌹 𐌹𐌺 𐌲𐌰𐌻𐌴𐌹𐌸𐌰𐌿; 𐌿𐌽𐍄𐌴 𐌾𐌰𐌱𐌰𐌹 𐌹𐌺 𐌽𐌹 𐌲𐌰𐌻𐌴𐌹𐌸𐌰, 𐍀𐌰𐍂𐌰𐌺𐌻𐌴𐍄𐌿𐍃 𐌽𐌹 𐌵𐌹𐌼𐌹𐌸 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃; 𐌰𐌸𐌸𐌰𐌽 𐌾𐌰𐌱𐌰𐌹 𐌲𐌰𐌲𐌲𐌰, 𐍃𐌰𐌽𐌳𐌾𐌰 𐌹𐌽𐌰 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, '𐌾𐌰𐌷 𐌵𐌹𐌼𐌰𐌽𐌳𐍃 𐌹𐍃 𐌲𐌰𐍃𐌰𐌺𐌹𐌸 𐌸𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸 𐌱𐌹 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄 𐌾𐌰𐌷 𐌱𐌹 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌹𐌸𐌰 𐌾𐌰𐌷 𐌱𐌹 𐍃𐍄𐌰𐌿𐌰;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, '𐌱𐌹 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄 𐍂𐌰𐌹𐌷𐍄𐌹𐍃, [𐌸𐌰𐍄𐌰] 𐌸𐌰𐍄𐌴𐌹 𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳 𐌳𐌿 𐌼𐌹𐍃;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, '𐌹𐌸 𐌱𐌹 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌹𐌸𐌰, 𐌸𐌰𐍄𐌴𐌹 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌲𐌰𐌲𐌲𐌰, 𐌾𐌰𐌷 𐌽𐌹 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐍃𐌰𐌹𐍈𐌹𐌸 𐌼𐌹𐌺;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, '𐌹𐌸 𐌱𐌹 𐍃𐍄𐌰𐌿𐌰, 𐌸𐌰𐍄𐌴𐌹 𐍃𐌰 𐍂𐌴𐌹𐌺𐍃 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃 𐌰𐍆𐌳𐍉𐌼𐌹𐌸𐍃 𐍅𐌰𐍂𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, '𐌽𐌰𐌿𐌷 𐌲𐌰𐌽𐍉𐌷 𐍃𐌺𐌰𐌻 𐌵𐌹𐌸𐌰𐌽 𐌹𐌶𐍅𐌹𐍃, 𐌰𐌺𐌴𐌹 𐌽𐌹 𐌼𐌰𐌲𐌿𐌸 𐍆𐍂𐌰𐌱𐌰𐌹𐍂𐌰𐌽 𐌽𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, '𐌹𐌸 𐌸𐌰𐌽 𐌵𐌹𐌼𐌹𐌸 𐌾𐌰𐌹𐌽𐍃, 𐌰𐌷𐌼𐌰 𐍃𐌿𐌽𐌾𐍉𐍃, 𐌱𐍂𐌹𐌲𐌲𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐍃𐌿𐌽𐌾𐌰𐌹; 𐌽𐌹𐌷 𐌸𐌰𐌽 𐍂𐍉𐌳𐌴𐌹𐌸 𐌰𐍆 𐍃𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌰𐌺 𐍃𐍅𐌰 𐍆𐌹𐌻𐌿 𐍃𐍅𐌴 𐌷𐌰𐌿𐍃𐌴𐌹𐌸 𐍂𐍉𐌳𐌴𐌹𐌸, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐌰𐌽𐌰𐍅𐌰𐌹𐍂𐌸𐍉 𐌲𐌰𐍄𐌴𐌹𐌷𐌹𐌸 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, '𐌾𐌰𐌹𐌽𐍃 𐌼𐌹𐌺 𐌷𐌰𐌿𐌷𐌴𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌿𐍃 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌽𐌹𐌼𐌹𐌸 𐌾𐌰𐌷 𐌲𐌰𐍄𐌴𐌹𐌷𐌹𐌸 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, '𐌰𐌻𐌻 𐌸𐌰𐍄𐌴𐌹 𐌰𐌹𐌷 𐌰𐍄𐍄𐌰, 𐌼𐌴𐌹𐌽 𐌹𐍃𐍄; 𐌳𐌿𐌷𐌸𐌴 𐌵𐌰𐌸 𐌸𐌰𐍄𐌴𐌹 𐌿𐍃 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌽𐌹𐌼𐌹𐌸 𐌾𐌰𐌷 𐌲𐌰𐍄𐌴𐌹𐌷𐌹𐌸 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, '𐌻𐌴𐌹𐍄𐌹𐌻 𐌽𐌰𐌿𐌷 𐌾𐌰𐌷 𐌽𐌹 𐍃𐌰𐌹𐍈𐌹𐌸 𐌼𐌹𐌺; 𐌾𐌰𐌷 𐌰𐍆𐍄𐍂𐌰 𐌻𐌴𐌹𐍄𐌹𐌻 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐌸 𐌼𐌹𐌺, 𐌿𐌽𐍄𐌴 𐌹𐌺 𐌲𐌰𐌲𐌲𐌰 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌿𐍃 𐌸𐌰𐌹𐌼 𐍃𐌹𐍀𐍉𐌽𐌾𐌰𐌼 𐌳𐌿 𐍃𐌹𐍃 𐌼𐌹𐍃𐍃𐍉: 𐍈𐌰 𐌹𐍃𐍄 𐌸𐌰𐍄𐌰 𐌸𐌰𐍄𐌴𐌹 𐌵𐌹𐌸𐌹𐌸 𐌿𐌽𐍃𐌹𐍃: 𐌻𐌴𐌹𐍄𐌹𐌻 𐌴𐌹 𐌽𐌹 𐍃𐌰𐌹𐍈𐌹𐌸 𐌼𐌹𐌺, 𐌾𐌰𐌷 𐌰𐍆𐍄𐍂𐌰 𐌻𐌴𐌹𐍄𐌹𐌻 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐌸 𐌼𐌹𐌺, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌲𐌰𐌲𐌲𐌰 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, '𐌵𐌴𐌸𐌿𐌽𐌿𐌷: 𐌸𐌰𐍄𐌰 𐍈𐌰 𐍃𐌹𐌾𐌰𐌹 𐌸𐌰𐍄𐌴𐌹 𐌵𐌹𐌸𐌹𐌸: 𐌻𐌴𐌹𐍄𐌹𐌻, 𐌽𐌹 𐍅𐌹𐍄𐌿𐌼 𐍈𐌰 𐌵𐌹𐌸𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, '𐌹𐌸 𐌹𐌴𐍃𐌿𐍃 𐍅𐌹𐍃𐍃𐌿𐌷 𐌸𐌰𐍄𐌴𐌹 𐍅𐌹𐌻𐌳𐌴𐌳𐌿𐌽 𐌹𐌽𐌰 𐍆𐍂𐌰𐌹𐌷𐌽𐌰𐌽 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌹𐌼: 𐌱𐌹 𐌸𐌰𐍄𐌰 𐍃𐍉𐌺𐌴𐌹𐌸 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌸𐌰𐍄𐌴𐌹 𐌵𐌰𐌸: 𐌻𐌴𐌹𐍄𐌹𐌻 𐌾𐌰𐌷 𐌽𐌹 𐍃𐌰𐌹𐍈𐌹𐌸 𐌼𐌹𐌺, 𐌾𐌰𐌷 𐌰𐍆𐍄𐍂𐌰 𐌻𐌴𐌹𐍄𐌹𐌻 𐌾𐌰𐌷 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐌸 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, '𐌰𐌼𐌴𐌽, 𐌰𐌼𐌴𐌽, 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃 𐌸𐌴𐌹 𐌲𐍂𐌴𐌹𐍄𐌹𐌸 𐌾𐌰𐌷 𐌲𐌰𐌿𐌽𐍉𐌸 𐌾𐌿𐍃, 𐌹𐌸 𐌼𐌰𐌽𐌰𐍃𐌴𐌸𐍃 𐍆𐌰𐌲𐌹𐌽𐍉𐌸; 𐌾𐌿𐍃 𐍃𐌰𐌿𐍂𐌲𐌰𐌽𐌳𐌰𐌽𐍃 𐍅𐌰𐌹𐍂𐌸𐌹𐌸, 𐌰𐌺𐌴𐌹 𐍃𐍉 𐍃𐌰𐌿𐍂𐌲𐌰 𐌹𐌶𐍅𐌰𐍂𐌰 𐌳𐌿 𐍆𐌰𐌷𐌴𐌳𐌰𐌹 𐍅𐌰𐌹𐍂𐌸𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, '𐌵𐌹𐌽𐍉, 𐌸𐌰𐌽 𐌱𐌰𐌹𐍂𐌹𐌸, 𐍃𐌰𐌿𐍂𐌲𐌰 𐌷𐌰𐌱𐌰𐌹𐌳, 𐌿𐌽𐍄𐌴 𐌵𐌰𐌼 𐍈𐌴𐌹𐌻𐌰 𐌹𐌶𐍉𐍃; 𐌹𐌸 𐌱𐌹𐌸𐌴 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽 𐌹𐍃𐍄 𐌱𐌰𐍂𐌽, 𐌽𐌹 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌽𐌹 𐌲𐌰𐌼𐌰𐌽 𐌸𐌹𐌶𐍉𐍃 𐌰𐌲𐌻𐍉𐌽𐍃 𐍆𐌰𐌿𐍂𐌰 𐍆𐌰𐌷𐌴𐌳𐌰𐌹, 𐌿𐌽𐍄𐌴 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐍃 𐍅𐌰𐍂𐌸 𐌼𐌰𐌽𐌽𐌰 𐌹𐌽 𐍆𐌰𐌹𐍂𐍈𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, '𐌾𐌰𐌷 𐌸𐌰𐌽 𐌾𐌿𐍃 𐌰𐌿𐌺 𐌽𐌿 𐍃𐌰𐌿𐍂𐌲𐌰 𐌷𐌰𐌱𐌰𐌹𐌸, 𐌹𐌸 𐌰𐍆𐍄𐍂𐌰 𐍃𐌰𐌹𐍈𐌰 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐍆𐌰𐌲𐌹𐌽𐍉𐌸 𐌹𐌶𐍅𐌰𐍂 𐌷𐌰𐌹𐍂𐍄𐍉, 𐌾𐌰𐌷 𐌸𐍉 𐍆𐌰𐌷𐌴𐌳 𐌹𐌶𐍅𐌰𐍂𐌰 𐌽𐌹 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌽𐌹𐌼𐌹𐌸 𐌰𐍆 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, '𐌾𐌰𐌷 𐌹𐌽 𐌾𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌳𐌰𐌲𐌰 𐌼𐌹𐌺 𐌽𐌹 𐍆𐍂𐌰𐌹𐌷𐌽𐌹𐌸 𐍅𐌰𐌹𐌷𐍄𐌰𐌹𐍃. 𐌰𐌼𐌴𐌽 𐌰𐌼𐌴𐌽, 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌸𐌹𐍃𐍈𐌰𐌷 𐌸𐌴𐌹 𐌱𐌹𐌳𐌾𐌹𐌸 𐌰𐍄𐍄𐌰𐌽 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌲𐌹𐌱𐌹𐌸 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, '𐌿𐌽𐌳 𐌷𐌹𐍄𐌰 𐌽𐌹 𐌱𐌴𐌳𐌿𐌸 𐌽𐌹 𐍅𐌰𐌹𐌷𐍄𐌰𐌹𐍃 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰; 𐌱𐌹𐌳𐌾𐌰𐌹𐌸 𐌾𐌰𐌷 𐌽𐌹𐌼𐌹𐌸, 𐌴𐌹 𐍆𐌰𐌷𐌴𐌸𐍃 𐌹𐌶𐍅𐌰𐍂𐌰 𐍃𐌹𐌾𐌰𐌹 𐌿𐍃𐍆𐌿𐌻𐌻𐌹𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, '𐌸𐌰𐍄𐌰 𐌹𐌽 𐌲𐌰𐌾𐌿𐌺𐍉𐌼 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃; 𐌰𐌺𐌴𐌹 𐌵𐌹𐌼𐌹𐌸 𐍈𐌴𐌹𐌻𐌰, 𐌸𐌰𐌽𐌿𐌷 𐌹𐌶𐍅𐌹𐍃 𐌽𐌹 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌹𐌽 𐌲𐌰𐌾𐌿𐌺𐍉𐌼 𐍂𐍉𐌳𐌾𐌰, 𐌰𐌺 𐌰𐌽𐌳𐌰𐌿𐌲𐌹𐌱𐌰 𐌱𐌹 𐌰𐍄𐍄𐌰𐌽 𐌲𐌰𐍄𐌴𐌹𐌷𐌰 𐌹𐌶𐍅𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, '𐌹𐌽 𐌾𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌳𐌰𐌲𐌰 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌱𐌹𐌳𐌾𐌹𐌸, 𐌾𐌰𐌷 𐌽𐌹 𐌵𐌹𐌸𐌰 𐌹𐌶𐍅𐌹𐍃 𐌸𐌴𐌹 𐌹𐌺 𐌱𐌹𐌳𐌾𐌰𐌿 𐌰𐍄𐍄𐌰𐌽 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, '𐌰𐌺 𐍃𐌹𐌻𐌱𐌰 𐌰𐍄𐍄𐌰 𐍆𐍂𐌹𐌾𐍉𐌸 𐌹𐌶𐍅𐌹𐍃, 𐌿𐌽𐍄𐌴 𐌾𐌿𐍃 𐌼𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌳𐌴𐌳𐌿𐌸 𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌴𐌳𐌿𐌸 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰 𐌿𐍂𐍂𐌰𐌽𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, '𐌿𐌶𐌿𐌷𐌹𐌳𐌳𐌾𐌰 𐍆𐍂𐌰𐌼 𐌰𐍄𐍄𐌹𐌽 𐌾𐌰𐌷 𐌰𐍄𐌹𐌳𐌳𐌾𐌰 𐌹𐌽 𐌸𐌰𐌽𐌰 𐍆𐌰𐌹𐍂𐍈𐌿; 𐌰𐍆𐍄𐍂𐌰 𐌱𐌹𐌻𐌴𐌹𐌸𐌰 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌾𐌰𐌷 𐌲𐌰𐌲𐌲𐌰 𐌳𐌿 𐌰𐍄𐍄𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌸𐌰𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐌹𐍃: 𐍃𐌰𐌹, 𐌽𐌿 𐌰𐌽𐌳𐌰𐌿𐌲𐌹𐌱𐌰 𐍂𐍉𐌳𐌴𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐌾𐌿𐌺𐍉𐌽𐍉 𐌽𐌹 𐌰𐌹𐌽𐍉𐌷𐌿𐌽 𐌵𐌹𐌸𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, '𐌽𐌿 𐍅𐌹𐍄𐌿𐌼 𐌴𐌹 𐌸𐌿 𐌺𐌰𐌽𐍄 𐌰𐌻𐌻𐌰, 𐌾𐌰𐌷 𐌽𐌹 𐌸𐌰𐍂𐍆𐍄 𐌴𐌹 𐌸𐌿𐌺 𐍈𐌰𐍃 𐍆𐍂𐌰𐌹𐌷𐌽𐌰𐌹; 𐌱𐌹 𐌸𐌰𐌼𐌼𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌼 𐌸𐌰𐍄𐌴𐌹 𐌸𐌿 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰 𐌿𐍂𐍂𐌰𐌽𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌽𐌿 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, '𐍃𐌰𐌹, 𐌵𐌹𐌼𐌹𐌸 𐍈𐌴𐌹𐌻𐌰 𐌾𐌰𐌷 𐌽𐌿 𐌵𐌰𐌼, 𐌴𐌹 𐌳𐌹𐍃𐍄𐌰𐌷𐌾𐌰𐌳𐌰 𐍈𐌰𐍂𐌾𐌹𐌶𐌿𐌷 𐌳𐌿 𐍃𐌴𐌹𐌽𐌰𐌹𐌼, 𐌾𐌰𐌷 𐌼𐌹𐌺 𐌰𐌹𐌽𐌰𐌽𐌰 𐌱𐌹𐌻𐌴𐌹𐌸𐌹𐌸; 𐌾𐌰𐌷 𐌽𐌹 𐌹𐌼 𐌰𐌹𐌽𐍃, 𐌿𐌽𐍄𐌴 𐌰𐍄𐍄𐌰 𐌼𐌹𐌸 𐌼𐌹𐍃 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, '𐌸𐌰𐍄𐌰 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐌸𐌴𐌹 𐌹𐌽 𐌼𐌹𐍃 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌰𐌹𐌲𐌴𐌹𐌸. 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌰𐌲𐌻𐍉𐌽𐍃 𐌷𐌰𐌱𐌰𐌹𐌳; 𐌰𐌺𐌴𐌹 𐌸𐍂𐌰𐍆𐍃𐍄𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃, 𐌹𐌺 𐌲𐌰𐌾𐌹𐌿𐌺𐌰𐌹𐌳𐌰 𐌸𐌰𐌽𐌰 𐍆𐌰𐌹𐍂𐍈𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Ã𐌰𐍄𐌰 𐍂𐍉𐌳𐌹𐌳𐌰 𐌹𐌴𐍃𐌿𐍃 𐌿𐌶𐌿𐌷𐌷𐍉𐍆 𐌰𐌿𐌲𐍉𐌽𐌰 𐍃𐌴𐌹𐌽𐌰 𐌳𐌿 𐌷𐌹𐌼𐌹𐌽𐌰 𐌾𐌰𐌷 𐌵𐌰𐌸: 𐌰𐍄𐍄𐌰, 𐌵𐌰𐌼 𐍈𐌴𐌹𐌻𐌰, 𐌷𐌰𐌿𐌷𐌴𐌹 𐌸𐌴𐌹𐌽𐌰𐌽𐌰 𐍃𐌿𐌽𐌿, 𐌴𐌹 𐍃𐌿𐌽𐌿𐍃 𐌸𐌴𐌹𐌽𐍃 𐌷𐌰𐌿𐌷𐌾𐌰𐌹 𐌸𐌿𐌺;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, '𐍃𐍅𐌰𐍃𐍅𐌴 𐌰𐍄𐌲𐌰𐍆𐍄 𐌹𐌼𐌼𐌰 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐌰𐌻𐌻𐌰𐌹𐌶𐌴 𐌻𐌴𐌹𐌺𐌴, 𐌴𐌹 𐌰𐌻𐌻 𐌸𐌰𐍄𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌹𐌼𐌼𐌰, 𐌲𐌹𐌱𐌰𐌹 𐌹𐌼 𐌻𐌹𐌱𐌰𐌹𐌽 𐌰𐌹𐍅𐌴𐌹𐌽𐍉𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, '𐍃𐍉𐌷 𐌸𐌰𐌽 𐌹𐍃𐍄 𐍃𐍉 𐌰𐌹𐍅𐌴𐌹𐌽𐍉 𐌻𐌹𐌱𐌰𐌹𐌽𐍃, 𐌴𐌹 𐌺𐌿𐌽𐌽𐌴𐌹𐌽𐌰 𐌸𐌿𐌺 𐌰𐌹𐌽𐌰𐌽𐌰 𐍃𐌿𐌽𐌾𐌰𐌽𐌰 𐌲𐌿𐌸 𐌾𐌰𐌷 𐌸𐌰𐌽𐌴𐌹 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐍃, 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, '𐌹𐌺 𐌸𐌿𐌺 𐌷𐌰𐌿𐌷𐌹𐌳𐌰 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹; 𐍅𐌰𐌿𐍂𐍃𐍄𐍅 𐌿𐍃𐍄𐌰𐌿𐌷 𐌸𐌰𐍄𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃 𐌳𐌿 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, '𐌾𐌰𐌷 𐌽𐌿 𐌷𐌰𐌿𐌷𐌴𐌹 𐌼𐌹𐌺, 𐌸𐌿 𐌰𐍄𐍄𐌰, 𐌰𐍄 𐌸𐌿𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍅𐌿𐌻𐌸𐌰𐌿, 𐌸𐌰𐌽𐌴𐌹 𐌷𐌰𐌱𐌰𐌹𐌳𐌰 𐌰𐍄 𐌸𐌿𐍃, 𐍆𐌰𐌿𐍂𐌸𐌹𐌶𐌴𐌹 𐍃𐌰 𐍆𐌰𐌹𐍂𐍈𐌿𐍃 𐍅𐌴𐍃𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, '𐌲𐌰𐌱𐌰𐌹𐍂𐌷𐍄𐌹𐌳𐌰 𐌸𐌴𐌹𐌽𐌰𐍄𐌰 𐌽𐌰𐌼𐍉 𐌼𐌰𐌽𐌽𐌰𐌼 𐌸𐌰𐌽𐌶𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿. 𐌸𐌴𐌹𐌽𐌰𐌹 𐍅𐌴𐍃𐌿𐌽 𐌾𐌰𐌷 𐌼𐌹𐍃 𐌰𐍄𐌲𐌰𐍆𐍄 𐌹𐌽𐍃, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐍅𐌰𐌿𐍂𐌳 𐌸𐌴𐌹𐌽𐌰𐍄𐌰 𐌲𐌰𐍆𐌰𐍃𐍄𐌰𐌹𐌳𐌴𐌳𐌿𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, '𐌽𐌿 𐌿𐍆𐌺𐌿𐌽𐌸𐌰 𐌴𐌹 𐌰𐌻𐌻𐌰 𐌸𐍉𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃, 𐌰𐍄 𐌸𐌿𐍃 𐍃𐌹𐌽𐌳;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, '𐌿𐌽𐍄𐌴 𐌸𐍉 𐍅𐌰𐌿𐍂𐌳𐌰 𐌸𐍉𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃, 𐌰𐍄𐌲𐌰𐍆 𐌹𐌼, 𐌾𐌰𐌷 𐌴𐌹𐍃 𐌽𐌴𐌼𐌿𐌽 𐌱𐌹 𐍃𐌿𐌽𐌾𐌰𐌹 𐌸𐌰𐍄𐌴𐌹 𐍆𐍂𐌰𐌼 𐌸𐌿𐍃 𐌿𐍂𐍂𐌰𐌽𐌽, 𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌴𐌳𐌿𐌽 𐌸𐌰𐍄𐌴𐌹 𐌸𐌿 𐌼𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, '𐌹𐌺 𐌱𐌹 𐌹𐌽𐍃 𐌱𐌹𐌳𐌾𐌰; 𐌽𐌹 𐌱𐌹 𐌸𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸 𐌱𐌹𐌳𐌾𐌰, 𐌰𐌺 𐌱𐌹 𐌸𐌰𐌽𐍃 𐌸𐌰𐌽𐌶𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃, 𐌿𐌽𐍄𐌴 𐌸𐌴𐌹𐌽𐌰𐌹 𐍃𐌹𐌽𐌳.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, '𐌾𐌰𐌷 𐌼𐌴𐌹𐌽𐌰 𐌰𐌻𐌻𐌰 𐌸𐌴𐌹𐌽𐌰 𐍃𐌹𐌽𐌳 𐌾𐌰𐌷 𐌸𐌴𐌹𐌽𐌰 𐌼𐌴𐌹𐌽𐌰, 𐌾𐌰𐌷 𐌷𐌰𐌿𐌷𐌹𐌸𐍃 𐌹𐌼 𐌹𐌽 𐌸𐌰𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, '𐌽𐌹 𐌸𐌰𐌽𐌰𐍃𐌴𐌹𐌸𐍃 𐌹𐌼 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿; 𐌹𐌸 𐌸𐌰𐌹 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐍃𐌹𐌽𐌳, 𐌾𐌰𐌷 𐌹𐌺 𐌳𐌿 𐌸𐌿𐍃 𐌲𐌰𐌲𐌲𐌰. 𐌰𐍄𐍄𐌰 𐍅𐌴𐌹𐌷𐌰, 𐍆𐌰𐍃𐍄𐌰𐌹 𐌹𐌽𐍃 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌸𐌰𐌽𐌶𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌽𐌰 𐌰𐌹𐌽 𐍃𐍅𐌰𐍃𐍅𐌴 𐍅𐌹𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, '𐌸𐌰𐌽 𐍅𐌰𐍃 𐌼𐌹𐌸 𐌹𐌼 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿, 𐌹𐌺 𐍆𐌰𐍃𐍄𐌰𐌹𐌳𐌰 𐌹𐌽𐍃 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰. 𐌸𐌰𐌽𐌶𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃 𐌲𐌰𐍆𐌰𐍃𐍄𐌰𐌹𐌳𐌰, 𐌾𐌰𐌷 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌿𐍃 𐌹𐌼 𐌽𐌹 𐍆𐍂𐌰𐌵𐌹𐍃𐍄𐌽𐍉𐌳𐌰, 𐌽𐌹𐌱𐌰 𐍃𐌰 𐍃𐌿𐌽𐌿𐍃 𐍆𐍂𐌰𐌻𐌿𐍃𐍄𐌰𐌹𐍃, 𐌴𐌹 𐌸𐌰𐍄𐌰 𐌲𐌰𐌼𐌴𐌻𐌹𐌳𐍉 𐌿𐍃𐍆𐌿𐌻𐌻𐌹𐌸 𐍅𐌰𐌿𐍂𐌸𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, '𐌹𐌸 𐌽𐌿 𐌳𐌿 𐌸𐌿𐍃 𐌲𐌰𐌲𐌲𐌰, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐍂𐍉𐌳𐌾𐌰 𐌹𐌽 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐌰𐌹, 𐌴𐌹 𐌷𐌰𐌱𐌰𐌹𐌽𐌰 𐍆𐌰𐌷𐌴𐌳 𐌼𐌴𐌹𐌽𐌰 𐌿𐍃𐍆𐌿𐌻𐌻𐌹𐌳𐌰 𐌹𐌽 𐍃𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, '𐌹𐌺 𐌰𐍄𐌲𐌰𐍆 𐌹𐌼 𐍅𐌰𐌿𐍂𐌳 𐌸𐌴𐌹𐌽𐌰𐍄𐌰; 𐌾𐌰𐌷 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸𐍃 𐍆𐌹𐌾𐌰𐌹𐌳𐌰 𐌹𐌽𐍃, 𐌿𐌽𐍄𐌴 𐌽𐌹 𐍃𐌹𐌽𐌳 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌹𐌺 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌽𐌹 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, '𐌽𐌹 𐌱𐌹𐌳𐌾𐌰 𐌴𐌹 𐌿𐍃𐌽𐌹𐌼𐌰𐌹𐍃 𐌹𐌽𐍃 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿, 𐌰𐌺 𐌴𐌹 𐌱𐌰𐌹𐍂𐌲𐌰𐌹𐍃 𐌹𐌼 𐍆𐌰𐌿𐍂𐌰 𐌸𐌰𐌼𐌼𐌰 𐌿𐌽𐍃𐌴𐌻𐌾𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, '𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌽𐌹 𐍃𐌹𐌽𐌳, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌹𐌺 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌽𐌹 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, '𐍅𐌴𐌹𐌷𐌰𐌹 𐌹𐌽𐍃 𐌹𐌽 𐍃𐌿𐌽𐌾𐌰𐌹; 𐍅𐌰𐌿𐍂𐌳 𐌸𐌴𐌹𐌽𐌰𐍄𐌰 𐍃𐌿𐌽𐌾𐌰 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, '𐍃𐍅𐌰𐍃𐍅𐌴 𐌼𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐍃 𐌹𐌽 𐌼𐌰𐌽𐌰𐍃𐌴𐌸, 𐍃𐍅𐌰𐌷 𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌹𐌽𐍃 𐌹𐌽 𐌸𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌳.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, '𐌾𐌰𐌷 𐍆𐍂𐌰𐌼 𐌹𐌼 𐌹𐌺 𐍅𐌴𐌹𐌷𐌰 𐌼𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌽𐌰 𐌾𐌰𐌷 𐌴𐌹𐍃 𐍅𐌴𐌹𐌷𐌰𐌹 𐌹𐌽 𐍃𐌿𐌽𐌾𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, '𐌰𐌸𐌸𐌰𐌽 𐌽𐌹 𐌱𐌹 𐌸𐌰𐌽𐍃 𐌱𐌹𐌳𐌾𐌰 𐌰𐌹𐌽𐌰𐌽𐍃, 𐌰𐌺 𐌱𐌹 𐌸𐌰𐌽𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐌹𐍂𐌷 𐍅𐌰𐌿𐍂𐌳𐌰 𐌹𐌶𐌴 𐌳𐌿 𐌼𐌹𐍃,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, '𐌴𐌹 𐌰𐌻𐌻𐌰𐌹 𐌰𐌹𐌽 𐍃𐌹𐌾𐌰𐌹𐌽𐌰, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌸𐌿, 𐌰𐍄𐍄𐌰, 𐌹𐌽 𐌼𐌹𐍃 𐌾𐌰𐌷 𐌹𐌺 𐌹𐌽 𐌸𐌿𐍃, 𐌴𐌹 𐌾𐌰𐌷 𐌸𐌰𐌹 𐌹𐌽 𐌿𐌲𐌲𐌺𐌹𐍃 𐌰𐌹𐌽 𐍃𐌹𐌾𐌰𐌹𐌽𐌰, 𐌴𐌹 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌹 𐌸𐌰𐍄𐌴𐌹 𐌸𐌿 𐌼𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, '𐌾𐌰𐌷 𐌹𐌺 𐍅𐌿𐌻𐌸𐌿 𐌸𐌰𐌽𐌴𐌹 𐌲𐌰𐍆𐍄 𐌼𐌹𐍃, 𐌲𐌰𐍆 𐌹𐌼, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌽𐌰 𐌰𐌹𐌽, 𐍃𐍅𐌰𐍃𐍅𐌴 𐍅𐌹𐍄 𐌰𐌹𐌽 𐍃𐌹𐌾𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, '𐌹𐌺 𐌹𐌽 𐌹𐌼 𐌾𐌰𐌷 𐌸𐌿 𐌹𐌽 𐌼𐌹𐍃, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌽𐌰 𐌿𐍃𐍄𐌰𐌿𐌷𐌰𐌽𐌰𐌹 𐌳𐌿 𐌰𐌹𐌽𐌰𐌼𐌼𐌰, 𐌾𐌰𐌷 𐌺𐌿𐌽𐌽𐌴𐌹 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸𐍃 𐌸𐌰𐍄𐌴𐌹 𐌸𐌿 𐌼𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐍃 𐌾𐌰𐌷 𐍆𐍂𐌹𐌾𐍉𐌳𐌴𐍃 𐌹𐌽𐍃, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌼𐌹𐌺 𐍆𐍂𐌹𐌾𐍉𐌳𐌴𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, '𐌰𐍄𐍄𐌰, 𐌸𐌰𐍄𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃, 𐍅𐌹𐌻𐌾𐌰𐌿 𐌴𐌹 𐌸𐌰𐍂𐌴𐌹 𐌹𐌼 𐌹𐌺, 𐌾𐌰𐌷 𐌸𐌰𐌹 𐍃𐌹𐌾𐌰𐌹𐌽𐌰 𐌼𐌹𐌸 𐌼𐌹𐍃, 𐌴𐌹 𐍃𐌰𐌹𐍈𐌰𐌹𐌽𐌰 𐍅𐌿𐌻𐌸𐌿 𐌼𐌴𐌹𐌽𐌰𐌽𐌰 𐌸𐌰𐌽𐌴𐌹 𐌲𐌰𐍆𐍄 𐌼𐌹𐍃, 𐌿𐌽𐍄𐌴 𐍆𐍂𐌹𐌾𐍉𐌳𐌴𐍃 𐌼𐌹𐌺 𐍆𐌰𐌿𐍂 𐌲𐌰𐍃𐌺𐌰𐍆𐍄 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, '𐌰𐍄𐍄𐌰 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌰, 𐌾𐌰𐌷 𐍃𐍉 𐌼𐌰𐌽𐌰𐍃𐌴𐌸𐍃 𐌸𐌿𐌺 𐌽𐌹 𐌿𐍆𐌺𐌿𐌽𐌸𐌰; 𐌹𐌸 𐌹𐌺 𐌸𐌿𐌺 𐌺𐌿𐌽𐌸𐌰. 𐌾𐌰𐌷 𐌸𐌰𐌹 𐌿𐍆𐌺𐌿𐌽𐌸𐌴𐌳𐌿𐌽 𐌸𐌰𐍄𐌴𐌹 𐌸𐌿 𐌼𐌹𐌺 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, '𐌾𐌰𐌷 𐌲𐌰𐌺𐌰𐌽𐌽𐌹𐌳𐌰 𐌹𐌼 𐌽𐌰𐌼𐍉 𐌸𐌴𐌹𐌽𐌰𐍄𐌰 𐌾𐌰𐌷 𐌺𐌰𐌽𐌽𐌾𐌰, 𐌴𐌹 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌸𐍉𐌴𐌹 𐍆𐍂𐌹𐌾𐍉𐌳𐌴𐍃 𐌼𐌹𐌺, 𐌹𐌽 𐌹𐌼 𐍃𐌹𐌾𐌰𐌹 𐌾𐌰𐌷 𐌹𐌺 𐌹𐌽 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Ã𐌰𐍄𐌰 𐌵𐌹𐌸𐌰𐌽𐌳𐍃 𐌹𐌴𐍃𐌿𐍃 𐌿𐍃𐌹𐌳𐌳𐌾𐌰 𐌼𐌹𐌸 𐍃𐌹𐍀𐍉𐌽𐌾𐌰𐌼 𐍃𐌴𐌹𐌽𐌰𐌹𐌼 𐌿𐍆𐌰𐍂 𐍂𐌹𐌽𐌽𐍉𐌽 𐌸𐍉 𐌺𐌰𐌹𐌳𐍂𐍉𐌽, 𐌸𐌰𐍂𐌴𐌹 𐍅𐌰𐍃 𐌰𐌿𐍂𐍄𐌹𐌲𐌰𐍂𐌳𐍃, 𐌹𐌽 𐌸𐌰𐌽𐌴𐌹 𐌲𐌰𐌻𐌰𐌹𐌸 𐌹𐌴𐍃𐌿𐍃 𐌾𐌰𐌷 𐍃𐌹𐍀𐍉𐌽𐌾𐍉𐍃 𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, '𐍅𐌹𐍃𐍃𐌿𐌷 𐌸𐌰𐌽 𐌾𐌰𐌷 𐌹𐌿𐌳𐌰𐍃 𐍃𐌰 𐌲𐌰𐌻𐌴𐍅𐌾𐌰𐌽𐌳𐍃 𐌹𐌽𐌰 𐌸𐌰𐌽𐌰 𐍃𐍄𐌰𐌳, 𐌸𐌰𐍄𐌴𐌹 𐌿𐍆𐍄𐌰 𐌲𐌰ï𐌳𐌳𐌾𐌰 𐌹𐌴𐍃𐌿𐍃 𐌾𐌰𐌹𐌽𐌰𐍂 𐌼𐌹𐌸 𐍃𐌹𐍀𐍉𐌽𐌾𐌰𐌼 𐍃𐌴𐌹𐌽𐌰𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, '𐌹𐌸 𐌹𐌿𐌳𐌰𐍃 𐌽𐌰𐌼 𐌷𐌰𐌽𐍃𐌰 𐌾𐌰𐌷 𐌸𐌹𐌶𐌴 𐌲𐌿𐌳𐌾𐌰𐌽𐌴 𐌾𐌰𐌷 𐍆𐌰𐍂𐌴𐌹𐍃𐌰𐌹𐌴 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐌰𐌽𐍃, 𐌹𐌳𐌳𐌾𐌿𐌷 𐌾𐌰𐌹𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐍃 𐌼𐌹𐌸 𐍃𐌺𐌴𐌹𐌼𐌰𐌼 𐌾𐌰𐌷 𐌷𐌰𐌹𐌶𐌰𐌼 𐌾𐌰𐌷 𐍅𐌴𐍀𐌽𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, '𐌹𐌸 𐌹𐌴𐍃𐌿𐍃 𐍅𐌹𐍄𐌰𐌽𐌳𐍃 𐌰𐌻𐌻𐌰 𐌸𐍉𐌴𐌹 𐌵𐌴𐌼𐌿𐌽 𐌰𐌽𐌰 𐌹𐌽𐌰, 𐌿𐍃𐌲𐌰𐌲𐌲𐌰𐌽𐌳𐍃 𐌿𐍄 𐌵𐌰𐌸 𐌹𐌼: 𐍈𐌰𐌽𐌰 𐍃𐍉𐌺𐌴𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, '𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌼𐌼𐌰 𐌵𐌴𐌸𐌿𐌽: 𐌹𐌴𐍃𐌿, 𐌸𐌰𐌽𐌰 𐌽𐌰𐌶𐍉𐍂𐌰𐌹𐌿. 𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌹𐌼 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌺 𐌹𐌼. 𐍃𐍄𐍉𐌸𐌿𐌷 𐌸𐌰𐌽 𐌾𐌰𐌷 𐌹𐌿𐌳𐌰𐍃 𐍃𐌰 𐌻𐌴𐍅𐌾𐌰𐌽𐌳𐍃 𐌹𐌽𐌰 𐌼𐌹𐌸 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, '𐌸𐌰𐍂𐌿𐌷 𐍃𐍅𐌴 𐌵𐌰𐌸 𐌹𐌼 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌼, 𐌲𐌰𐌻𐌹𐌸𐌿𐌽 𐌹𐌱𐌿𐌺𐌰𐌹 𐌾𐌰𐌷 𐌲𐌰𐌳𐍂𐌿𐍃𐌿𐌽 𐌳𐌰𐌻𐌰𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, '𐌸𐌰𐌸𐍂𐍉𐌷 𐌸𐌰𐌽 𐌹𐌽𐍃 𐌰𐍆𐍄𐍂𐌰 𐍆𐍂𐌰𐌷: 𐍈𐌰𐌽𐌰 𐍃𐍉𐌺𐌴𐌹𐌸? 𐌹𐌸 𐌴𐌹𐍃 𐌵𐌴𐌸𐌿𐌽: 𐌹𐌴𐍃𐌿, 𐌸𐌰𐌽𐌰 𐌽𐌰𐌶𐍉𐍂𐌰𐌹𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌵𐌰𐌸 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌹𐌺 𐌹𐌼; 𐌾𐌰𐌱𐌰𐌹 𐌽𐌿 𐌼𐌹𐌺 𐍃𐍉𐌺𐌴𐌹𐌸, 𐌻𐌴𐍄𐌹𐌸 𐌸𐌰𐌽𐍃 𐌲𐌰𐌲𐌲𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, '𐌴𐌹 𐌿𐍃𐍆𐌿𐌻𐌻𐌽𐍉𐌳𐌴𐌳𐌹 𐌸𐌰𐍄𐌰 𐍅𐌰𐌿𐍂𐌳 𐌸𐌰𐍄𐌴𐌹 𐌵𐌰𐌸, 𐌴𐌹 𐌸𐌰𐌽𐌶𐌴𐌹 𐌰𐍄𐌲𐌰𐍆𐍄 𐌼𐌹𐍃, 𐌽𐌹 𐍆𐍂𐌰𐌵𐌹𐍃𐍄𐌹𐌳𐌰 𐌹𐌶𐌴 𐌰𐌹𐌽𐌿𐌼𐌼𐌴𐌷𐌿𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, '𐌹𐌸 𐍃𐌴𐌹𐌼𐍉𐌽 𐍀𐌰𐌹𐍄𐍂𐌿𐍃 𐌷𐌰𐌱𐌰𐌽𐌳𐍃 𐌷𐌰𐌹𐍂𐌿, 𐌿𐍃𐌻𐌰𐌿𐌺 𐌹𐌽𐌰 𐌾𐌰𐌷 𐍃𐌻𐍉𐌷 𐌸𐌹𐍃 𐌰𐌿𐌷𐌿𐌼𐌹𐍃𐍄𐌹𐌽𐍃 𐌲𐌿𐌳𐌾𐌹𐌽𐍃 𐍃𐌺𐌰𐌻𐌺 𐌾𐌰𐌷 𐌰𐍆𐌼𐌰𐌹𐌼𐌰𐌹𐍄 𐌹𐌼𐌼𐌰 𐌰𐌿𐍃𐍉 𐍄𐌰𐌹𐌷𐍃𐍅𐍉; 𐍃𐌰𐌷 𐌸𐌰𐌽 𐌷𐌰𐌹𐍄𐌰𐌽𐍃 𐍅𐌰𐍃 𐌽𐌰𐌼𐌹𐌽 𐌼𐌰𐌻𐌺𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌹𐌴𐍃𐌿𐍃 𐌳𐌿 𐍀𐌰𐌹𐍄𐍂𐌰𐌿: 𐌻𐌰𐌲𐌴𐌹 𐌸𐌰𐌽𐌰 𐌷𐌰𐌹𐍂𐌿 𐌹𐌽 𐍆𐍉𐌳𐍂. 𐍃𐍄𐌹𐌺𐌻 𐌸𐌰𐌽𐌴𐌹 𐌲𐌰𐍆 𐌼𐌹𐍃 𐌰𐍄𐍄𐌰, 𐌽𐌹𐌿 𐌳𐍂𐌹𐌲𐌺𐌰𐌿 𐌸𐌰𐌽𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, '𐌸𐌰𐍂𐌿𐌷 𐌷𐌰𐌽𐍃𐌰 𐌾𐌰𐌷 𐍃𐌰 𐌸𐌿𐍃𐌿𐌽𐌳𐌹𐍆𐌰𐌸𐍃 𐌾𐌰𐌷 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍉𐍃 𐌹𐌿𐌳𐌰𐌹𐌴 𐌿𐌽𐌳𐌲𐍂𐌹𐍀𐌿𐌽 𐌹𐌴𐍃𐌿 𐌾𐌰𐌷 𐌲𐌰𐌱𐌿𐌽𐌳𐌿𐌽 𐌹𐌽𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, '𐌾𐌰𐌷 𐌲𐌰𐍄𐌰𐌿𐌷𐌿𐌽 𐌹𐌽𐌰 𐌳𐌿 𐌰𐌽𐌽𐌹𐌽 𐍆𐍂𐌿𐌼𐌹𐍃𐍄; 𐍃𐌰 𐍅𐌰𐍃 𐌰𐌿𐌺 𐍃𐍅𐌰𐌹𐌷𐍂𐌰 𐌺𐌰𐌾𐌰𐍆𐌹𐌽, 𐍃𐌰𐌴𐌹 𐍅𐌰𐍃 𐌰𐌿𐌷𐌿𐌼𐌹𐍃𐍄𐍃 𐍅𐌴𐌹𐌷𐌰 𐌸𐌹𐍃 𐌰𐍄𐌰𐌸𐌽𐌾𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, '𐍅𐌰𐍃𐌿𐌷 𐌸𐌰𐌽 𐌺𐌰𐌾𐌰𐍆𐌰, 𐍃𐌰𐌴𐌹 𐌲𐌰𐍂𐌰𐌲𐌹𐌽𐍉𐌳𐌰 𐌹𐌿𐌳𐌰𐌹𐌿𐌼 𐌸𐌰𐍄𐌴𐌹 𐌱𐌰𐍄𐌹𐌶𐍉 𐌹𐍃𐍄 𐌰𐌹𐌽𐌰𐌽𐌰 𐌼𐌰𐌽𐌽𐌰𐌽 𐍆𐍂𐌰𐌵𐌹𐍃𐍄𐌾𐌰𐌽 𐍆𐌰𐌿𐍂 𐌼𐌰𐌽𐌰𐌲𐌴𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, '𐌸𐌰𐍂𐌿𐌷 𐌻𐌰𐌹𐍃𐍄𐌹𐌳𐌰 𐌹𐌴𐍃𐌿 𐍃𐌴𐌹𐌼𐍉𐌽 𐍀𐌰𐌹𐍄𐍂𐌿𐍃 𐌾𐌰𐌷 𐌰𐌽𐌸𐌰𐍂 𐍃𐌹𐍀𐍉𐌽𐌴𐌹𐍃. 𐍃𐌰𐌷 𐌸𐌰𐌽 𐍃𐌹𐍀𐍉𐌽𐌴𐌹𐍃 𐍅𐌰𐍃 𐌺𐌿𐌽𐌸𐍃 𐌸𐌰𐌼𐌼𐌰 𐌲𐌿𐌳𐌾𐌹𐌽 𐌾𐌰𐌷 𐌼𐌹𐌸𐌹𐌽𐌽𐌲𐌰𐌻𐌰𐌹𐌸 𐌼𐌹𐌸 𐌹𐌴𐍃𐌿𐌰 𐌹𐌽 𐍂𐍉𐌷𐍃𐌽 𐌸𐌹𐍃 𐌲𐌿𐌳𐌾𐌹𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, '𐌹𐌸 𐍀𐌰𐌹𐍄𐍂𐌿𐍃 𐍃𐍄𐍉𐌸 𐌰𐍄 𐌳𐌰𐌿𐍂𐍉𐌼 𐌿𐍄𐌰. 𐌸𐌰𐍂𐌿𐌷 𐌿𐍃𐌹𐌳𐌳𐌾𐌰 𐌿𐍄 𐍃𐌰 𐍃𐌹𐍀𐍉𐌽𐌴𐌹𐍃 𐌰𐌽𐌸𐌰𐍂, 𐍃𐌰𐌴𐌹 𐍅𐌰𐍃 𐌺𐌿𐌽𐌸𐍃 𐌸𐌰𐌼𐌼𐌰 𐌲𐌿𐌳𐌾𐌹𐌽, 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌳𐌰𐌿𐍂𐌰𐍅𐌰𐍂𐌳𐌰𐌹 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰𐌿𐌷 𐌹𐌽𐌽 𐍀𐌰𐌹𐍄𐍂𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌾𐌰𐌹𐌽𐌰 𐌸𐌹𐍅𐌹, 𐍃𐍉 𐌳𐌰𐌿𐍂𐌰𐍅𐌰𐍂𐌳𐍉, 𐌳𐌿 𐍀𐌰𐌹𐍄𐍂𐌰𐌿: 𐌹𐌱𐌰𐌹 𐌾𐌰𐌷 𐌸𐌿 𐌸𐌹𐌶𐌴 𐍃𐌹𐍀𐍉𐌽𐌾𐌴 𐌹𐍃 𐌸𐌹𐍃 𐌼𐌰𐌽𐍃? 𐌹𐌸 𐌹𐍃 𐌵𐌰𐌸: 𐌽𐌹 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, '𐌸𐌰𐍂𐌿𐌷 𐍃𐍄𐍉𐌸𐌿𐌽 𐍃𐌺𐌰𐌻𐌺𐍉𐍃 𐌾𐌰𐌷 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍉𐍃 𐌷𐌰𐌿𐍂𐌾𐌰 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌰𐌽𐍃, 𐌿𐌽𐍄𐌴 𐌺𐌰𐌻𐌳 𐍅𐌰𐍃, 𐌾𐌰𐌷 𐍅𐌰𐍂𐌼𐌹𐌳𐌴𐌳𐌿𐌽 𐍃𐌹𐌺; 𐌾𐌰𐌷 𐌸𐌰𐌽 𐍅𐌰𐍃 𐌼𐌹𐌸 𐌹𐌼 𐍀𐌰𐌹𐍄𐍂𐌿𐍃 𐍃𐍄𐌰𐌽𐌳𐌰𐌽𐌳𐍃 𐌾𐌰𐌷 𐍅𐌰𐍂𐌼𐌾𐌰𐌽𐌳𐍃 𐍃𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, '𐌹𐌸 𐍃𐌰 𐌰𐌿𐌷𐌿𐌼𐌹𐍃𐍄𐌰 𐌲𐌿𐌳𐌾𐌰 𐍆𐍂𐌰𐌷 𐌹𐌴𐍃𐌿 𐌱𐌹 𐍃𐌹𐍀𐍉𐌽𐌾𐌰𐌽𐍃 𐌹𐍃 𐌾𐌰𐌷 𐌱𐌹 𐌻𐌰𐌹𐍃𐌴𐌹𐌽 𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌼𐌼𐌰 𐌹𐌴𐍃𐌿𐍃: 𐌹𐌺 𐌰𐌽𐌳𐌰𐌿𐌲𐌾𐍉 𐍂𐍉𐌳𐌹𐌳𐌰 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐌰𐌹; 𐌹𐌺 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌻𐌰𐌹𐍃𐌹𐌳𐌰 𐌹𐌽 𐌲𐌰𐌵𐌿𐌼𐌸𐌰𐌹 𐌾𐌰𐌷 𐌹𐌽 𐌲𐌿𐌳𐌷𐌿𐍃𐌰, 𐌸𐌰𐍂𐌴𐌹 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐌲𐌰𐌵𐌹𐌼𐌰𐌽𐌳, 𐌾𐌰𐌷 𐌸𐌹𐌿𐌱𐌾𐍉 𐌽𐌹 𐍂𐍉𐌳𐌹𐌳𐌰 𐍅𐌰𐌹𐌷𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, '𐍈𐌹𐍃 𐌼𐌹𐌺 𐍆𐍂𐌰𐌹𐌷𐌽𐌹𐍃? 𐍆𐍂𐌰𐌹𐌷𐌽 𐌸𐌰𐌽𐍃 𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍈𐌰 𐍂𐍉𐌳𐌹𐌳𐌴𐌳𐌾𐌰𐌿 𐌳𐌿 𐌹𐌼; 𐍃𐌰𐌹, 𐌸𐌰𐌹 𐍅𐌹𐍄𐌿𐌽 𐌸𐌰𐍄𐌴𐌹 𐌵𐌰𐌸 𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, '𐌹𐌸 𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌰𐌽𐌳𐌹𐌽 𐌹𐌼𐌼𐌰, 𐍃𐌿𐌼𐍃 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐌴 𐍃𐍄𐌰𐌽𐌳𐌰𐌽𐌳𐍃 𐌲𐌰𐍆 𐍃𐌻𐌰𐌷 𐌻𐍉𐍆𐌹𐌽 𐌹𐌴𐍃𐌿𐌰 𐌵𐌰𐌸𐌿𐌷: 𐍃𐍅𐌰𐌿 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌹𐍃 𐌸𐌰𐌼𐌼𐌰 𐍂𐌴𐌹𐌺𐌹𐍃𐍄𐌹𐌽 𐌲𐌿𐌳𐌾𐌹𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌾𐌰𐌱𐌰𐌹 𐌿𐌱𐌹𐌻𐌰𐌱𐌰 𐍂𐍉𐌳𐌹𐌳𐌰, 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌴𐌹 𐌱𐌹 𐌸𐌰𐍄𐌰 𐌿𐌱𐌹𐌻, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌾𐌰𐌱𐌰𐌹 𐍅𐌰𐌹𐌻𐌰, 𐌳𐌿𐍈𐌴 𐌼𐌹𐌺 𐍃𐌻𐌰𐌷𐌹𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, '𐌸𐌰𐌽𐌿𐌷 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌹𐌽𐌰 𐌰𐌽𐌽𐌰𐍃 𐌲𐌰𐌱𐌿𐌽𐌳𐌰𐌽𐌰𐌽𐌰 𐌳𐌿 𐌺𐌰𐌾𐌰𐍆𐌹𐌽, 𐌸𐌰𐌼𐌼𐌰 𐌼𐌰𐌹𐍃𐍄𐌹𐌽 𐌲𐌿𐌳𐌾𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, '𐌹𐌸 𐍃𐌴𐌹𐌼𐍉𐌽 𐍀𐌰𐌹𐍄𐍂𐌿𐍃 𐍅𐌰𐍃 𐍃𐍄𐌰𐌽𐌳𐌰𐌽𐌳𐍃 𐌾𐌰𐌷 𐍅𐌰𐍂𐌼𐌾𐌰𐌽𐌳𐍃 𐍃𐌹𐌺. 𐌸𐌰𐍂𐌿𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌽𐌹𐌿 𐌾𐌰𐌷 𐌸𐌿 𐌸𐌹𐌶𐌴 𐍃𐌹𐍀𐍉𐌽𐌾𐌴 𐌸𐌹𐍃 𐌹𐍃? 𐌹𐌸 𐌹𐍃 𐌰𐍆𐌰𐌹𐌰𐌹𐌺 𐌾𐌰𐌷 𐌵𐌰𐌸: 𐌽𐌴, 𐌽𐌹 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, '𐌵𐌰𐌸 𐍃𐌿𐌼𐍃 𐌸𐌹𐌶𐌴 𐍃𐌺𐌰𐌻𐌺𐌴 𐌸𐌹𐍃 𐌼𐌰𐌹𐍃𐍄𐌹𐌽𐍃 𐌲𐌿𐌳𐌾𐌹𐌽𐍃, 𐍃𐌰𐌷 𐌽𐌹𐌸𐌾𐌹𐍃 𐍅𐌰𐍃 𐌸𐌰𐌼𐌼𐌴𐌹 𐌰𐍆𐌼𐌰𐌹𐌼𐌰𐌹𐍄 𐍀𐌰𐌹𐍄𐍂𐌿𐍃 𐌰𐌿𐍃𐍉: 𐌽𐌹𐌿 𐌸𐌿𐌺 𐍃𐌰𐍈 𐌹𐌺 𐌹𐌽 𐌰𐌿𐍂𐍄𐌹𐌲𐌰𐍂𐌳𐌰 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, '𐌸𐌰𐍂𐌿𐌷 𐌰𐍆𐍄𐍂𐌰 𐌰𐍆𐌰𐌹𐌰𐌹𐌺 𐍀𐌰𐌹𐍄𐍂𐌿𐍃, 𐌾𐌰𐌷 𐍃𐌿𐌽𐍃 𐌷𐌰𐌽𐌰 𐌷𐍂𐌿𐌺𐌹𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, '𐌹𐌸 𐌴𐌹𐍃 𐍄𐌰𐌿𐌷𐌿𐌽 𐌹𐌴𐍃𐌿 𐍆𐍂𐌰𐌼 𐌺𐌰𐌾𐌰𐍆𐌹𐌽 𐌹𐌽 𐍀𐍂𐌰𐌹𐍄𐍉𐍂𐌹𐌰𐌿𐌽. 𐌸𐌰𐌽𐌿𐌷 𐍅𐌰𐍃 𐌼𐌰𐌿𐍂𐌲𐌹𐌽𐍃. 𐌹𐌸 𐌴𐌹𐍃 𐌽𐌹 𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌽 𐌹𐌽 𐍀𐍂𐌰𐌹𐍄𐍉𐍂𐌹𐌰, 𐌴𐌹 𐌽𐌹 𐌱𐌹𐍃𐌰𐌿𐌻𐌽𐍉𐌳𐌴𐌳𐌴𐌹𐌽𐌰, 𐌰𐌺 𐌼𐌰𐍄𐌹𐌳𐌴𐌳𐌴𐌹𐌽𐌰 𐍀𐌰𐍃𐍇𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, '𐌸𐌰𐍂𐌿𐌷 𐌰𐍄𐌹𐌳𐌳𐌾𐌰 𐌿𐍄 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃 𐌳𐌿 𐌹𐌼 𐌾𐌰𐌷 𐌵𐌰𐌸: 𐍈𐍉 𐍅𐍂𐍉𐌷𐌴 𐌱𐌰𐌹𐍂𐌹𐌸 𐌰𐌽𐌰 𐌸𐌰𐌽𐌰 𐌼𐌰𐌽𐌽𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, '𐌰𐌽𐌳𐌷𐍉𐍆𐌿𐌽 𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽 𐌳𐌿 𐌹𐌼𐌼𐌰: 𐌽𐌹𐌷 𐍅𐌴𐍃𐌹 𐍃𐌰 𐌿𐌱𐌹𐌻𐍄𐍉𐌾𐌹𐍃, 𐌽𐌹 𐌸𐌰𐌿 𐍅𐌴𐌹𐍃 𐌰𐍄𐌲𐌴𐌱𐌴𐌹𐌼𐌰 𐌸𐌿𐍃 𐌹𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌹𐌼 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃: 𐌽𐌹𐌼𐌹𐌸 𐌹𐌽𐌰 𐌾𐌿𐍃 𐌾𐌰𐌷 𐌱𐌹 𐍅𐌹𐍄𐍉𐌳𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰 𐍃𐍄𐍉𐌾𐌹𐌸 𐌹𐌽𐌰. 𐌹𐌸 𐌴𐌹𐍃 𐌵𐌴𐌸𐌿𐌽𐌿𐌷 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃: 𐌿𐌽𐍃𐌹𐍃 𐌽𐌹 𐍃𐌺𐌿𐌻𐌳 𐌹𐍃𐍄 𐌿𐍃𐌵𐌹𐌼𐌰𐌽 𐌼𐌰𐌽𐌽𐌴 𐌰𐌹𐌽𐌿𐌼𐌼𐌴𐌷𐌿𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, '𐌴𐌹 𐍅𐌰𐌿𐍂𐌳 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐍃𐍆𐌿𐌻𐌻𐌽𐍉𐌳𐌴𐌳𐌹, 𐌸𐌰𐍄𐌴𐌹 𐌵𐌰𐌸, 𐌱𐌰𐌽𐌳𐍅𐌾𐌰𐌽𐌳𐍃 𐍈𐌹𐌻𐌴𐌹𐌺𐌰𐌼𐌼𐌰 𐌳𐌰𐌿𐌸𐌰𐌿 𐍃𐌺𐌿𐌻𐌳𐌰 𐌲𐌰𐍃𐍅𐌹𐌻𐍄𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, '𐌲𐌰𐌻𐌰𐌹𐌸 𐌹𐌽 𐍀𐍂𐌰𐌹𐍄𐌰𐌿𐍂𐌹𐌰 𐌰𐍆𐍄𐍂𐌰 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃 𐌾𐌰𐌷 𐍅𐍉𐍀𐌹𐌳𐌰 𐌹𐌴𐍃𐌿 𐌵𐌰𐌸𐌿𐌷 𐌹𐌼𐌼𐌰: 𐌸𐌿 𐌹𐍃 𐌸𐌹𐌿𐌳𐌰𐌽𐍃 𐌹𐌿𐌳𐌰𐌹𐌴?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌰𐌱𐌿 𐌸𐌿𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌸𐌿 𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌹𐍃 𐌸𐌰𐌿 𐌰𐌽𐌸𐌰𐍂𐌰𐌹 𐌸𐌿𐍃 𐌵𐌴𐌸𐌿𐌽 𐌱𐌹 𐌼𐌹𐌺?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, '𐌰𐌽𐌳𐌷𐍉𐍆 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃: 𐍅𐌰𐌹𐍄𐌴𐌹 𐌹𐌺 𐌹𐌿𐌳𐌰𐌹𐌿𐍃 𐌹𐌼? 𐍃𐍉 𐌸𐌹𐌿𐌳𐌰 𐌸𐌴𐌹𐌽𐌰 𐌾𐌰𐌷 𐌲𐌿𐌳𐌾𐌰𐌽𐍃 𐌰𐌽𐌰𐍆𐌿𐌻𐌷𐌿𐌽 𐌸𐌿𐌺 𐌼𐌹𐍃; 𐍈𐌰 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌴𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌹 𐌼𐌴𐌹𐌽𐌰 𐌽𐌹𐍃𐍄 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿; 𐌹𐌸 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐍅𐌴𐍃𐌹 𐌼𐌴𐌹𐌽𐌰 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌹, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍉𐍃 𐌼𐌴𐌹𐌽𐌰𐌹 𐌿𐍃𐌳𐌰𐌿𐌳𐌹𐌳𐌴𐌳𐌴𐌹𐌽𐌰, 𐌴𐌹 𐌽𐌹 𐌲𐌰𐌻𐌴𐍅𐌹𐌸𐍃 𐍅𐌴𐍃𐌾𐌰𐌿 𐌹𐌿𐌳𐌰𐌹𐌿𐌼. 𐌹𐌸 𐌽𐌿 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌹 𐌼𐌴𐌹𐌽𐌰 𐌽𐌹𐍃𐍄 𐌸𐌰𐌸𐍂𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌹𐌼𐌼𐌰 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃: 𐌰𐌽 𐌽𐌿𐌷 𐌸𐌹𐌿𐌳𐌰𐌽𐍃 𐌹𐍃 𐌸𐌿? 𐌰𐌽𐌳𐌷𐌰𐍆𐌾𐌰𐌽𐌳𐍃 𐌹𐌴𐍃𐌿𐍃: 𐌸𐌿 𐌵𐌹𐌸𐌹𐍃 𐌴𐌹 𐌸𐌹𐌿𐌳𐌰𐌽𐍃 𐌹𐌼 𐌹𐌺. 𐌹𐌺 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐍃 𐌹𐌼 𐌾𐌰𐌷 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 𐌵𐌰𐌼 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌴𐌹 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰𐌿 𐍃𐌿𐌽𐌾𐌰𐌹. 𐍈𐌰𐌶𐌿𐌷 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐍃𐌿𐌽𐌾𐍉𐍃, 𐌷𐌰𐌿𐍃𐌴𐌹𐌸 𐍃𐍄𐌹𐌱𐌽𐍉𐍃 𐌼𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, '𐌸𐌰𐌽𐌿𐌷 𐌵𐌰𐌸 𐌹𐌼𐌼𐌰 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃: 𐍈𐌰 𐌹𐍃𐍄 𐍃𐍉 𐍃𐌿𐌽𐌾𐌰! 𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌰𐌽𐌳𐍃 𐌲𐌰𐌻𐌰𐌹𐌸 𐌿𐍄 𐌳𐌿 𐌹𐌿𐌳𐌰𐌹𐌿𐌼 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌹𐌼: 𐌹𐌺 𐌰𐌹𐌽𐍉𐌷𐌿𐌽 𐍆𐌰𐌹𐍂𐌹𐌽𐍉 𐌽𐌹 𐌱𐌹𐌲𐌹𐍄𐌰 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, '𐌹𐌸 𐌹𐍃𐍄 𐌱𐌹𐌿𐌷𐍄𐌹 𐌹𐌶𐍅𐌹𐍃 𐌴𐌹 𐌰𐌹𐌽𐌰𐌽𐌰 𐌹𐌶𐍅𐌹𐍃 𐍆𐍂𐌰𐌻𐌴𐍄𐌰𐌿 𐌹𐌽 𐍀𐌰𐍃𐍇𐌰; 𐍅𐌹𐌻𐌴𐌹𐌳𐌿 𐌽𐌿 𐌴𐌹 𐍆𐍂𐌰𐌻𐌴𐍄𐌰𐌿 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐌽𐌰 𐌸𐌹𐌿𐌳𐌰𐌽 𐌹𐌿𐌳𐌰𐌹𐌴?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, '𐌹𐌸 𐌴𐌹𐍃 𐌷𐍂𐍉𐍀𐌹𐌳𐌴𐌳𐌿𐌽 𐌰𐍆𐍄𐍂𐌰 𐌰𐌻𐌻𐌰𐌹 𐌵𐌹𐌸𐌰𐌽𐌳𐌰𐌽𐍃: 𐌽𐌴 𐌸𐌰𐌽𐌰, 𐌰𐌺 𐌱𐌰𐍂𐌰𐌱𐌱𐌰𐌽; 𐍃𐌰𐌷 𐌸𐌰𐌽 𐍅𐌰𐍃 𐍃𐌰 𐌱𐌰𐍂𐌰𐌱𐌱𐌰 𐍅𐌰𐌹𐌳𐌴𐌳𐌾𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Ã𐌰𐌽𐌿𐌷 𐌸𐌰𐌽 𐌽𐌰𐌼 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃 𐌹𐌴𐍃𐌿 𐌾𐌰𐌷 𐌿𐍃𐌱𐌻𐌰𐌲𐌲𐍅.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, '𐌾𐌰𐌷 𐌸𐌰𐌹 𐌲𐌰𐌳𐍂𐌰𐌿𐌷𐍄𐌴𐌹𐍃 𐌿𐍃𐍅𐌿𐌽𐌳𐌿𐌽 𐍅𐌹𐍀𐌾𐌰 𐌿𐍃 𐌸𐌰𐌿𐍂𐌽𐌿𐌼 𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌲𐌹𐌳𐌴𐌳𐌿𐌽 𐌹𐌼𐌼𐌰 𐌰𐌽𐌰 𐌷𐌰𐌿𐌱𐌹𐌳 𐌾𐌰𐌷 𐍅𐌰𐍃𐍄𐌾𐌰𐌹 𐍀𐌰𐌿𐍂𐍀𐌿𐍂𐍉𐌳𐌰𐌹 𐌲𐌰𐍅𐌰𐍃𐌹𐌳𐌴𐌳𐌿𐌽 𐌹𐌽𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, '𐌾𐌰𐌷 𐌵𐌴𐌸𐌿𐌽: 𐌷𐌰𐌹𐌻𐍃 𐌸𐌹𐌿𐌳𐌰𐌽𐍃 𐌹𐌿𐌳𐌰𐌹𐌴! 𐌾𐌰𐌷 𐌲𐌴𐌱𐌿𐌽 𐌹𐌼𐌼𐌰 𐍃𐌻𐌰𐌷𐌹𐌽𐍃 𐌻𐍉𐍆𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, '𐌰𐍄𐌹𐌳𐌳𐌾𐌰 𐌰𐍆𐍄𐍂𐌰 𐌿𐍄 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌹𐌼: 𐍃𐌰𐌹, 𐌰𐍄𐍄𐌹𐌿𐌷𐌰 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽𐌰 𐌿𐍄, 𐌴𐌹 𐍅𐌹𐍄𐌴𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌽𐌹 𐌰𐌹𐌽𐍉𐌷𐌿𐌽 𐍆𐌰𐌹𐍂𐌹𐌽𐍉 𐌱𐌹𐌲𐌰𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, '𐌸𐌰𐍂𐌿𐌷 𐌿𐍃𐌹𐌳𐌳𐌾𐌰 𐌿𐍄 𐌹𐌴𐍃𐌿𐍃 𐌱𐌰𐌹𐍂𐌰𐌽𐌳𐍃 𐌸𐌰𐌽𐌰 𐌸𐌰𐌿𐍂𐌽𐌴𐌹𐌽𐌰𐌽 𐍅𐌰𐌹𐍀 𐌾𐌰𐌷 𐌸𐍉 𐍀𐌰𐌿𐍂𐍀𐌿𐍂𐍉𐌳𐍉𐌽 𐍅𐌰𐍃𐍄𐌾𐌰. 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌹𐌼: 𐍃𐌰 𐌹𐍃𐍄 𐍃𐌰 𐌼𐌰𐌽𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, '𐌸𐌰𐍂𐌿𐌷 𐌱𐌹𐌸𐌴 𐍃𐌴𐍈𐌿𐌽 𐌹𐌽𐌰 𐌸𐌰𐌹 𐌼𐌰𐌹𐍃𐍄𐌰𐌽𐍃 𐌲𐌿𐌳𐌾𐌰𐌽𐍃 𐌾𐌰𐌷 𐌰𐌽𐌳𐌱𐌰𐌷𐍄𐍉𐍃, 𐌷𐍂𐍉𐍀𐌹𐌳𐌴𐌳𐌿𐌽 𐌵𐌹𐌸𐌰𐌽𐌳𐌰𐌽𐍃: 𐌿𐍃𐌷𐍂𐌰𐌼𐌴𐌹, 𐌿𐍃𐌷𐍂𐌰𐌼𐌴𐌹 𐌹𐌽𐌰! 𐌵𐌰𐌸 𐌹𐌼 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃: 𐌽𐌹𐌼𐌹𐌸 𐌹𐌽𐌰 𐌾𐌿𐍃 𐌾𐌰𐌷 𐌷𐍂𐌰𐌼𐌾𐌹𐌸. 𐌹𐌸 𐌹𐌺 𐍆𐌰𐌹𐍂𐌹𐌽𐌰 𐌹𐌽 𐌹𐌼𐌼𐌰 𐌽𐌹 𐌱𐌹𐌲𐌹𐍄𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, '𐌰𐌽𐌳𐌷𐍉𐍆𐌿𐌽 𐌹𐌼𐌼𐌰 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃: 𐍅𐌴𐌹𐍃 𐍅𐌹𐍄𐍉𐌸 𐌰𐌹𐌷𐌿𐌼, 𐌾𐌰𐌷 𐌱𐌹 𐌸𐌰𐌼𐌼𐌰 𐍅𐌹𐍄𐍉𐌳𐌰 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰 𐍃𐌺𐌰𐌻 𐌲𐌰𐍃𐍅𐌹𐌻𐍄𐌰𐌽, 𐌿𐌽𐍄𐌴 𐍃𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐌲𐌿𐌳𐌹𐍃 𐍃𐌿𐌽𐌿 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, '𐌱𐌹𐌸𐌴 𐌲𐌰𐌷𐌰𐌿𐍃𐌹𐌳𐌰 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃 𐌸𐌰𐍄𐌰 𐍅𐌰𐌿𐍂𐌳, 𐌼𐌰𐌹𐍃 𐍉𐌷𐍄𐌰 𐍃𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, '𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌹𐌸 𐌹𐌽 𐍀𐍂𐌰𐌹𐍄𐌰𐌿𐍂𐌹𐌰 𐌰𐍆𐍄𐍂𐌰 𐌾𐌰𐌷 𐌵𐌰𐌸 𐌳𐌿 𐌹𐌴𐍃𐌿𐌰: 𐍈𐌰𐌸𐍂𐍉 𐌹𐍃 𐌸𐌿? 𐌹𐌸 𐌹𐌴𐍃𐌿𐍃 𐌰𐌽𐌳𐌰𐍅𐌰𐌿𐍂𐌳𐌹 𐌽𐌹 𐌲𐌰𐍆 𐌹𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, '𐌸𐌰𐍂𐌿𐌷 𐌵𐌰𐌸 𐌹𐌼𐌼𐌰 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃: 𐌳𐌿 𐌼𐌹𐍃 𐌽𐌹 𐍂𐍉𐌳𐌴𐌹𐍃? 𐌽𐌹𐌿 𐍅𐌰𐌹𐍃𐍄 𐌸𐌰𐍄𐌴𐌹 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐌰𐌹𐌷 𐌿𐍃𐌷𐍂𐌰𐌼𐌾𐌰𐌽 𐌸𐌿𐌺 𐌾𐌰𐌷 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐌰𐌹𐌷 𐍆𐍂𐌰𐌻𐌴𐍄𐌰𐌽 𐌸𐌿𐌺?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, '𐌰𐌽𐌳𐌷𐍉𐍆 𐌹𐌴𐍃𐌿𐍃: 𐌽𐌹 𐌰𐌹𐌷𐍄𐌴𐌳𐌴𐌹𐍃 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌾𐌴 𐌰𐌹𐌽𐌷𐌿𐌽 𐌰𐌽𐌰 𐌼𐌹𐌺, 𐌽𐌹𐌷 𐍅𐌴𐍃𐌹 𐌸𐌿𐍃 𐌰𐍄𐌲𐌹𐌱𐌰𐌽 𐌹𐌿𐍀𐌰𐌸𐍂𐍉; 𐌳𐌿𐌷𐌸𐌴 𐍃𐌰 𐌲𐌰𐌻𐌴𐍅𐌾𐌰𐌽𐌳𐍃 𐌼𐌹𐌺 𐌸𐌿𐍃 𐌼𐌰𐌹𐌶𐌴𐌹𐌽 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄 𐌷𐌰𐌱𐌰𐌹𐌳.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, '𐍆𐍂𐌰𐌼𐌿𐌷 𐌸𐌰𐌼𐌼𐌰 𐍃𐍉𐌺𐌹𐌳𐌰 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃 𐍆𐍂𐌰𐌻𐌴𐍄𐌰𐌽 𐌹𐌽𐌰. 𐌹𐌸 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐌷𐍂𐍉𐍀𐌹𐌳𐌴𐌳𐌿𐌽 𐌵𐌹𐌸𐌰𐌽𐌳𐌰𐌽𐍃: 𐌾𐌰𐌱𐌰𐌹 𐌸𐌰𐌽𐌰 𐍆𐍂𐌰𐌻𐌴𐍄𐌹𐍃, 𐌽𐌹 𐌹𐍃 𐍆𐍂𐌹𐌾𐍉𐌽𐌳𐍃 𐌺𐌰𐌹𐍃𐌰𐍂𐌰; 𐍃𐌰𐍈𐌰𐌶𐌿𐌷 𐌹𐌶𐌴𐌹 𐌸𐌹𐌿𐌳𐌰𐌽 𐍃𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐍄𐌰𐌿𐌾𐌹𐌸, 𐌰𐌽𐌳𐍃𐍄𐌰𐌽𐌳𐌹𐌸 𐌺𐌰𐌹𐍃𐌰𐍂𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, '𐌸𐌰𐌽𐌿𐌷 𐍀𐌴𐌹𐌻𐌰𐍄𐌿𐍃 𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳𐍃 𐌸𐌹𐌶𐌴....');
