INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, '.... 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐌹𐌽 𐍄𐌰𐌹𐌷𐍃𐍅𐍉𐌽 𐌲𐌿𐌳𐌹𐍃, 𐍃𐌰𐌴𐌹 𐌾𐌰𐌷 𐌱𐌹𐌳𐌾𐌹𐌸 𐍆𐌰𐌿𐍂 𐌿𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, '𐍈𐌰𐍃 𐌿𐌽𐍃 𐌰𐍆𐍃𐌺𐌰𐌹𐌳𐌰𐌹 𐌰𐍆 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃? 𐌰𐌲𐌻𐍉? 𐌸𐌰𐌿 𐌰𐌲𐌲𐍅𐌹𐌸𐌰? 𐌸𐌰𐌿 𐍅𐍂𐌰𐌺𐌾𐌰? 𐌸𐌰𐌿 𐌷𐌿𐌷𐍂𐌿𐍃? 𐌸𐌰𐌿 𐌽𐌰𐌵𐌰𐌳𐌴𐌹? 𐌸𐌰𐌿 𐍃𐌻𐌴𐌹𐌸𐌴𐌹? 𐌸𐌰𐌿 𐌷𐌰𐌹𐍂𐌿𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, '𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄 𐌸𐌰𐍄𐌴𐌹 𐌹𐌽 𐌸𐌿𐌺 𐌲𐌰𐌳𐌰𐌿𐌸𐌾𐌰𐌽𐌳𐌰 𐌰𐌻𐌻 𐌳𐌰𐌲𐌹𐍃, 𐍂𐌰𐌷𐌽𐌹𐌳𐌰𐌹 𐍅𐌴𐍃𐌿𐌼 𐍃𐍅𐌴 𐌻𐌰𐌼𐌱𐌰 𐍃𐌻𐌰𐌿𐌷𐍄𐌰𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, '𐌰𐌺𐌴𐌹 𐌹𐌽 𐌸𐌰𐌹𐌼 𐌰𐌻𐌻𐌰𐌹𐌼 𐌾𐌹𐌿𐌺𐌰𐌼 𐌸𐌰𐌹𐍂𐌷 𐌸𐌰𐌽𐌰 𐍆𐍂𐌹𐌾𐍉𐌽𐌳𐌰𐌽 𐌿𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, '𐌲𐌰𐍄𐍂𐌰𐌿𐌰 𐌰𐌿𐌺 𐌸𐌰𐍄𐌴𐌹 𐌽𐌹 𐌳𐌰𐌿𐌸𐌿𐍃 𐌽𐌹𐌷 𐌰𐌲𐌲𐌴𐌻𐌾𐌿𐍃 𐌽𐌹 (𐍂𐌴𐌹𐌺𐌾𐌰) 𐌽𐌹 𐌼𐌰𐌷𐍄𐌴𐌹𐍃 𐌽𐌹𐌷 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐍉 𐌽𐌹𐌷 𐌰𐌽𐌰𐍅𐌰𐌹𐍂𐌸𐍉,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, '𐌽𐌹𐌷 𐌷𐌰𐌿𐌷𐌹𐌸𐌰 𐌽𐌹𐌷 𐌳𐌹𐌿𐍀𐌹𐌸𐌰 𐌽𐌹𐌷 𐌲𐌰𐍃𐌺𐌰𐍆𐍄𐍃 (𐌰𐌽𐌸𐌰𐍂𐌰) 𐌼𐌰𐌲𐌹 𐌿𐌽𐍃 𐌰𐍆𐍃𐌺𐌰𐌹𐌳𐌰𐌽 𐌰𐍆 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹 𐌲𐌿𐌳𐌹𐍃 𐌸𐌹𐌶𐌰𐌹 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿, 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, '𐍃𐌿𐌽𐌾𐌰 𐌵𐌹𐌸𐌰 𐌽𐌹 𐍅𐌰𐌹𐌷𐍄 𐌻𐌹𐌿𐌲𐌰, 𐌼𐌹𐌸𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰𐌽𐌳𐌴𐌹𐌽 𐌼𐌹𐍃 𐌼𐌹𐌸𐍅𐌹𐍃𐍃𐌴𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌹 𐌹𐌽 𐌰𐌷𐌼𐌹𐌽 𐍅𐌴𐌹𐌷𐌰𐌼𐌼𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, '𐌸𐌰𐍄𐌴𐌹 𐍃𐌰𐌿𐍂𐌲𐌰 𐌼𐌹𐍃 𐌹𐍃𐍄 𐌼𐌹𐌺𐌹𐌻𐌰 𐌾𐌰𐌷 𐌿𐌽𐍈𐌴𐌹𐌻𐍉 𐌰𐌲𐌻𐍉 𐌷𐌰𐌹𐍂𐍄𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, '𐌿𐍃𐌱𐌹𐌳𐌰 𐌰𐌿𐌺 𐌰𐌽𐌰𐌸𐌰𐌹𐌼𐌰 𐍅𐌹𐍃𐌰𐌽 𐍃𐌹𐌻𐌱𐌰 𐌹𐌺 𐌰𐍆 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐍆𐌰𐌿𐍂 𐌱𐍂𐍉𐌸𐍂𐌿𐌽𐍃 𐌼𐌴𐌹𐌽𐌰𐌽𐍃 𐌸𐌰𐌽𐍃 𐍃𐌰𐌼𐌰𐌺𐌿𐌽𐌾𐌰𐌽𐍃 𐌱𐌹 𐌻𐌴𐌹𐌺𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, '𐌸𐌰𐌹𐌴𐌹 𐍃𐌹𐌽𐌳 𐌹𐍃𐍂𐌰𐌴𐌻𐌴𐌹𐍄𐌰𐌹, 𐌸𐌹𐌶𐌴𐌴𐌹 𐌹𐍃𐍄 𐍆𐍂𐌰𐍃𐍄𐌹𐍃𐌹𐌱𐌾𐌰 𐌾𐌰𐌷 𐍅𐌿𐌻𐌸𐌿𐍃 𐌾𐌰𐌷 𐍅𐌹𐍄𐍉𐌳𐌹𐍃 𐌲𐌰𐍂𐌰𐌹𐌳𐌴𐌹𐌽𐍃 𐌾𐌰𐌷 𐍄𐍂𐌹𐌲𐌲𐍅𐍉𐍃 𐌾𐌰𐌷 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐌰𐍃𐍃𐌿𐍃 𐌾𐌰𐌷 𐌲𐌰𐌷𐌰𐌹𐍄𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, '𐌸𐌹𐌶𐌴𐌴𐌹 𐌰𐍄𐍄𐌰𐌽𐍃, 𐌾𐌰𐌷 𐌿𐍃 𐌸𐌰𐌹𐌼𐌴𐌹 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌱𐌹 𐌻𐌴𐌹𐌺𐌰, 𐍃𐌰𐌴𐌹 𐌹𐍃𐍄 𐌿𐍆𐌰𐍂 𐌰𐌻𐌻𐌰𐌹𐌼 𐌲𐌿𐌸 𐌸𐌹𐌿𐌸𐌹𐌸𐍃 𐌹𐌽 𐌰𐌹𐍅𐌰𐌼, 𐌰𐌼𐌴𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, '𐌰𐌸𐌸𐌰𐌽 𐍃𐍅𐌴𐌸𐌰𐌿𐌷 𐌽𐌹 𐌿𐍃𐌳𐍂𐌰𐌿𐍃 𐍅𐌰𐌿𐍂𐌳 𐌲𐌿𐌳𐌹𐍃; 𐌽𐌹 𐌰𐌿𐌺 𐌰𐌻𐌻𐌰𐌹 𐌸𐌰𐌹 𐌿𐍃 𐌹𐍃𐍂𐌰𐌴𐌻𐌰 𐍃𐌹𐌽𐌳 𐌹𐍃𐍂𐌰𐌴𐌻,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, '𐌽𐌹𐌸~𐌸𐌰𐍄𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌽𐌰 𐍆𐍂𐌰𐌹𐍅 𐌰𐌱𐍂𐌰𐌷𐌰𐌼𐌹𐍃, 𐌰𐌻𐌻𐌰𐌹 𐌱𐌰𐍂𐌽𐌰, 𐌰𐌺: 𐌹𐌽 𐌹𐍃𐌰𐌺𐌰 𐌷𐌰𐌹𐍄𐌰𐌳𐌰 𐌸𐌿𐍃 𐍆𐍂𐌰𐌹𐍅,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, '𐌸𐌰𐍄~𐌹𐍃𐍄: 𐌽𐌹 𐌸𐍉 𐌱𐌰𐍂𐌽𐌰 𐌻𐌴𐌹𐌺𐌹𐍃 𐌱𐌰𐍂𐌽𐌰 𐌲𐌿𐌳𐌹𐍃, 𐌰𐌺 𐌱𐌰𐍂𐌽𐌰 𐌲𐌰𐌷𐌰𐌹𐍄𐌹𐍃 𐍂𐌰𐌷𐌽𐌾𐌰𐌽𐌳𐌰 𐌳𐌿 𐍆𐍂𐌰𐌹𐍅𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, '𐌲𐌰𐌷𐌰𐌹𐍄𐌹𐍃 𐌰𐌿𐌺 𐍅𐌰𐌿𐍂𐌳 𐌸𐌰𐍄~𐌹𐍃𐍄: 𐌱𐌹 𐌸𐌰𐌼𐌼𐌰 𐌼𐌴𐌻𐌰 𐌵𐌹𐌼𐌰, 𐌾𐌰𐌷 𐍅𐌰𐌹𐍂𐌸𐌹𐌸 𐍃𐌰𐍂𐍂𐌹𐌽 𐍃𐌿𐌽𐌿𐍃;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, '𐌰𐌸𐌸𐌰𐌽 𐌽𐌹 𐌸𐌰𐍄~𐌰𐌹𐌽, 𐌰𐌺 𐌾𐌰𐌷 𐍂𐌰𐌹𐌱𐌰𐌹𐌺𐌺𐌰 𐌿𐍃 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌲𐌰𐌻𐌹𐌲𐍂𐌾𐌰 𐌷𐌰𐌱𐌰𐌽𐌳𐌴𐌹 𐌹𐍃𐌰𐌺𐌹𐍃, 𐌰𐍄𐍄𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, '𐌰𐌸𐌸𐌰𐌽 𐌽𐌰𐌿𐌷𐌸𐌰𐌽𐌿𐌷 𐌲𐌰𐌱𐌰𐌿𐍂𐌰𐌽𐌰𐌹 𐍅𐌴𐍃𐌿𐌽, 𐌰𐌹𐌸𐌸𐌰𐌿 𐍄𐌰𐍅𐌹𐌳𐌴𐌳𐌴𐌹𐌽𐌰 𐍈𐌰 𐌸𐌹𐌿𐌸𐌹𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐌿𐌽𐌸𐌹𐌿𐌸𐌹𐍃, 𐌴𐌹 𐌱𐌹 𐌲𐌰𐍅𐌰𐌻𐌴𐌹𐌽𐌰𐌹 𐌼𐌿𐌽𐍃 𐌲𐌿𐌳𐌹𐍃 𐍅𐌹𐍃𐌰𐌹,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, '𐌽𐌹 𐌿𐍃 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼, 𐌰𐌺 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐌻𐌰𐌸𐍉𐌽𐌳𐌹𐌽 𐌵𐌹𐌸𐌰𐌽 𐌹𐍃𐍄 𐌹𐌶𐌰𐌹 𐌸𐌰𐍄𐌴𐌹 𐍃𐌰 𐌼𐌰𐌹𐌶𐌰 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐍉𐌸 𐌸𐌰𐌼𐌼𐌰 𐌼𐌹𐌽𐌽𐌹𐌶𐌹𐌽,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, '𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄: 𐌹𐌰𐌺𐍉𐌱 𐍆𐍂𐌹𐌾𐍉𐌳𐌰, 𐌹𐌸 𐌴𐍃𐌰𐍅 𐍆𐌹𐌾𐌰𐌹𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, '𐍈𐌰 𐌽𐌿 𐌵𐌹𐌸𐌰𐌼? 𐌹𐌱𐌰𐌹 𐌹𐌽𐍅𐌹𐌽𐌳𐌹𐌸𐌰 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰? 𐌽𐌹𐍃~𐍃𐌹𐌾𐌰𐌹!');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, '𐌳𐌿 𐌼𐍉𐍃𐌴 𐌰𐌿𐌺 𐌵𐌹𐌸𐌹𐌸: 𐌲𐌰𐌰𐍂𐌼𐌰 𐌸𐌰𐌽𐌴𐌹 𐌰𐍂𐌼𐌰, 𐌾𐌰𐌷 𐌲𐌰𐌱𐌻𐌴𐌹𐌸𐌾𐌰 (𐌸𐌰𐌽𐌴𐌹 𐌱𐌻𐌴𐌹𐌸𐌾𐌰).');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, '𐌸𐌰𐌽𐌽𐌿 𐌽𐌿 𐌽𐌹 𐍅𐌹𐌻𐌾𐌰𐌽𐌳𐌹𐌽𐍃 𐌽𐌹 𐍂𐌹𐌽𐌽𐌰𐌽𐌳𐌹𐌽𐍃, 𐌰𐌺 𐌰𐍂𐌼𐌰𐌽𐌳𐌹𐌽𐍃 𐌲𐌿𐌳𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, '𐌵𐌹𐌸𐌹𐌸 𐌰𐌿𐌺 𐌸𐌰𐍄𐌰 𐌲𐌰𐌼𐌴𐌻𐌹𐌳𐍉 𐌳𐌿 𐍆𐌰𐍂𐌰𐍉𐌽𐌹, (𐌿𐌽𐍄𐌴 𐌹𐌽 𐌸𐌹𐌶𐌴 𐌾𐌰𐌷 𐍂𐌰𐌹𐍃𐌹𐌳𐌰) 𐌸𐌿𐌺, 𐌴𐌹 𐌲𐌰𐌱𐌰𐌹𐍂𐌷𐍄𐌾𐌰𐌿 𐌱𐌹 𐌸𐌿𐍃 𐌼𐌰𐌷𐍄 𐌼𐌴𐌹𐌽𐌰 𐌾𐌰𐌷 𐌲𐌰𐍄𐌴𐌹𐌷𐌰𐌹𐌳𐌰𐌿 𐌽𐌰𐌼𐍉 𐌼𐌴𐌹𐌽 𐌰𐌽𐌳 𐌰𐌻𐌻𐌰 𐌰𐌹𐍂𐌸𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, '𐌸𐌰𐌽𐌽𐌿 𐌽𐌿 𐌾𐌰𐌹 𐌸𐌰𐌽𐌴𐌹 𐍅𐌹𐌻𐌹 𐌰𐍂𐌼𐌰𐌹𐌸, 𐌹𐌸 𐌸𐌰𐌽𐌴𐌹 𐍅𐌹𐌻𐌹 𐌲𐌰𐌷𐌰𐍂𐌳𐌴𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, '𐌵𐌹𐌸𐌹𐍃 𐌼𐌹𐍃 𐌽𐌿: 𐌰𐌸𐌸𐌰𐌽 𐍈𐌰 𐌽𐌰𐌿𐌷 𐍆𐌰𐌹𐌰𐌽𐌳𐌰? 𐌿𐌽𐍄𐌴 𐍅𐌹𐌻𐌾𐌹𐌽 𐌹𐍃 𐍈𐌰𐍃 𐌰𐌽𐌳𐍃𐍄𐌰𐌽𐌳𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, '𐌸𐌰𐌽𐌽𐌿 𐌽𐌿 𐌾𐌰𐌹, 𐌼𐌰𐌽𐌽𐌰, 𐌸𐌿 𐍈𐌰𐍃 𐌹𐍃, 𐌴𐌹 𐌰𐌽𐌳𐍅𐌰𐌿𐍂𐌳𐌾𐌰𐌹𐍃 𐌲𐌿𐌳𐌰? 𐌹𐌱𐌰𐌹 𐌵𐌹𐌸𐌹𐌸 𐌲𐌰𐌳𐌹𐌺𐌹𐍃 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 𐌳𐌹𐌲𐌰𐌽𐌳𐌹𐌽: 𐍈𐌰 𐌼𐌹𐌺 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌴𐍃 𐍃𐍅𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, '𐌸𐌰𐌿 𐌽𐌹𐌿 𐌷𐌰𐌱𐌰𐌹𐌸 𐌺𐌰𐍃𐌾𐌰 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐌸𐌰𐌷𐍉𐌽𐍃 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍃𐌰𐌼𐌹𐌽 𐌳𐌰𐌹𐌲𐌰 𐍄𐌰𐌿(𐌾𐌰𐌽) 𐍃𐌿𐌼 𐌳𐌿 𐌲𐌰𐌻𐌰𐌿𐌱𐌰𐌼𐌼𐌰 𐌺𐌰𐍃𐌰, 𐍃𐌿𐌼𐌿𐌸~𐌸𐌰𐌽 𐌳𐌿 𐌿𐌽𐌲𐌰𐌻𐌿𐌱𐌰𐌼𐌼𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, '𐌹𐌸 𐌾𐌰𐌱𐌰𐌹 𐍅𐌹𐌻𐌾𐌰𐌽𐌳𐍃 𐌲𐌿𐌸 𐌿𐍃𐍄𐌰𐌹𐌺𐌽𐌾𐌰𐌽 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹𐌽 𐌾𐌰𐌷 𐌿𐍃𐌺𐌰𐌽𐌽𐌾𐌰𐌽 𐌸𐌰𐍄𐌰 𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐍉 𐌿𐍃𐌱𐌴𐌹𐌳𐌰𐌽𐌳𐍃 𐌹𐌽 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌻𐌰𐌲𐌲𐌰𐌼𐍉𐌳𐌴𐌹𐌽 𐌱𐌹 𐌺𐌰𐍃𐌰𐌼 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹𐌽𐍃 𐌲𐌰𐌼𐌰𐌽𐍅𐌹𐌳𐌰𐌹𐌼 𐌳𐌿 𐍆𐍂𐌰𐌻𐌿𐍃𐍄𐌰𐌹,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, '𐌴𐌹 𐌲𐌰𐌺𐌰𐌽𐌽𐌹𐌳𐌴𐌳𐌹 𐌲𐌰𐌱𐌴𐌹𐌽 𐍅𐌿𐌻𐌸(𐌰)𐌿𐍃 𐍃𐌴𐌹𐌽𐌹𐍃 𐌱𐌹 𐌺𐌰𐍃𐌰𐌼 𐌰𐍂𐌼𐌰𐌹𐍉𐌽𐍃 𐌸𐍉𐌴𐌹 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌼𐌰𐌽𐍅𐌹𐌳𐌰 𐌳𐌿 𐍅𐌿𐌻𐌸𐌰𐌿;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, '𐌸𐌰𐌽𐌶𐌴𐌹 𐌾𐌰𐌷 𐌻𐌰𐌸𐍉𐌳𐌰 𐌿𐌽𐍃 𐌽𐌹 𐌸𐌰𐍄𐌰𐌹𐌽𐌴(𐌹) 𐌿𐍃 𐌹𐌿𐌳𐌰𐌹𐌿𐌼, 𐌰𐌺 𐌾𐌰𐌷 𐌿𐍃 𐌸𐌹𐌿𐌳𐍉𐌼,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, '𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐌹𐌽 𐍉𐍃𐌰𐌹𐌹𐌽 𐌵𐌹𐌸𐌹𐌸: 𐌷𐌰𐌹𐍄𐌰 𐌸𐍉 𐌽𐌹 𐌼𐌰𐌽𐌰𐌲𐌴𐌹𐌽 𐌼𐌴𐌹𐌽𐌰 𐌼𐌰𐌽𐌰𐌲𐌴𐌹𐌽 𐌼𐌴𐌹𐌽𐌰, 𐌾𐌰𐌷 𐌸𐍉 𐌿𐌽𐌻𐌹𐌿𐌱𐍉𐌽 𐌻𐌹𐌿𐌱𐍉𐌽;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, '𐌾𐌰𐌷 𐍅𐌰𐌹𐍂𐌸𐌹𐌸 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐍃𐍄𐌰𐌳𐌰 𐌸𐌰𐍂𐌴𐌹 𐌵𐌹𐌸𐌰𐌳𐌰 𐌹𐌼: 𐌽𐌹 𐌼𐌰𐌽𐌰𐌲𐌴𐌹 𐌼𐌴𐌹𐌽𐌰 𐌾𐌿𐍃, 𐌸𐌰𐌹 𐌷𐌰𐌹𐍄𐌰𐌽𐌳𐌰 𐍃𐌿𐌽𐌾𐌿𐍃 𐌲𐌿𐌳𐌹𐍃 𐌻𐌹𐌱𐌰𐌽𐌳𐌹𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, '𐌹𐌸 𐌴𐍃𐌰ï𐌰𐍃 𐌷𐍂𐍉𐍀𐌴𐌹𐌸 𐌱𐌹 𐌹𐍃𐍂𐌰𐌴𐌻: 𐌾𐌰𐌱𐌰𐌹 𐍅𐌴𐍃𐌹 𐍂𐌰𐌸𐌾𐍉 𐍃𐌿𐌽𐌹𐍅𐌴 𐌹𐍃𐍂𐌰𐌴𐌻𐌹𐍃 𐍃𐍅𐌰𐍃𐍅𐌴 𐌼𐌰𐌻𐌼𐌰 𐌼𐌰𐍂𐌴𐌹𐌽𐍃, 𐌻𐌰𐌹𐌱𐍉𐍃 𐌲𐌰𐌽𐌹𐍃𐌰𐌽𐌳.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, '𐍅𐌰𐌿𐍂𐌳 𐌰𐌿𐌺 𐌿𐍃𐍄𐌹𐌿𐌷𐌰𐌽𐌳𐍃 𐌾𐌰𐌷 𐌲𐌰𐌼𐌰𐌿𐍂𐌲𐌾𐌰𐌽𐌳𐍃 𐌹𐌽 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽, 𐌿𐌽𐍄𐌴 𐍅𐌰𐌿𐍂𐌳 𐌲𐌰𐌼𐌰𐌿𐍂𐌲𐌹𐌸 𐍄𐌰𐌿𐌾𐌹𐌸 𐍆𐍂𐌰𐌿𐌾𐌰 𐌰𐌽𐌰 𐌰𐌹𐍂𐌸𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, '𐌾𐌰𐌷 𐍃𐍅𐌰𐍃𐍅𐌴 𐍆𐌰𐌿𐍂𐌰𐌵𐌰𐌸 𐌴𐍃𐌰ï𐌰𐍃: 𐌽𐌹𐌷 𐍆𐍂𐌰𐌿𐌾𐌰 𐍃𐌰𐌱𐌰𐍉𐌸 𐌱𐌹𐌻𐌹𐌸𐌹 𐌿𐌽𐍃𐌹𐍃 𐍆𐍂𐌰𐌹𐍅𐌰, 𐍃𐍅𐌴 𐍃𐌰𐌿𐌳𐌰𐌿𐌼𐌰 𐌸𐌰𐌿 𐍅𐌰𐌿𐍂𐌸𐌴𐌹𐌼𐌰 𐌾𐌰𐌷 𐍃𐍅𐌴 𐌲𐌰𐌿𐌼𐌰𐌿𐍂𐍂𐌰 𐌸𐌰𐌿 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹 𐍅𐌰𐌿𐍂𐌸𐌴𐌹𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, '𐍈𐌰 𐌽𐌿 𐌵𐌹𐌸𐌰𐌼? 𐌸𐌰𐍄𐌴𐌹 𐌸𐌹𐌿𐌳𐍉𐍃 𐌸𐍉𐍃 𐌽𐌹 𐌻𐌰𐌹𐍃𐍄𐌾𐌰𐌽𐌳𐌴𐌹𐌽𐍃 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌲𐌰𐍆𐌰𐌹𐍆𐌰𐌷𐌿𐌽 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽, 𐌰𐌸𐌸𐌰𐌽 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌸𐍉 𐌿𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹(𐌽𐌰𐌹);');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, '𐌹𐌸 𐌹𐍃𐍂𐌰𐌴𐌻 𐌻𐌰𐌹𐍃𐍄𐌾𐌰𐌽𐌳𐍃 𐍅𐌹𐍄𐍉𐌸 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽𐍃 𐌱𐌹 𐍅𐌹𐍄𐍉𐌸 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽𐍃 𐌽𐌹 𐌲𐌰𐍃𐌽𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, '𐌳𐌿𐍈𐌴? 𐌿𐌽𐍄𐌴 𐌽𐌹 𐌿𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹, 𐌰𐌺 𐌿𐍃 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌰𐌼 𐍅𐌹𐍄𐍉𐌳𐌹𐍃; 𐌱𐌹𐍃𐍄𐌿𐌲𐌲𐌵𐌿𐌽 𐌳𐌿 𐍃𐍄𐌰𐌹𐌽𐌰 𐌱𐌹𐍃𐍄𐌿𐌲𐌲𐌵𐌹𐍃,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, '𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄: 𐍃𐌰𐌹, 𐌲𐌰𐌻𐌰𐌲𐌾𐌰 𐌹𐌽 𐍃𐌹𐍉𐌽 𐍃𐍄𐌰𐌹𐌽 𐌱𐌹𐍃𐍄𐌿𐌲𐌲𐌵𐌹𐍃 𐌾𐌰𐌷 𐌷𐌰𐌻𐌻𐌿 𐌲𐌰𐌼𐌰𐍂𐌶𐌴𐌹𐌽𐌰𐌹𐍃, 𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐍃 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌽𐌹 𐌲𐌰𐌰𐌹𐍅𐌹𐍃𐌺𐍉𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, '𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐍃𐌰 𐍂𐌰𐌹𐌷𐍄𐌹𐍃 𐍅𐌹𐌻𐌾𐌰 𐌼𐌴𐌹𐌽𐌹𐍃 𐌷𐌰𐌹𐍂𐍄𐌹𐌽𐍃 𐌾𐌰𐌷 𐌱𐌹𐌳𐌰 𐌳𐌿 𐌲𐌿𐌳𐌰 𐌱𐌹 𐌹𐌽𐍃 𐌳𐌿 𐌽𐌰𐍃𐌴𐌹𐌽𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, '𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰 𐌰𐌿𐌺 𐌹𐌼 𐌸𐌰𐍄𐌴𐌹 𐌰𐌻𐌾𐌰𐌽 𐌲𐌿𐌳𐌹𐍃 𐌷𐌰𐌱𐌰𐌽𐌳, 𐌰𐌺𐌴𐌹 𐌽𐌹 𐌱𐌹 𐌺𐌿𐌽𐌸𐌾𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, '𐌿𐌽𐌺𐌿𐌽𐌽𐌰𐌽𐌳𐌰𐌽𐍃 𐌰𐌿𐌺 𐌲𐌿𐌳𐌹𐍃 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌾𐌰𐌷 𐍃𐌴𐌹𐌽𐌰 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐍃𐍉𐌺𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐍄𐌹𐌿𐍂𐌾𐌰𐌽, 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌲𐌿𐌳𐌹𐍃 𐌽𐌹 𐌿𐍆𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, '𐌿𐍃𐍄𐌰𐌿𐌷𐍄𐍃 𐌰𐌿𐌺 𐍅𐌹𐍄𐍉𐌳𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌳𐌿 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌰𐌻𐌻𐌰𐌹𐌼 𐌸𐌰𐌹𐌼 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, '𐌼𐍉𐍃𐌴𐍃 𐌰𐌿𐌺 𐌼𐌴𐌻𐌴𐌹𐌸 𐌸𐍉 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹𐌽 𐌿𐍃 𐍅𐌹𐍄𐍉𐌳𐌰, 𐌸𐌰𐍄𐌴𐌹 𐍃𐌰 𐍄𐌰𐌿𐌾𐌰𐌽𐌳𐍃 𐌸𐍉 𐌼𐌰𐌽𐌽𐌰 𐌻𐌹𐌱𐌰𐌹𐌸 𐌹𐌽 𐌹𐌶𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, '𐌹𐌸 𐍃𐍉 𐌿𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌴𐌹 𐍃𐍅𐌰 𐌵𐌹𐌸𐌹𐌸: 𐌽𐌹 𐌵𐌹𐌸𐌰𐌹𐍃 𐌹𐌽 𐌷𐌰𐌹𐍂𐍄𐌹𐌽 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰: 𐍈𐌰𐍃 𐌿𐍃𐍃𐍄𐌴𐌹𐌲𐌹𐌸 𐌹𐌽 𐌷𐌹𐌼𐌹𐌽? 𐌸𐌰𐍄~𐌹𐍃𐍄 𐍇𐍂𐌹𐍃𐍄𐌿 𐌳𐌰𐌻𐌰𐌸 𐌰𐍄𐍄𐌹𐌿𐌷𐌰𐌽;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, '𐌰𐌹𐌸𐌸𐌰𐌿: 𐍈𐌰𐍃 𐌲𐌰𐍃𐍄𐌴𐌹𐌲𐌹𐌸 𐌹𐌽 𐌰𐍆𐌲𐍂𐌿𐌽𐌳𐌹𐌸𐌰? 𐌸𐌰𐍄~𐌹𐍃𐍄 𐍇𐍂𐌹𐍃𐍄𐌿 𐌿𐍃 𐌳𐌰𐌿𐌸𐌰𐌹𐌼 𐌹𐌿𐍀 𐌿𐍃𐍄𐌹𐌿𐌷𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, '𐌰𐌺𐌴𐌹 𐍈𐌰 𐌵𐌹𐌸𐌹𐌸? 𐌽𐌴𐍈𐌰 𐌸𐌿𐍃 𐌸𐌰𐍄𐌰 𐍅𐌰𐌿𐍂𐌳 𐌹𐍃𐍄 𐌹𐌽 𐌼𐌿𐌽𐌸𐌰 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌾𐌰𐌷 𐌹𐌽 𐌷𐌰𐌹𐍂𐍄𐌹𐌽 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰, 𐌸𐌰𐍄~𐌹𐍃𐍄 𐍅𐌰𐌿𐍂𐌳 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌼𐌴𐍂𐌾𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, '𐌸𐌴𐌹 𐌾𐌰𐌱𐌰𐌹 𐌰𐌽𐌳𐌷𐌰𐌹𐍄𐌹𐍃 𐌹𐌽 𐌼𐌿𐌽𐌸𐌰 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌹𐌴𐍃𐌿 𐌾𐌰𐌷 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐍃 𐌹𐌽 𐌷𐌰𐌹𐍂𐍄𐌹𐌽 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌸𐌰𐍄𐌴𐌹 𐌲𐌿𐌸 𐌹𐌽𐌰 𐌿𐍂𐍂𐌰𐌹𐍃𐌹𐌳𐌰 𐌿𐍃 𐌳𐌰𐌿𐌸𐌰𐌹𐌼, 𐌲𐌰𐌽𐌹𐍃𐌹(𐍃).');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, '𐌷𐌰𐌹𐍂𐍄𐍉 𐌰𐌿𐌺 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸 𐌳𐌿 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌹𐌸𐌰𐌹, 𐌹𐌸 𐌼𐌿𐌽𐌸𐌰 𐌰𐌽𐌳𐌷𐌰𐌹𐍄𐌰𐌳𐌰 𐌳𐌿 𐌲𐌰𐌽𐌹𐍃𐍄𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, '𐌵𐌹𐌸𐌹𐌸 𐌰𐌿𐌺 𐌸𐌰𐍄𐌰 𐌲𐌰𐌼𐌴𐌻𐌹𐌸: 𐍈𐌰𐌶𐌿𐌷 𐍃𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐍃 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌽𐌹 𐌲𐌰𐌰𐌹𐍅𐌹𐍃𐌺𐍉𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, '𐌽𐌹 𐌰𐌿𐌺 𐌹𐍃𐍄 𐌲𐌰𐍃𐌺𐌰𐌹𐌳𐌴𐌹𐌽𐍃 𐌹𐌿𐌳𐌰𐌹𐌰𐌿𐍃 𐌾𐌰𐌷 𐌺𐍂𐌴𐌺𐌹𐍃; 𐍃𐌰 𐍃𐌰𐌼𐌰 𐌰𐌿𐌺 𐍆𐍂𐌰𐌿𐌾𐌰 𐌰𐌻𐌻𐌰𐌹𐌶𐌴, 𐌲𐌰𐌱𐌹𐌲𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌽𐍃 𐌸𐌰𐌽𐍃 𐌱𐌹𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, '𐍈𐌰𐌶𐌿𐌷 𐌰𐌿𐌺 𐍃𐌰𐌴𐌹 𐌰𐌽𐌰𐌷𐌰𐌹𐍄𐌹𐌸 𐌱𐌹𐌳𐌰𐌹 𐌽𐌰𐌼𐍉 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃, 𐌲𐌰𐌽𐌹𐍃𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, '𐍈𐌰𐌹𐍅𐌰 𐌽𐌿 𐌱𐌹𐌳𐌾𐌰𐌽𐌳 𐌳𐌿 𐌸𐌰𐌼𐌼𐌴𐌹 𐌽𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌴𐌳𐌿𐌽? 𐌰𐌹𐌸𐌸𐌰𐌿 𐍈𐌰𐌹𐍅𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳 𐌸𐌰𐌼𐌼𐌴𐌹 𐌽𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌽? 𐌹𐌸 𐍈𐌰𐌹𐍅𐌰 𐌷𐌰𐌿𐍃𐌾𐌰𐌽𐌳 𐌹𐌽𐌿 𐌼𐌴𐍂𐌾𐌰𐌽𐌳𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, '𐌹𐌸 𐍈𐌰𐌹𐍅𐌰 𐌼𐌴𐍂𐌾𐌰𐌽𐌳, 𐌽𐌹𐌱𐌰 𐌹𐌽𐍃𐌰𐌽𐌳𐌾𐌰𐌽𐌳𐌰? 𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄: 𐍈𐌰𐌹𐍅𐌰 𐍃𐌺𐌰𐌿𐌽𐌾𐌰𐌹 𐍆𐍉𐍄𐌾𐌿𐍃 𐌸𐌹𐌶𐌴 𐍃𐍀𐌹𐌻𐌻𐍉𐌽𐌳𐌰𐌽𐌴 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹, 𐌸𐌹𐌶𐌴 𐍃𐍀𐌹𐌻𐌻𐍉𐌽𐌳𐌰𐌽𐌴 𐌸𐌹𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, '𐌰𐌺𐌴𐌹 𐌽𐌹 𐌰𐌻𐌻𐌰𐌹 𐌿𐍆𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌽 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉𐌽: 𐌴𐍃𐌰Ã ̄𐌰𐍃 𐌰𐌿𐌺 𐌵𐌹𐌸𐌹𐌸: 𐍆𐍂𐌰𐌿𐌾𐌰, 𐍈𐌰𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌹𐌳𐌰 𐌷𐌰𐌿𐍃𐌴𐌹𐌽𐌰𐌹 𐌿𐌽𐍃𐌰𐍂𐌰𐌹?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, '𐌸𐌰𐌽𐌽𐌿 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐍃 𐌿𐍃 𐌲𐌰𐌷𐌰𐌿𐍃𐌴𐌹𐌽𐌰𐌹, 𐌹𐌸 𐌲𐌰𐌷𐌰𐌿𐍃𐌴𐌹𐌽𐍃 𐌸𐌰𐌹𐍂𐌷 𐍅𐌰𐌿𐍂𐌳 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, '𐌰𐌺𐌴𐌹 𐌵𐌹𐌸𐌰: 𐌹𐌱𐌰𐌹 𐌽𐌹 𐌷𐌰𐌿𐍃𐌹𐌳𐌴𐌳𐌿𐌽? 𐍂𐌰𐌹𐌷𐍄𐌹𐍃: 𐌰𐌽𐌳 𐌰𐌻𐌻𐌰 𐌰𐌹𐍂𐌸𐌰 𐌲𐌰𐌻𐌰𐌹𐌸 𐌳𐍂𐌿𐌽𐌾𐌿𐍃 𐌹𐌶𐌴 𐌾𐌰𐌷 𐌰𐌽𐌳 𐌰𐌽𐌳𐌹𐌽𐍃 𐌼𐌹𐌳𐌾𐌿𐌽𐌲𐌰𐍂𐌳𐌹𐍃 𐍅𐌰𐌿𐍂𐌳𐌰 𐌹𐌶𐌴.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, '𐌰𐌺𐌴𐌹 𐌵𐌹𐌸𐌰: 𐌹𐌱𐌰𐌹 𐌹𐍃𐍂𐌰𐌴𐌻 𐌽𐌹 𐍆𐌰𐌽𐌸? 𐍆𐍂𐌿𐌼𐌹𐍃𐍄 𐌼𐍉𐍃𐌴𐍃 𐌵𐌹𐌸𐌹𐌸: 𐌹𐌺 𐌹𐌽 𐌰𐌻𐌾𐌰𐌽𐌰 𐌹𐌶𐍅𐌹𐍃 𐌱𐍂𐌹𐌲𐌲𐌰 𐌹𐌽 𐌿𐌽𐌸𐌹𐌿𐌳𐍉𐌼, 𐌹𐌽 𐌸𐌹𐌿𐌳𐌰𐌹 𐌿𐌽𐍆𐍂𐌰𐌸𐌾𐌰𐌽𐌳𐌴𐌹𐌽 𐌹𐌽 𐌸𐍅𐌰𐌹𐍂𐌷𐌴𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌱𐍂𐌹𐌲𐌲𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, '𐌹𐌸 𐌴𐍃𐌰ï𐌰𐍃 𐌰𐌽𐌰𐌽𐌰𐌽𐌸𐌴𐌹𐌸 𐌾𐌰𐌷 𐌵𐌹𐌸𐌹𐌸: 𐌱𐌹𐌲𐌹𐍄𐌰𐌽𐍃 𐍅𐌰𐍂𐌸 𐌸𐌰𐌹𐌼 𐌼𐌹𐌺 𐌽𐌹 𐌲𐌰𐍃𐍉𐌺𐌾𐌰𐌽𐌳𐌰𐌼, 𐍃𐍅𐌹𐌺𐌿𐌽𐌸𐍃 𐍅𐌰𐍂𐌸 𐌸𐌰𐌹𐌼 𐌼𐌹𐌺 𐌽𐌹 𐌲𐌰𐍆𐍂𐌰𐌹𐌷𐌽𐌰𐌽𐌳𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, '𐌹𐌸 𐌳𐌿 𐌹𐍃𐍂𐌰𐌴𐌻𐌰 𐌵𐌹𐌸𐌹𐌸: 𐌰𐌻𐌻𐌰𐌽𐌰 𐌳𐌰𐌲 𐌿𐍃𐌱𐍂𐌰𐌹𐌳𐌹𐌳𐌰 (𐌸𐍉𐍃) 𐌷𐌰𐌽𐌳𐌿𐌽𐍃 𐌼𐌴𐌹𐌽𐍉𐍃 𐌳𐌿 𐌼𐌰𐌽𐌰𐌲𐌴𐌹𐌽 𐌿𐌽𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌴𐌹𐌽 𐌾𐌰𐌷 𐌰𐌽𐌳𐍃𐍄𐌰𐌽𐌳𐌰𐌽𐌳𐌴𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, '𐌵𐌹𐌸𐌰 𐌽𐌿: 𐌹𐌱𐌰𐌹 𐌰𐍆𐍃𐌺𐌰𐌿𐍆 𐌲𐌿𐌸 𐌰(𐍂)𐌱𐌾𐌰 𐍃𐌴𐌹𐌽𐌰𐌼𐌼𐌰? 𐌽𐌹𐍃~𐍃𐌹𐌾𐌰𐌹! 𐌾𐌰𐌷 𐌰𐌿𐌺 𐌹𐌺 𐌹𐍃𐍂𐌰𐌴𐌻𐌴𐌹𐍄𐌴𐍃 𐌹𐌼....');
