INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, '.... 𐌸𐌹𐌶𐌴 𐌹𐌳𐍅𐌴𐌹𐍄𐌾𐌰𐌽𐌳𐌰𐌽𐌴 𐌸𐌿𐌺 𐌲𐌰𐌳𐍂𐌿𐍃𐌿𐌽 𐌰𐌽𐌰 𐌼𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, '𐍃𐍅𐌰 𐍆𐌹𐌻𐌿 𐌰𐌿𐌺 𐍃𐍅𐌴 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐍅𐌰𐍂𐌸, 𐌳𐌿 𐌿𐌽𐍃𐌰𐍂𐌰𐌹 𐌻𐌰𐌹𐍃𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐍅𐌰𐍂𐌸, 𐌴𐌹 𐌸𐌰𐌹𐍂𐌷 𐌸𐌿𐌻𐌰𐌹𐌽 𐌾𐌰𐌷 𐌲𐌰𐌸𐍂𐌰𐍆𐍃𐍄𐌴𐌹𐌽 𐌱𐍉𐌺𐍉 𐍅𐌴𐌽 𐌷𐌰𐌱𐌰𐌹𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, '𐌹𐌸 𐌲𐌿𐌸 𐌸𐌿𐌻𐌰𐌹𐌽𐌰𐌹𐍃 𐌾𐌰𐌷 𐌸𐍂𐌰𐍆𐍃𐍄𐌴𐌹𐌽𐌰𐌹𐍃 𐌲𐌹𐌱𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐍄𐌰 𐍃𐌰𐌼𐍉 𐍆𐍂𐌰𐌸𐌾𐌰𐌽 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌱𐌹 𐍇𐍂𐌹𐍃𐍄𐌿 𐌹𐌴𐍃𐌿,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, '𐌴𐌹 𐌲𐌰𐍅𐌹𐌻𐌾𐌰𐌹 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌼𐌿𐌽𐌸𐌰 𐌷𐌰𐌿𐌷𐌾𐌰𐌹𐌸 𐌲𐌿𐌸 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, '𐌹𐌽 𐌸𐌹𐌶𐌴𐌹 𐌰𐌽𐌳𐌽𐌹𐌼𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌰𐌽𐌳𐌽𐌰𐌼 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐍅𐌿𐌻𐌸𐌰𐌿 𐌲𐌿𐌳𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, '𐌵𐌹𐌸𐌰 𐌰𐌿𐌺 𐍇𐍂𐌹𐍃𐍄𐌿 𐌹𐌴𐍃𐌿 𐌰𐌽𐌳𐌱𐌰𐌷𐍄 𐍅𐌰𐌿𐍂𐌸𐌰𐌽𐌰𐌽𐌰 𐍆𐍂𐌰𐌼 𐍃𐌿𐌽𐌾𐌰𐌹 𐌲𐌿𐌳𐌹𐍃 𐌳𐌿 𐌲𐌰𐍄𐌿𐌻𐌲𐌾𐌰𐌽 𐌲𐌰𐌷𐌰𐌹𐍄𐌰 𐌰𐍄𐍄𐌰𐌽𐌴,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, '𐌹𐌸 𐌸𐌹𐌿𐌳𐍉𐍃 𐌹𐌽 𐌰𐍂𐌼𐌰𐌷𐌰𐌹𐍂𐍄𐌴𐌹𐌽𐍃 𐌷𐌰𐌿𐌷𐌾𐌰𐌽 𐌲𐌿𐌸, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄: 𐌳𐌿𐌸𐌸𐌴 𐌰𐌽𐌳𐌷𐌰𐌹𐍄𐌰 𐌸𐌿𐍃 𐌹𐌽 𐌸𐌹𐌿𐌳𐍉𐌼, 𐍆𐍂𐌰𐌿𐌾𐌰, 𐌾𐌰𐌷 𐌽𐌰𐌼𐌹𐌽 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌻𐌹𐌿𐌸𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, '𐌾𐌰𐌷 𐌰𐍆𐍄𐍂𐌰 𐌵𐌹𐌸𐌹𐌸: 𐍃𐌹𐍆𐌰𐌹𐌸 𐌸𐌹𐌿𐌳𐍉𐍃 𐌼𐌹𐌸 𐌼𐌰𐌽𐌰𐌲𐌴𐌹𐌽 𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, '𐌾𐌰𐌷 𐌰𐍆𐍄𐍂𐌰 𐌵𐌹𐌸𐌹𐌸: 𐌷𐌰𐌶𐌾𐌹𐌸 𐌰𐌻𐌻𐍉𐍃 𐌸𐌹𐌿𐌳𐍉𐍃 𐍆𐍂𐌰𐌿𐌾𐌰𐌽 𐌾𐌰𐌷 𐌷𐌰𐌶𐌾𐌰𐌹𐌽𐌰 𐌹𐌽𐌰 𐌰𐌻𐌻𐍉𐍃 𐌼𐌰𐌽𐌰𐌲𐌴𐌹𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, '𐌾𐌰𐌷 𐌰𐍆𐍄𐍂𐌰 𐌴𐍃𐌰𐌴𐌹𐌰𐍃 𐌵𐌹𐌸𐌹𐌸: 𐍅𐌰𐌹𐍂𐌸𐌹𐌸 𐍅𐌰𐌿𐍂𐍄𐍃 𐌹𐌰𐌹𐍃𐍃𐌰𐌹𐌶𐌹𐍃, 𐌾𐌰𐌷 𐍃𐌰 𐌿𐍃𐍃𐍄𐌰𐌽𐌳𐌰𐌽𐌳𐍃 𐍂𐌴𐌹𐌺𐌹𐌽𐍉𐌸 𐌸𐌹𐌿𐌳𐍉𐌼; 𐌳𐌿 𐌹𐌼𐌼𐌰 𐌸𐌹𐌿𐌳𐍉𐍃 𐍅𐌴𐌽𐌾𐌰𐌽𐌳.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, '𐌹𐌸 𐌲𐌿𐌸 𐌻𐌿𐌱𐌰𐌹𐌽𐌰𐌹𐍃 𐍆𐌿𐌻𐌻𐌾𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌰𐌻𐌻𐌰𐌹𐌶𐍉𐍃 𐍆𐌰𐌷𐌴𐌳𐌰𐌹𐍃....');
