INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, '.... 𐌾𐌰𐌷 𐌻𐌿𐌺𐌹𐌿𐍃 𐌾𐌰𐌷 𐌹𐌰𐍃𐍃𐍉𐌽 𐌾𐌰𐌷 𐍃𐍉𐍃𐌴𐌹𐍀𐌰𐍄𐍂𐌿𐍃, 𐌸𐌰𐌹 𐌽𐌹𐌸𐌾𐍉𐍃 𐌼𐌴𐌹𐌽𐌰𐌹;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, '𐌲𐍉𐌻𐌾𐌰 𐌹𐌶𐍅𐌹𐍃 𐌹𐌺 𐍄𐌰𐌹𐍂𐍄𐌹𐌿𐍃 𐍃𐌰 𐌼𐌴𐌻𐌾𐌰𐌽𐌳𐍃 𐌸𐍉 𐌰𐌹𐍀𐌹𐍃𐍄𐌰𐌿𐌻𐌴𐌹𐌽 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, '𐌲𐍉𐌻𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌲𐌰ï𐌿𐍃, 𐍅𐌰𐌹𐍂𐌳𐌿𐍃 𐌼𐌴𐌹𐌽𐍃 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌹𐌶𐍉𐍃 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌽𐍃. 𐌲𐍉𐌻𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌰𐌹𐍂𐌰𐍃𐍄𐌿𐍃, 𐍆𐌰𐌿𐍂𐌰𐌲𐌰𐌲𐌲𐌾𐌰 𐌱𐌰𐌿𐍂𐌲𐍃, 𐌾𐌰𐌷 𐌵𐌰𐍂𐍄𐌿𐍃 𐍃𐌰 𐌱𐍂𐍉𐌸𐌰𐍂.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, '𐌰𐌽𐍃𐍄𐍃 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌼𐌹𐌸 𐌰𐌷𐌼𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰𐌼𐌼𐌰. 𐌰𐌼𐌴𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, '𐌳𐌿 𐍂𐌿𐌼𐍉𐌽𐌹𐌼 𐌿𐍃𐍄𐌰𐌿𐌷. 𐌳𐌿 𐍂𐌿𐌼𐍉𐌽𐌹𐌼 𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄 𐌿𐍃 𐌺𐌰𐌿𐍂𐌹𐌽𐌸𐍉𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, '');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, '');
