INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, '');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, '');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, '');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, '');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, '');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, '');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, '.... 𐌹𐌺 𐌹𐌼 𐍀𐌰𐍅𐌻𐌿𐍃, 𐌹𐌸 𐌹𐌺 𐌰𐍀𐌰𐌿𐌻𐌻𐍉𐌽𐍃, 𐌹𐌸 𐌹𐌺 𐌺𐌴𐍆𐌹𐌽𐍃, 𐌹𐌸 𐌹𐌺 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, '𐌳𐌹𐍃𐌳𐌰𐌹𐌻𐌹𐌸𐍃 𐌹𐍃𐍄 𐍇𐍂𐌹𐍃𐍄𐌿𐍃? 𐌹𐌱𐌰𐌹 𐍀𐌰𐍅𐌻𐌿𐍃 𐌿𐍃𐌷𐍂𐌰𐌼𐌹𐌸𐍃 𐍅𐌰𐍂𐌸 𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐍀𐌰𐍅𐌻𐌿𐍃 𐌳𐌰𐌿𐍀𐌹𐌳𐌰𐌹 𐍅𐌴𐍃𐌴𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, '𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉 𐌲𐌿𐌳𐌰 𐌴𐌹 𐌰𐌹𐌽𐌽𐍉𐌷𐌿𐌽 𐌹𐌶𐍅𐌰𐍂𐌰 𐌽𐌹 𐌳𐌰𐌿𐍀𐌹𐌳𐌰 𐌽𐌹𐌱𐌰 𐌺𐍂𐌹𐍃𐍀𐌿 𐌾𐌰𐌷 𐌲𐌰ï𐌿,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, '𐌴𐌹 𐍈𐌰𐍃 𐌽𐌹 𐌵𐌹𐌸𐌰𐌹 𐌸𐌰𐍄𐌴𐌹 𐌹𐌽 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌽𐌰𐌼𐌹𐌽 𐌳𐌰𐌿𐍀𐌹𐌳𐌴𐌳𐌾𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, '𐌹𐌺 𐌳𐌰𐌿𐍀𐌹𐌳𐌰 𐌰𐌿𐌺 𐌾𐌰𐌸~𐌸𐌰𐌽𐍃 𐍃𐍄𐌰𐌹𐍆𐌰𐌽𐌰𐌿𐍃 𐌲𐌰𐌳𐌰𐌿𐌺𐌰𐌽𐍃; 𐌸𐌰𐍄𐌰 𐌰𐌽𐌸𐌰𐍂 𐌽𐌹 𐍅𐌰𐌹𐍄 𐌴𐌹 𐌰𐌹𐌽𐌽𐍉𐌷𐌿𐌽 𐌳𐌰𐌿𐍀𐌹𐌳𐌴𐌳𐌾𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, '𐌽𐌹𐌸~𐌸𐌰𐌽 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌼𐌹𐌺 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌳𐌰𐌿𐍀𐌾𐌰𐌽, 𐌰𐌺 𐍅𐌰𐌹𐌻𐌰𐌼𐌴𐍂𐌾𐌰𐌽; 𐌽𐌹 𐌹𐌽 𐍃𐌽𐌿𐍄𐍂𐌴𐌹𐌽 𐍅𐌰𐌿𐍂𐌳𐌹𐍃, 𐌴𐌹 𐌽𐌹 𐌻𐌰𐌿𐍃𐌾𐌰𐌹𐌳𐌰𐌿 𐌲𐌰𐌻𐌲𐌰 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, '𐌿𐌽𐍄𐌴 𐌸𐌰𐍄𐌰 𐍅𐌰𐌿𐍂𐌳 𐌲𐌰𐌻𐌲𐌹𐌽𐍃 𐌸𐌰𐌹𐌼 𐍆𐍂𐌰𐌻𐌿𐍃𐌽𐌰𐌽𐌳𐌰𐌼 𐌳𐍅𐌰𐌻𐌹𐌸𐌰 𐌹𐍃𐍄, 𐌹𐌸 𐌸𐌰𐌹𐌼 𐌲𐌰𐌽𐌹𐍃𐌰𐌽𐌳𐌰𐌼 𐌼𐌰𐌷𐍄𐍃 𐌲𐌿𐌳𐌹𐍃 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, '𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄 𐌰𐌿𐌺: 𐍆𐍂𐌰𐌵𐌹𐍃𐍄𐌾𐌰 𐍃𐌽𐌿𐍄𐍂𐌴𐌹𐌽 𐌸𐌹𐌶𐌴 𐍃𐌽𐌿𐍄𐍂𐌰𐌽𐌴 𐌾𐌰𐌷 𐍆𐍂𐍉𐌳𐌴𐌹𐌽 𐌸𐌹𐌶𐌴 𐍆𐍂𐍉𐌳𐌰𐌽𐌴 𐌿𐍃𐌺𐌹𐌿𐍃𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, '𐍈𐌰𐍂 𐌷𐌰𐌽𐌳𐌿𐌲𐍃? 𐍈𐌰𐍂 𐌱𐍉𐌺𐌰𐍂𐌴𐌹𐍃? 𐍈𐌰𐍂 𐍃𐍉𐌺𐌰𐍂𐌴𐌹𐍃 𐌸𐌹𐍃 𐌰𐌹𐍅𐌹𐍃? 𐌽𐌹𐌷 𐌳𐍅𐌰𐌻𐌰 𐌲𐌰𐍄𐌰𐍅𐌹𐌳𐌰 𐌲𐌿𐌸 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, '𐌿𐌽𐍄𐌴 𐌰𐌿𐌺 𐌹𐌽 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌲𐌿𐌳𐌹𐍃 𐌽𐌹 𐌿𐍆𐌺𐌿𐌽𐌽𐌰𐌹𐌳𐌰 𐍃𐌰 𐍆𐌰𐌹𐍂𐍈𐌿𐍃 𐌸𐌰𐌹𐍂𐌷 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐌲𐌿𐌸, 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌳𐌰 𐌲𐌿𐌳𐌰 𐌸𐌰𐌹𐍂𐌷 𐌸𐍉 𐌳𐍅𐌰𐌻𐌹𐌸𐌰 𐌸𐌹𐌶𐍉𐍃 𐍅𐌰𐌹𐌻𐌰𐌼𐌴𐍂𐌴𐌹𐌽𐌰𐌹𐍃 𐌲𐌰𐌽𐌰𐍃𐌾𐌰𐌽 𐌸𐌰𐌽𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, '𐌿𐌽𐍄𐌴 𐌹𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐍄𐌰𐌹𐌺𐌽𐌴 𐌱𐌹𐌳𐌾𐌰𐌽𐌳, 𐌹𐌸 𐌺𐍂𐌴𐌺𐍉𐍃 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽 𐍃𐍉𐌺𐌾𐌰𐌽𐌳;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, '𐌹𐌸 𐍅𐌴𐌹𐍃 𐌼𐌴𐍂𐌾𐌰𐌼 𐌹𐌴𐍃𐌿 𐌿𐍃𐌷𐍂𐌰𐌼𐌹𐌳𐌰𐌽𐌰, 𐌹𐌿𐌳𐌰𐌹𐌿𐌼 𐌲𐌰𐌼𐌰𐍂𐌶𐌴𐌹𐌽, 𐌹𐌸 𐌸𐌹𐌿𐌳𐍉𐌼 𐌳𐍅𐌰𐌻𐌹𐌸𐌰;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, '𐌹𐌸 𐌸𐌰𐌹𐌼 𐌲𐌰𐌻𐌰𐌸𐍉𐌳𐌰𐌼 𐌹𐌿𐌳𐌰𐌹𐌴 𐌾𐌰𐌷 𐌸𐌹𐌿𐌳𐍉 𐍇𐍂𐌹𐍃𐍄𐌿, 𐌲𐌿𐌳𐌹𐍃 𐌼𐌰𐌷𐍄 𐌾𐌰𐌷 𐌲𐌿𐌳𐌹𐍃 𐌷𐌰𐌽𐌳𐌿𐌲𐌴𐌹𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, '𐌿𐌽𐍄𐌴 𐍃𐍉 𐌳𐍅𐌰𐌻𐌹𐌸𐌰 𐌲𐌿𐌳𐌹𐍃 𐌷𐌰𐌽𐌳𐌿𐌲𐍉(𐌶𐌴)𐌹 𐌼𐌰𐌽𐌽𐌰𐌼....');
