INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, '.... 𐌴𐌹 𐍈𐌰𐍃 𐍄𐍂𐌹𐌲𐌲𐍅𐍃 𐌱𐌹𐌲𐌹𐍄𐌰𐌹𐌳𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, '𐌰𐌸𐌸𐌰𐌽 𐌼𐌹𐍃 𐌹𐌽 𐌼𐌹𐌽𐌽𐌹𐍃𐍄𐌹𐌽 𐌹𐍃𐍄, 𐌴𐌹 𐍆𐍂𐌰𐌼 𐌹𐌶𐍅𐌹𐍃 𐌿𐍃𐍃𐍉𐌺𐌾𐌰𐌹𐌳𐌰𐌿 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐍂𐌰𐌼 𐌼𐌰𐌽𐌽𐌹𐍃𐌺𐌰𐌼𐌼𐌰 𐌳𐌰𐌲𐌰; 𐌰𐌺𐌴𐌹 𐌽𐌹𐌷 𐌼𐌹𐌺 𐍃𐌹𐌻𐌱𐌰𐌽 𐌿𐍃𐍃𐍉𐌺𐌾𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, '𐌽𐌹𐌷 𐍅𐌰𐌹𐌷𐍄 𐌰𐌿𐌺 𐌼𐌹𐍃 𐍃𐌹𐌻𐌱𐌹𐌽 𐌼𐌹𐌸𐍅𐌰𐌹𐍄; 𐌰𐌺𐌴𐌹 𐌽𐌹 𐌹𐌽 𐌸𐌰𐌼𐌼𐌰 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌹𐌸𐍃 𐌹𐌼, 𐌹𐌸 𐍃𐌰𐌴𐌹 𐌿𐍃𐍃𐍉𐌺𐌴𐌹𐌸 𐌼𐌹𐌺, 𐍆𐍂𐌰𐌿𐌾𐌰 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, '𐌸𐌰𐌽𐌽𐌿 𐌽𐌿 𐌴𐌹 𐍆𐌰𐌿𐍂 𐌼𐌴𐌻 𐌽𐌹 𐍃𐍄𐍉𐌾𐌰𐌹𐌸, 𐌿𐌽𐍄𐌴 𐌵𐌹𐌼𐌰𐌹 𐍆𐍂𐌰𐌿𐌾𐌰, 𐍃𐌰𐌴𐌹 𐌾𐌰𐌷 𐌲𐌰𐌻𐌹𐌿𐌷𐍄𐌴𐌹𐌸 𐌰𐌽𐌰𐌻𐌰𐌿𐌲𐌽 𐍂𐌹𐌵𐌹𐌶𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐌱𐌰𐌹𐍂𐌷𐍄𐌴𐌹𐌸 𐍂𐌿𐌽𐍉𐍃 𐌷𐌰𐌹𐍂𐍄𐌰𐌽𐌴; 𐌾𐌰𐌸~𐌸𐌰𐌽 𐌷𐌰𐌶𐌴𐌹𐌽𐍃 𐍅𐌰𐌹𐍂𐌸𐌹𐌸 𐍈𐌰𐍂𐌾𐌰𐌼𐌼𐌴𐌷 𐍆𐍂𐌰𐌼 𐌲𐌿𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, '𐌰𐌸𐌸𐌰𐌽, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌸𐌰𐌹𐍂𐌷𐌲𐌰𐌻𐌴𐌹𐌺𐍉[𐌽]𐌳𐌰 𐌹𐌽 𐌼𐌹𐍃 𐌾𐌰𐌷 𐌰𐍀𐌰𐌿𐌻𐌻𐍉𐌽 𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌴𐌹 𐌹𐌽 𐌿𐌲𐌺𐌹𐍃 𐌲𐌰𐌽𐌹𐌼𐌰𐌹𐌸 𐌽𐌹 𐌿𐍆𐌰𐍂 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄 𐍆𐍂𐌰𐌸𐌾𐌰𐌽, 𐌴𐌹 𐌰𐌹𐌽𐍃 𐍆𐌰𐌿𐍂 𐌰𐌹𐌽𐌰𐌽𐌰 𐌰𐌽𐌰 𐌰𐌽𐌸𐌰𐍂𐌰𐌽𐌰 𐌿𐍆𐌱𐌻𐌴𐍃𐌰𐌽𐍃 𐌽𐌹 𐍃𐌹𐌾𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, '𐍈𐌰𐍃 𐌰𐌿𐌺 𐌸𐌿𐌺 𐌿𐍃𐍃𐍉𐌺𐌴𐌹𐌸? 𐍈𐌰𐌿𐌸~𐌸𐌰𐌽 𐌷𐌰𐌱𐌰𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌽𐌹 𐌽𐌰𐌼𐍄? 𐌰𐌹𐌸𐌸𐌰𐌿 𐌾𐌰𐌱𐌰𐌹 𐌰𐌽𐌳𐌽𐌰𐌼𐍄, 𐍈𐌰 𐍈𐍉𐍀𐌹𐍃 𐍃𐍅𐌴 𐌽𐌹 𐌽𐌴𐌼𐌴𐌹𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, '𐌾𐌿 𐍃𐌰𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸, 𐌾𐌿 𐌲𐌰𐌱𐌹𐌲𐌰𐌹 𐍅𐌰𐌿𐍂𐌸𐌿𐌸, 𐌹𐌽𐌿 𐌿𐌽𐍃 𐌸𐌹𐌿𐌳𐌰𐌽𐍉𐌳𐌴𐌳𐌿𐌸; 𐌾𐌰𐌷 𐍅𐌰𐌹𐌽𐌴𐌹 𐌸𐌹𐌿𐌳𐌰𐌽𐍉𐌳𐌴𐌳𐌴𐌹𐌸, 𐌴𐌹 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐌸𐌸𐌹𐌿𐌳𐌰𐌽𐍉𐌼𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, '𐌼𐌰𐌽 𐌰𐌿𐌺 𐌸𐌴𐌹 𐌲𐌿𐌸 𐌿𐌽𐍃 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌿𐌽𐍃 𐍃𐍀𐌴𐌳𐌹𐍃𐍄𐌰𐌽𐍃 𐌿𐍃𐍄𐌰𐌹𐌺𐌽𐌹𐌳𐌰, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌳𐌰𐌿𐌸𐌿𐌱𐌻𐌾𐌰𐌽𐍃, 𐌿𐌽𐍄𐌴 𐍆𐌰𐌹𐍂𐍅𐌴𐌹𐍄𐌻 𐍅𐌰𐌿𐍂𐌸𐌿𐌼 𐌸𐌹𐌶𐌰𐌹 𐌼𐌰𐌽𐌰𐍃𐌴𐌳𐌰𐌹 𐌾𐌰𐌷 𐌰𐌲𐌲𐌹𐌻𐌿𐌼 𐌾𐌰𐌷 𐌼𐌰𐌽𐌽𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, '𐍅𐌴𐌹𐍃 𐌳𐍅𐌰𐌻𐌰𐌹 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌹𐌸 𐌾𐌿𐍃 𐍆𐍂𐍉𐌳𐌰𐌹 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿; 𐍅𐌴𐌹𐌶𐌿𐌸~𐌸𐌰𐌽 𐌿𐌽𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐌰𐌹, 𐌹𐌸 𐌾𐌿𐍃 𐍃𐍅𐌹𐌽𐌸𐌰𐌹; 𐌾𐌿𐌶𐌿𐌸~𐌸𐌰𐌽 𐍅𐌿𐌻𐌸𐌰𐌲𐌰𐌹, 𐌹𐌸 𐍅𐌴𐌹𐍃 𐌿𐌽𐍃𐍅𐌴𐍂𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, '𐌿𐌽𐌳 𐌸𐍉 𐌽𐌿 𐍈𐌴𐌹𐌻𐌰 𐌾𐌰𐌷 𐌷𐌿𐌲𐌲𐍂𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌸𐌰𐌿𐍂𐍃𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌽𐌰𐌵𐌰𐌳𐌰𐌹 𐌾𐌰𐌷 𐌺𐌰𐌿𐍀𐌰𐍄𐌹𐌳𐌰𐌹 𐌾𐌰𐌷 𐌿𐌽𐌲𐌰𐍃𐍄𐍉𐌸𐌰𐌹.');
