INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, '.... 𐌾𐌿 𐌲𐌰𐍃𐍄𐌰𐌿𐌹𐌳𐌰 𐍃𐍅𐌴 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐍃 𐌸𐌰𐌽𐌰 𐍃𐍅𐌰 𐌸𐌰𐍄𐌰 𐌲𐌰𐍄𐌰𐌿𐌾𐌰𐌽𐌳𐌰𐌽,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, '𐌹𐌽 𐌽𐌰𐌼𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐍃𐌰𐌼𐌰𐌸 𐌲𐌰𐌲𐌰𐌲𐌲𐌰𐌽𐌳𐌰𐌼 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌼𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐌰𐌷𐌼𐌹𐌽, 𐌼𐌹𐌸 𐌼𐌰𐌷𐍄𐌰𐌹 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, '𐌰𐍄𐌲𐌹𐌱𐌰𐌽 𐌸𐌰𐌽𐌰 𐍃𐍅𐌰𐌻𐌴𐌹𐌺𐌰𐌽𐌰 𐌿𐌽𐌷𐌿𐌻𐌸𐌹𐌽 𐌳𐌿 𐌵𐌹𐍃𐍄𐌴𐌹𐌽𐌰𐌹 𐌻𐌴𐌹𐌺𐌹𐍃, 𐌴𐌹 𐌰𐌷𐌼𐌰 𐌲𐌰𐌽𐌹𐍃𐌰𐌹 𐌹𐌽 𐌳𐌰𐌲𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌹𐌴𐍃𐌿𐌹𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, '𐌽𐌹 𐌲𐍉𐌳𐌰 𐍃𐍉 𐍈𐍉𐍆𐍄𐌿𐌻𐌹 𐌹𐌶𐍅𐌰𐍂𐌰; 𐌽𐌹𐌿 𐍅𐌹𐍄𐌿𐌸 𐌸𐌰𐍄𐌴𐌹 𐌻𐌴𐌹𐍄𐌹𐌻 𐌱𐌴𐌹𐍃𐍄𐌹𐍃 𐌰𐌻𐌻𐌰𐌽𐌰 𐌳𐌰𐌹𐌲 𐌲𐌰𐌱𐌴𐌹𐍃𐍄𐌴𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, '𐌿𐍃𐌷𐍂𐌰𐌹𐌽𐌴𐌹𐌸 𐌸𐌰𐍄𐌰 𐍆𐌰𐌹𐍂𐌽𐌾𐍉 𐌱𐌴𐌹𐍃𐍄, 𐌴𐌹 𐍃𐌹𐌾𐌰𐌹𐌸 𐌽𐌹𐌿𐌾𐌹𐍃 𐌳𐌰𐌹𐌲𐍃, 𐍃𐍅𐌰𐍃𐍅𐌴 𐍃𐌹𐌾𐌰𐌹𐌸 𐌿𐌽𐌱𐌴𐌹𐍃𐍄𐌾𐍉𐌳𐌰𐌹; 𐌾𐌰𐌷 𐌰𐌿𐌺 𐍀𐌰𐍃𐌺𐌰 𐌿𐌽𐍃𐌰𐍂𐌰 𐌿𐍆𐍃𐌽𐌹𐌸𐌰𐌽𐍃 𐌹𐍃𐍄 𐍆𐌰𐌿𐍂 𐌿𐌽𐍃 𐍇𐍂𐌹𐍃𐍄𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, '𐌸𐌰𐌽𐌽𐌿 𐌳𐌿𐌻𐌸𐌾𐌰𐌼 𐌽𐌹 𐌹𐌽 𐌱𐌴𐌹𐍃𐍄𐌰 𐍆𐌰𐌹𐍂𐌽𐌾𐌰𐌼𐌼𐌰 𐌽𐌹𐌸~𐌸𐌰𐌽 𐌹𐌽 𐌱𐌴𐌹𐍃𐍄𐌰 𐌱𐌰𐌻𐍅𐌰𐍅𐌴𐍃𐌴𐌹𐌽𐍃 𐌾𐌰𐌷 𐌿𐌽𐍃𐌴𐌻𐌴𐌹𐌽𐍃, 𐌰𐌺 𐌹𐌽 𐌿𐌽𐌱𐌴𐌹𐍃𐍄𐌴𐌹𐌽 𐌿𐌽𐍅𐌰𐌼𐌼𐌴𐌹𐌽𐍃 𐌾𐌰𐍃~𐍃𐌿𐌽𐌾𐍉𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, '𐌲𐌰𐌼𐌴𐌻𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌰𐌽𐌰 𐌸𐌹𐌶𐌰𐌹 𐌰𐌹𐍀𐌹𐍃𐍄𐌰𐌿𐌻𐌴𐌹𐌽: 𐌽𐌹 𐌱𐌻𐌰𐌽𐌳𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌷𐍉𐍂𐌰𐌼,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, '𐌽𐌹 𐌸𐌰𐌹𐌼 𐌷𐍉𐍂𐌰𐌼 𐌸𐌹𐍃 𐍆𐌰𐌹𐍂𐍈𐌰𐌿𐍃, 𐌰𐌹𐌸𐌸𐌰𐌿 [𐌾𐌰𐌱𐌰𐌹] 𐌸𐌰𐌹𐌼 𐍆𐌰𐌹𐌷𐌿𐍆𐍂𐌹𐌺𐌰𐌼 𐌾𐌰𐌷 𐍅𐌹𐌻𐍅𐌰𐌼 𐌰𐌹𐌸𐌸𐌰𐌿 𐌲𐌰𐌻𐌹𐌿𐌲𐌰𐌼 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐍉𐌽𐌳𐌰𐌼, 𐌿𐌽𐍄𐌴 𐍃𐌺𐌿𐌻𐌳𐌴𐌳𐌴𐌹𐌸 𐌸𐌰𐌽 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐍆𐌰𐌹𐍂𐍈𐌰𐌿 𐌿𐍃𐌲𐌰𐌲𐌲𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, '𐌹𐌸 𐌽𐌿 𐌲𐌰𐌼𐌴𐌻𐌹𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌽𐌹 𐌱𐌻𐌰𐌽𐌳𐌰𐌽, 𐌾𐌰𐌱𐌰𐌹 𐍈𐌰𐍃 𐌱𐍂𐍉𐌸𐌰𐍂 𐌽𐌰𐌼𐌽𐌹𐌳𐍃 𐍃𐌹𐌾𐌰𐌹 𐌷𐍉𐍂𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐌰𐌹𐌷𐌿𐍆𐍂𐌹𐌺𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐌲𐌰𐌻𐌹𐌿𐌲𐌰𐌼 𐍃𐌺𐌰𐌻𐌺𐌹𐌽𐍉𐌽𐌳𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐌿𐌱𐌹𐌻𐍅𐌰𐌿𐍂𐌳𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐌰𐍆𐌳𐍂𐌿𐌲𐌺𐌾𐌰 𐌰𐌹𐌸𐌸𐌰𐌿 𐍅𐌹𐌻𐍅𐌰, 𐌸𐌰𐌼𐌼𐌰 𐍃𐍅𐌰𐌻𐌴𐌹𐌺𐌰𐌼𐌼𐌰 𐌽𐌹 𐌼𐌹𐌸𐌼𐌰𐍄𐌾𐌰𐌽.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, '𐍈𐌰 𐌼𐌹𐌺 𐌾𐌰𐌷 𐌸𐌰𐌽𐍃 𐌿𐍄𐌰 𐍃𐍄𐍉𐌾𐌰𐌽? 𐌽𐌹𐌿 𐌸𐌰𐌽𐍃 𐌹𐌽𐌽𐌰 𐌾𐌿𐍃 𐍃𐍄𐍉𐌾𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, '𐌹𐌸 𐌸𐌰𐌽𐍃 𐌿𐍄𐌰 𐌲𐌿𐌸 𐍃𐍄𐍉𐌾𐌹𐌸. 𐌿𐍃𐌽𐌹𐌼𐌹𐌸 𐌸𐌰𐌽𐌰 𐌿𐌱𐌹𐌻𐌰𐌽 𐌿𐍃 𐌹𐌶𐍅𐌹𐍃 𐍃𐌹𐌻𐌱𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, '𐌲𐌰𐌳𐌰𐍂𐍃 𐍈𐌰𐍃 𐌹𐌶𐍅𐌰𐍂𐌰, 𐍅𐌹𐌸𐍂𐌰 𐌰𐌽𐌸𐌰𐍂𐌰𐌽𐌰 𐍃𐍄𐌰𐌿𐌰 𐌷𐌰𐌱𐌰𐌽𐌳𐍃 𐍃𐍄𐍉𐌾𐌰𐌽 𐍆𐍂𐌰𐌼 𐌹𐌽𐍅𐌹𐌽𐌳𐌰𐌹𐌼 𐌾𐌰𐌷 𐌽𐌹 𐍆𐍂𐌰𐌼....');
