INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, '.... 𐍅𐌰𐌹𐍂𐌸𐌰𐌹 𐌸𐌰𐌹𐌼 𐌿𐌽𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, '𐌾𐌰𐌱𐌰𐌹 𐌰𐌿𐌺 𐍈𐌰𐍃 𐌲𐌰𐍃𐌰𐌹𐍈𐌹𐌸 𐌸𐌿𐌺 𐌸𐌰𐌽𐌰 𐌷𐌰𐌱𐌰𐌽𐌳𐌰𐌽 𐌺𐌿𐌽𐌸𐌹 𐌹𐌽 𐌲𐌰𐌻𐌹𐌿𐌲𐌴 𐍃𐍄𐌰𐌳𐌰 𐌰𐌽𐌰𐌺𐌿𐌼𐌱𐌾𐌰𐌽𐌳𐌰𐌽, 𐌽𐌹𐌿 𐌼𐌹𐌸𐍅𐌹𐍃𐍃𐌴𐌹 𐌹𐍃 𐍃𐌹𐌿𐌺𐌹𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐌹𐌽𐍃 𐍄𐌹𐌼𐍂𐌾𐌰𐌳𐌰 𐌳𐌿 𐌲𐌰𐌻𐌹𐌿𐌲𐌰𐌲𐌿𐌳𐌰𐌼 𐌲𐌰𐍃𐌰𐌻𐌹𐌸 𐌼𐌰𐍄𐌾𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, '𐍆𐍂𐌰𐌵𐌹𐍃𐍄𐌽𐌹𐌸 𐌰𐌿𐌺 𐍃𐌰 𐌿𐌽𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐌰 𐌰𐌽𐌰 𐌸𐌴𐌹𐌽𐌰𐌼𐌼𐌰 𐍅𐌹𐍄𐌿𐌱𐌽𐌾𐌰 𐌱𐍂𐍉𐌸𐌰𐍂 𐌹𐌽 𐌸𐌹𐌶𐌴 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌲𐌰𐍃𐍅𐌰𐌻𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, '𐍃𐍅𐌰𐌸~𐌸𐌰𐌽 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐍅𐌹𐌸𐍂𐌰 𐌱𐍂𐍉𐌸𐍂𐌿𐌽𐍃, 𐍃𐌻𐌰𐌷𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐌴 𐌲𐌰𐌷𐌿𐌲𐌳 𐍃𐌹𐌿𐌺𐌰, 𐌳𐌿 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌺𐌴𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, '𐌳𐌿𐌸𐌸𐌴 𐌾𐌰𐌱𐌰𐌹 𐌼𐌰𐍄𐍃 𐌲𐌰𐌼𐌰𐍂𐌶𐌴𐌹𐌸 𐌱𐍂𐍉𐌸𐌰𐍂, 𐌽𐌹 𐌼𐌰𐍄𐌾𐌰 𐌼𐌹𐌼𐌶 𐌰𐌹𐍅, 𐌴𐌹 𐌽𐌹 𐌲𐌰𐌼𐌰𐍂𐌶𐌾𐌰𐌿 𐌱𐍂𐍉𐌸𐌰𐍂 𐌼𐌴𐌹𐌽𐌰𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, '𐌽𐌹𐌿 𐌹𐌼 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌿𐍃? 𐌽𐌹𐌿 𐌹𐌼 𐍆𐍂𐌴𐌹𐍃? 𐌽𐌹𐌿 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐍆𐍂𐌰𐌿𐌾𐌰𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌽𐌰 𐍃𐌰𐍈? 𐌽𐌹𐌿 𐍅𐌰𐌿𐍂𐍃𐍄𐍅 𐌼𐌴𐌹𐌽𐌰𐍄𐌰 𐌾𐌿𐍃 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, '𐌾𐌰𐌱𐌰𐌹 𐌰𐌽𐌸𐌰𐍂𐌰𐌹𐌼 𐌽𐌹 𐌹𐌼 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌿𐍃, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌹𐌶𐍅𐌹𐍃 𐌹𐌼; 𐌿𐌽𐍄𐌴 𐍃𐌹𐌲𐌻𐌾𐍉 𐌼𐌴𐌹𐌽𐌰𐌹𐌶𐍉𐍃 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌴𐌹𐌽𐍃 𐌾𐌿𐍃 𐍃𐌹𐌾𐌿𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, '𐌼𐌴𐌹𐌽𐌰 𐌰𐌽𐌳𐌰𐌷𐌰𐍆𐍄𐍃 𐍅𐌹𐌸𐍂𐌰 𐌸𐌰𐌽𐍃 𐌼𐌹𐌺 𐌿𐍃𐍃𐍉𐌺𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐍄~𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, '𐌹𐌱𐌰𐌹 𐌽𐌹 𐌷𐌰𐌱𐌰𐌼 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐌼𐌰𐍄𐌾𐌰𐌽 𐌾𐌰𐌷 𐌳𐍂𐌹𐌲𐌺𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, '𐌹𐌱𐌰𐌹 𐌽𐌹 𐌷𐌰𐌱𐌰𐌼 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐍃𐍅𐌹𐍃𐍄𐌰𐍂 𐌵𐌹𐌽𐍉𐌽 𐌱𐌹𐍄𐌹𐌿𐌷𐌰𐌽, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌸𐌰𐌹 𐌰𐌽𐌸𐌰𐍂𐌰𐌹 𐌰𐍀𐌰𐌿𐍃𐍄𐌰𐌿𐌻𐌴𐌹𐍃 𐌾𐌰𐌷 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌾𐌰𐌷 𐌺𐌴𐍆𐌰𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, '𐌸𐌰𐌿 𐌰𐌹𐌽𐌶𐌿 𐌹𐌺 𐌾𐌰𐌷 𐌱𐌰𐍂𐌽𐌰𐌱𐌰𐍃 𐌽𐌹 𐌷𐌰𐌱𐍉𐍃 𐍅𐌰𐌻𐌳𐌿𐍆𐌽𐌹 𐌳𐌿 𐌽𐌹 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, '𐍈𐌰𐍃 𐌳𐍂𐌰𐌿𐌷𐍄𐌹𐌽𐍉𐌸 𐍃𐍅𐌴𐍃𐌰𐌹𐌼 𐌰𐌽𐌽𐍉𐌼 𐍈𐌰𐌽? 𐍈𐌰𐍃 𐍃𐌰𐍄𐌾𐌹𐌸 𐍅𐌴𐌹𐌽𐌰𐍄𐍂𐌹𐍅𐌰 𐌾𐌰𐌷 𐌰𐌺𐍂𐌰𐌽 𐌸𐌹𐌶𐌴 𐌽𐌹 𐌼𐌰𐍄𐌾𐌰𐌹? 𐍈𐌰𐍃 𐌷𐌰𐌻𐌳𐌹𐌸 𐌰𐍅𐌴𐌸𐌹 𐌾𐌰𐌷 𐌼𐌹𐌻𐌿𐌺𐍃 𐌸𐌹𐍃 𐌰𐍅𐌴𐌸𐌾𐌹𐍃 𐌽𐌹 𐌼𐌰𐍄𐌾𐌰𐌹?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, '𐌹𐌱𐌰𐌹 𐌱𐌹 𐌼𐌰𐌽𐌽𐌰𐌼 𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌰, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌾𐌰𐌷 𐍅𐌹𐍄𐍉𐌸 𐌸𐌰𐍄𐌰 𐌵𐌹𐌸𐌹𐌸?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, '𐌹𐌽 𐍅𐌹𐍄𐍉𐌳𐌰 𐌰𐌿𐌺 𐌼𐍉𐍃𐌴𐌶𐌹𐍃 𐌲𐌰𐌼𐌴𐌻𐌹𐌸 𐌹𐍃𐍄: 𐌽𐌹 𐍆𐌰𐌿𐍂𐌼𐌿𐌻𐌾𐌰𐌹𐍃 𐌰𐌿𐌷𐍃𐌰𐌿 𐌸𐍂𐌹𐍃𐌺𐌰𐌽𐌳𐌰𐌽. 𐌽𐌹 𐌸𐌰𐍄𐌴𐌹 𐌱𐌹 𐌰𐌿𐌷𐍃𐌿𐌼 𐌿𐍃....');
