INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, '.... 𐌴𐌹 𐌼𐌰𐌽𐌰𐌲𐌹𐌶𐌰𐌽𐍃 𐌲𐌰𐌲𐌴𐌹𐌲𐌰𐌹𐌳𐌴𐌳𐌾𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, '𐌾𐌰𐌷 𐍅𐌰𐍂𐌸 𐌹𐌿𐌳𐌰𐌹𐌿𐌼 𐍃𐍅𐌴 𐌾𐌿𐌳𐌰𐌹𐌿𐍃, 𐌴𐌹 𐌾𐌿𐌳𐌰𐌹𐌿𐌽𐍃 𐌲𐌰𐌲𐌴𐌹𐌲𐌰𐌹𐌳𐌰𐌿; 𐌸𐌰𐌹𐌼 𐌿𐍆 𐍅𐌹𐍄𐍉𐌳𐌰 𐍃𐍅𐌴 𐌿𐍆 𐍅𐌹𐍄𐍉𐌳𐌰, 𐌽𐌹 𐍅𐌹𐍃𐌰𐌽𐌳𐍃 𐍃𐌹𐌻𐌱𐌰 𐌿𐍆 𐍅𐌹𐍄𐍉𐌳𐌰, 𐌰𐌺 𐌿𐍆 𐌰𐌽𐍃𐍄𐌰𐌹, 𐌴𐌹 𐌸𐌰𐌽𐍃 𐌿𐍆 𐍅𐌹𐍄𐍉𐌳𐌰 𐌲𐌰𐌲𐌴𐌹𐌲[𐌲]𐌰𐌹𐌳𐌴𐌳𐌾𐌰𐌿;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, '𐌸𐌰𐌹𐌼 𐍅𐌹𐍄𐍉𐌳𐌰𐌻𐌰𐌿𐍃𐌰𐌼 𐍃𐍅𐌴 𐍅𐌹𐍄𐍉𐌳𐌰𐌻𐌰𐌿𐍃, 𐌽𐌹 𐍅𐌹𐍃𐌰𐌽𐌳𐍃 𐍅𐌹𐍄𐍉𐌳𐌹𐍃 𐌻𐌰𐌿𐍃 𐌲𐌿𐌳𐌹𐍃, 𐌰𐌺 𐌹𐌽𐍅𐌹𐍄𐍉𐌸 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌴𐌹 𐌲𐌰𐌲𐌴𐌹𐌲[𐌲]𐌰𐌿 𐍅𐌹𐍄𐍉𐌳𐌰𐌻𐌰𐌿𐍃𐌰𐌽𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, '𐍅𐌰𐍃 𐌸𐌰𐌹𐌼 𐌿𐌽𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐌰𐌼 𐍃𐍅𐌴 𐌿𐌽𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐍃, 𐌴𐌹 𐌿𐌽𐌼𐌰𐌷𐍄𐌴𐌹𐌲𐌰𐌽𐍃 𐌲𐌰𐌲𐌴𐌹𐌲[𐌲]𐌰𐌹𐌳𐌴𐌳𐌾𐌰𐌿; 𐌰𐌻𐌻𐌰𐌹𐌼 𐍅𐌰𐍃 𐌰𐌻𐌻, 𐌴𐌹 𐍈𐌰𐌹𐍅𐌰 𐍃𐌿𐌼𐌰𐌽𐍃 𐌲𐌰𐌽𐌰𐍃𐌾𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, '𐌸𐌰𐍄𐌿𐌸~𐌸𐌰𐌽 𐍄𐌰𐌿𐌾𐌰 𐌹𐌽 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐌹𐍃, 𐌴𐌹 𐌲𐌰𐌳𐌰𐌹𐌻𐌰 𐌹𐍃 𐍅𐌰𐌹𐍂𐌸𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, '𐌽𐌹𐌿 𐍅𐌹𐍄𐌿𐌸 𐌸𐌰𐍄𐌴𐌹 𐌸𐌰𐌹 𐌹𐌽 𐍃𐍀𐌰𐌿𐍂𐌳 𐍂𐌹𐌽𐌽𐌰𐌽𐌳𐌰𐌽𐍃 𐌰𐌻𐌻𐌰𐌹 𐍂𐌹𐌽𐌽𐌰𐌽𐌳, 𐌹𐌸 𐌰𐌹𐌽𐍃 𐌽𐌹𐌼𐌹𐌸 𐍃𐌹𐌲𐌹𐍃𐌻𐌰𐌿𐌽? 𐍃𐍅𐌰 𐍂𐌹𐌽𐌽𐌰𐌹𐌸, 𐌴𐌹 𐌲𐌰𐍂𐌹𐌽𐌽𐌰𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, '𐌹𐌸 𐍈𐌰𐌶𐌿𐌷 𐍃𐌰𐌴𐌹 𐌷𐌰𐌹𐍆𐍃𐍄𐌾𐌰𐌽 𐍃𐌽𐌹𐍅𐌹𐌸, 𐌰𐌻𐌻𐌹𐍃 𐍃𐌹𐌺 𐌲𐌰𐌸𐌰𐍂𐌱𐌹𐌸; 𐌰𐌸𐌸𐌰𐌽 𐌴𐌹𐍃, 𐌴𐌹 𐍂𐌹𐌿𐍂𐌾𐌰𐌽𐌰 𐍅𐌰𐌹𐍀 𐌽𐌹𐌼𐌰𐌹𐌽𐌰, 𐌹𐌸 𐍅𐌴𐌹𐍃 𐌿𐌽𐍂𐌹𐌿𐍂𐌾𐌰𐌽𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, '𐌰𐌸𐌸𐌰𐌽 𐌹𐌺 𐌽𐌿 𐍃𐍅𐌰 𐍂𐌹𐌽𐌽𐌰, 𐌽𐌹 𐌳𐌿 𐌿𐌽𐍅𐌹𐍃𐌰𐌼𐌼𐌰; 𐍃𐍅𐌰 𐌾𐌹𐌿𐌺𐌰, 𐌽𐌹 𐍃𐍅𐌴 𐌻𐌿𐍆𐍄𐌿 𐌱𐌻𐌹𐌲𐌲𐍅𐌰𐌽𐌳𐍃;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, '𐌰𐌺 𐌻𐌴𐌹𐌺 𐌼𐌴𐌹𐌽 𐍅𐌻𐌹𐌶𐌾𐌰 𐌾𐌰𐌷 𐌰𐌽𐌰𐌸𐌹𐍅𐌰, 𐌹𐌱𐌰𐌹 𐌰𐌽𐌸𐌰𐍂𐌰𐌹𐌼 𐌼𐌴𐍂𐌾𐌰𐌽𐌳𐍃 𐍃𐌹𐌻𐌱𐌰 𐌿𐍃𐌺𐌿𐍃𐌰𐌽𐍃 𐍅𐌰𐌹𐍂𐌸𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, '𐌽𐌹 𐍅𐌹𐌻𐌾𐌰𐌿 𐌹𐌶𐍅𐌹𐍃 𐌿𐌽𐍅𐌹𐍄𐌰𐌽𐍃, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌰𐍄𐍄𐌰𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌰𐌹 𐌰𐌻𐌻𐌰𐌹 𐌿𐍆 𐌼𐌹𐌻𐌷𐌼𐌹𐌽 𐍅𐌴𐍃𐌿𐌽, 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌹 𐌼𐌰𐍂𐌴𐌹𐌽 𐌸𐌰𐌹𐍂𐌷𐌹𐌳𐌳𐌾𐌴𐌳𐌿𐌽,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, '𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌹 𐌹𐌽 𐌼𐍉𐍃𐌴 𐌳𐌰𐌿𐍀𐌹𐌳𐌰𐌹 𐍅𐌴𐍃𐌿𐌽, 𐌹𐌽 𐌼𐌹𐌻𐌷𐌼𐌹𐌽 𐌾𐌰𐌷 𐌹𐌽 𐌼𐌰𐍂𐌴𐌹𐌽,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, '𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌹 𐌸𐌰𐌽𐌰 𐍃𐌰𐌼𐌰𐌽 𐌼𐌰𐍄 𐌰𐌷𐌼𐌴𐌹𐌽𐌰𐌽 𐌼𐌰𐍄𐌹𐌳𐌴𐌳𐌿𐌽,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, '𐌾𐌰𐌷 𐌸𐌰𐍄𐌰 𐍃𐌰𐌼𐍉 𐌳𐍂𐌰𐌲𐌺 𐌰𐌷𐌼𐌴𐌹𐌽𐍉 𐌳𐍂𐌿𐌲𐌺𐌿𐌽....');
