INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, '.... 𐍃𐌿𐌼𐌰𐌼𐌼𐌿𐌷 𐍃𐌺𐌴𐌹𐍂𐌴𐌹𐌽𐍃 𐍂𐌰𐌶𐌳𐍉.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, '𐌸𐌰𐍄𐌿𐌸~𐌸𐌰𐌽 𐌰𐌻𐌻 𐍅𐌰𐌿𐍂𐌺𐌴𐌹𐌸 𐌰𐌹𐌽𐍃 𐌾𐌰𐌷 𐍃𐌰 𐍃𐌰𐌼𐌰 𐌰𐌷𐌼𐌰, 𐌳𐌰𐌹𐌻𐌴𐌹𐌸 𐍃𐌿𐌽𐌳𐍂𐍉 𐍈𐌰𐍂𐌾𐌰𐌼𐌼𐌴𐌷 𐍃𐍅𐌰𐍃𐍅𐌴 𐍅𐌹𐌻𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, '𐍃𐍅𐌴 𐌻𐌴𐌹𐌺 𐍂𐌰𐌹𐌷𐍄𐌹𐍃 𐌰𐌹𐌽 𐌹𐍃𐍄, 𐌹𐌸 𐌻𐌹𐌸𐌿𐌽𐍃 𐌷𐌰𐌱𐌰𐌹𐌸 𐌼𐌰𐌽𐌰𐌲𐌰𐌽𐍃, 𐌸𐌰𐌹𐌸~𐌸𐌰𐌽 𐌻𐌹𐌸𐌾𐌿𐍃 𐌰𐌻𐌻𐌰𐌹 𐌿𐍃 𐌻𐌴𐌹𐌺𐌰 𐌸𐌰𐌼𐌼𐌰 𐌰𐌹𐌽𐌰𐌼𐌼𐌰, 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃, 𐌰𐌹𐌽 𐌹𐍃𐍄 𐌻𐌴𐌹𐌺, 𐍃𐍅𐌰 𐌾𐌰𐌷 𐍇𐍂𐌹𐍃𐍄𐌿𐍃.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, '𐌾𐌰𐌷 𐌰𐌿𐌺 𐌹𐌽 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌰𐌷𐌼𐌹𐌽 𐍅𐌴𐌹𐍃 𐌰𐌻𐌻𐌰𐌹 𐌳𐌿 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌻𐌴𐌹𐌺𐌰 𐌳𐌰𐌿𐍀𐌹𐌳𐌰𐌹 𐍃𐌹𐌿𐌼, 𐌾𐌰𐌸𐌸𐌴 𐌾𐌿𐌳𐌰𐌹𐌴𐌹𐍃 𐌾𐌰𐌸𐌸𐌴 𐌸𐌹𐌿𐌳𐍉𐍃, 𐌾𐌰𐌸𐌸𐌴 𐍃𐌺𐌰𐌻𐌺𐍉𐍃 𐌾𐌰𐌸𐌸𐌴 𐍆𐍂𐌹𐌾𐌰𐌹, 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌹 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐌰𐌷𐌼𐌹𐌽 𐌳𐍂𐌰𐌲𐌺𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, '𐌾𐌰𐌸~𐌸𐌰𐌽 𐌻𐌴𐌹𐌺 𐌽𐌹𐍃𐍄 𐌰𐌹𐌽𐍃 𐌻𐌹𐌸𐌿𐍃, 𐌰𐌺 𐌼𐌰𐌽𐌰𐌲𐌰𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, '𐌾𐌰𐌱𐌰𐌹 𐌵𐌹𐌸𐌰𐌹 𐍆𐍉𐍄𐌿𐍃 𐌸𐌰𐍄𐌴𐌹 𐌽𐌹 𐌹𐌼 𐌷𐌰𐌽𐌳𐌿𐍃, 𐌽𐌹 𐌹𐌼 𐌸𐌹𐍃 𐌻𐌴𐌹𐌺𐌹𐍃, 𐌽𐌹𐌷 𐌰𐍄 𐌸𐌰𐌼𐌼𐌰 𐌻𐌴𐌹𐌺𐌰; 𐌽𐌹𐍃𐍄 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐌻𐌴𐌹𐌺𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, '𐌾𐌰𐌱𐌰𐌹 𐌵𐌹𐌸𐌰𐌹 𐌰𐌿𐍃𐍉 𐌸𐌰𐍄𐌴𐌹 𐌽𐌹 𐌹𐌼 𐌰𐌿𐌲𐍉, 𐌽𐌹 𐌹𐌼 𐌸𐌹𐍃 𐌻𐌴𐌹𐌺𐌹𐍃, 𐌽𐌹 𐌰𐍄 𐌸𐌰𐌼𐌼𐌰 𐌻𐌴𐌹𐌺𐌰; 𐌽𐌹𐍃𐍄 𐌿𐍃 𐌸𐌰𐌼𐌼𐌰 𐌻𐌴𐌹𐌺𐌰?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, '𐌾𐌰𐌱𐌰𐌹 𐌰𐌻𐌻 𐌻𐌴𐌹𐌺 𐌰𐌿𐌲𐍉, 𐍈𐌰𐍂 𐌷𐌻𐌹𐌿𐌼𐌰? 𐌾𐌰𐌱𐌰𐌹 𐌰𐌻𐌻 𐌷𐌻𐌹𐌿𐌼𐌰, 𐍈𐌰𐍂 𐌳𐌰𐌿𐌽𐍃?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, '𐌹𐌸 𐌽𐌿 𐌲𐌿𐌸 𐌲𐌰𐍃𐌰𐍄𐌹𐌳𐌰 𐌻𐌹𐌸𐌿𐌽𐍃 𐌰𐌹𐌽𐍈𐌰𐍂𐌾𐌰𐌽𐍉𐌷 𐌹𐌶𐌴 𐌹𐌽 𐌻𐌴𐌹𐌺𐌰, 𐍃𐍅𐌰𐍃𐍅𐌴 𐍅𐌹𐌻𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, '𐌹𐌸 𐍅𐌴𐍃𐌴𐌹𐌽𐌰 𐌸𐍉 𐌰𐌻𐌻𐌰 𐌰𐌹𐌽𐍃 𐌻𐌹𐌸𐌿𐍃, 𐍈𐌰𐍂 𐌻𐌴𐌹𐌺?');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, '𐌹𐌸 𐌽𐌿 𐌼𐌰𐌽𐌰𐌲𐌰𐌹 𐌻𐌹𐌸𐌾𐌿𐍃, 𐌹𐌸 𐌰𐌹𐌽 𐌻𐌴𐌹𐌺.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, '𐌽𐌹𐌸~𐌸𐌰𐌽 𐌼𐌰𐌲 𐌰𐌿𐌲𐍉 𐌵𐌹𐌸𐌰𐌽 𐌳𐌿 𐌷𐌰𐌽𐌳𐌰𐌿: 𐌸𐌴𐌹𐌽𐌰 𐌽𐌹 𐌸𐌰𐍂𐍆, 𐌰𐌹𐌸𐌸𐌰𐌿 𐌰𐍆𐍄𐍂𐌰 𐌷𐌰𐌿𐌱𐌹𐌸 𐌳𐌿 𐍆𐍉𐍄𐌿𐌼: 𐌹𐌲𐌲𐌵𐌰𐍂𐌰 𐌽𐌹 𐌸𐌰𐍂𐍆;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, '𐌰𐌺 𐍆𐌹𐌻𐌿 𐌼𐌰𐌹𐍃 𐌸𐌰𐌹𐌴(𐌹) 𐌸𐌿𐌲𐌺𐌾𐌰𐌽𐌳 𐌻𐌹𐌸𐌹𐍅𐌴 𐌻𐌴𐌹𐌺𐌹𐍃 𐌻𐌰𐍃𐌹𐍅𐍉𐍃𐍄𐌰𐌹 𐍅𐌹𐍃𐌰𐌽, 𐌸𐌰𐌿𐍂𐍆𐍄𐌰𐌹 𐍃𐌹𐌽(𐌳)....');
