INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, '.... 𐌰𐌹𐌸𐌸𐌰𐌿 𐌺𐌻𐌹𐍃𐌼𐍉 𐌺𐌻𐌹𐍃𐌼𐌾𐌰𐌽𐌳𐌴𐌹.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, '𐌾𐌰𐌷 𐌾𐌰𐌱𐌰𐌹 𐌷𐌰𐌱𐌰𐌿 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌾𐌰𐌽𐍃 𐌾𐌰𐌷 𐍅𐌹𐍄𐌾𐌰𐌿 𐌰𐌻𐌻𐌰𐌹𐌶𐌴 𐍂𐌿𐌽𐍉𐍃 𐌾𐌰𐌷 𐌰𐌻𐌻 𐌺𐌿𐌽𐌸𐌹 𐌾𐌰𐌷 𐌷𐌰𐌱𐌰𐌿 𐌰𐌻𐌻𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽, 𐍃𐍅𐌰𐍃𐍅𐌴 𐍆𐌰𐌹𐍂𐌲𐌿𐌽𐌾𐌰 𐌼𐌹𐌸𐍃𐌰𐍄𐌾𐌰𐌿, 𐌹𐌸 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌽𐌹 𐌷𐌰𐌱𐌰𐌿, 𐌽𐌹 𐍅𐌰𐌹𐌷𐍄𐍃 𐌹𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, '𐌾𐌰𐌷 𐌾𐌰𐌱𐌰𐌹 𐍆𐍂𐌰𐌰𐍄𐌾𐌰𐌿 𐌰𐌻𐌻𐍉𐍃 𐌰𐌹𐌷𐍄𐌹𐌽𐍃 𐌼𐌴𐌹𐌽𐍉𐍃, 𐌾𐌰𐌷 𐌾𐌰𐌱𐌰𐌹 𐌰𐍄𐌲𐌹𐌱𐌰𐌿 𐌻𐌴𐌹𐌺 𐌼𐌴𐌹𐌽 𐌴𐌹 𐌲𐌰𐌱𐍂𐌰𐌽𐌽𐌾𐌰𐌹𐌳𐌰𐌿, 𐌹𐌸 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌷𐌰𐌱𐌰𐌿, 𐌽𐌹 𐍅𐌰𐌹𐌷𐍄 𐌱𐍉𐍄𐍉𐍃 𐌼𐌹𐍃 𐍄𐌰𐌿𐌾𐌰𐌿.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, '𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌿𐍃𐌱𐌴𐌹𐍃𐌽𐌴𐌹𐌲𐌰 𐌹𐍃𐍄, 𐍃𐌴𐌻𐍃 𐌹𐍃𐍄: 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌽𐌹 𐌰𐌻𐌾𐌰𐌽𐍉𐌸; 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌽𐌹 𐍆𐌻𐌰𐌿𐍄𐌴𐌹𐌸, 𐌽𐌹 𐌿𐍆𐌱𐌻𐌴𐍃𐌰𐌳𐌰,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, '𐌽𐌹 𐌰𐌹𐍅𐌹𐍃𐌺𐍉𐌸, 𐌽𐌹 𐍃𐍉𐌺𐌴𐌹𐌸 𐍃𐌴𐌹𐌽 𐌰𐌹𐌽, 𐌽𐌹 𐌹𐌽𐌲𐍂𐌰𐌼𐌾𐌰𐌳𐌰, 𐌽𐌹𐌷 𐌼𐌹𐍄𐍉𐌸 𐌿𐌱𐌹𐌻,');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, '𐌽𐌹𐌷 𐍆𐌰𐌲𐌹𐌽𐍉𐌸 𐌹𐌽𐍅𐌹𐌽𐌳𐌹𐌸𐌰𐌹, 𐌼𐌹𐌸𐍆𐌰𐌲𐌹𐌽𐍉𐌸 𐍃𐌿𐌽𐌾𐌰𐌹;');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, '𐌰𐌻𐌻𐌰𐍄𐌰 𐌸𐌿𐌻𐌰𐌹𐌸, 𐌰𐌻𐌻𐌰𐍄𐌰 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸, 𐌰𐌻𐌻 𐍅𐌴𐌽𐌴𐌹𐌸, 𐌰𐌻𐌻 𐌲𐌰𐌱𐌴𐌹𐌳𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, '𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌰𐌹𐍅 𐌽𐌹 𐌲𐌰𐌳𐍂𐌹𐌿𐍃𐌹𐌸, 𐌹𐌸 𐌾𐌰𐌸𐌸𐌴 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌾𐌰 𐌲𐌰𐍄𐌰𐌹𐍂𐌰𐌽𐌳𐌰 𐌾𐌰𐌸𐌸𐌴 𐍂𐌰𐌶𐌳𐍉𐍃 𐌲𐌰𐍈𐌴𐌹𐌻𐌰𐌽𐌳 𐌾𐌰𐌸𐌸𐌴 𐌺𐌿𐌽𐌸𐌹 𐌲𐌰𐍄𐌰𐌿𐍂𐌽𐌹𐌸.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, '𐍃𐌿𐌼𐌰𐌽 𐌺𐌿𐌽𐌽𐌿𐌼 𐌾𐌰𐌷 𐍃𐌿𐌼𐌰𐌽 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌾𐌰𐌼.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, '𐌱𐌹𐌸𐌴 𐌵𐌹𐌼𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌿𐍃𐍄𐌰𐌿𐌷𐌰𐌽 𐌹𐍃𐍄, 𐌲𐌰𐍄𐌰𐌿𐍂𐌽𐌹𐌸 𐌸𐌰𐍄𐌴𐌹 𐌿𐍃 𐌳𐌰𐌹𐌻𐌰𐌹 𐌹𐍃𐍄.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, '𐌹𐌸 𐌸𐌰𐌽 𐍅𐌰𐍃 𐌽𐌹𐌿𐌺𐌻𐌰𐌷𐍃, 𐍃𐍅𐌴 𐌽𐌹𐌿𐌺𐌻𐌰𐌷𐍃 𐍂𐍉𐌳𐌹𐌳𐌰, 𐍃𐍅𐌴 𐌽𐌹𐌿𐌺𐌻𐌰𐌷𐍃 𐍆𐍂𐍉𐌸, 𐍃𐍅𐌴 𐌽𐌹𐌿𐌺𐌻𐌰𐌷𐍃 𐌼𐌹𐍄𐍉𐌳𐌰; 𐌱𐌹𐌸𐌴 𐍅𐌰𐍂𐌸 𐍅𐌰𐌹𐍂, 𐌱𐌰𐍂𐌽𐌹𐍃𐌺𐌴𐌹𐌽𐍃 𐌰𐍆𐌻𐌰𐌲𐌹𐌳𐌰.');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, '𐍃𐌰𐌹𐍈𐌰𐌼 𐌽𐌿 𐌸𐌰𐌹𐍂𐌷 𐍃𐌺𐌿𐌲𐌲𐍅𐌰𐌽 𐌹𐌽 𐍆𐍂𐌹𐍃𐌰𐌷𐍄𐌰𐌹, 𐌹𐌸 𐌸𐌰𐌽 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐌹 𐍅𐌹𐌸𐍂𐌰 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐌹; 𐌽𐌿 𐍅𐌰𐌹𐍄 𐌿𐍃 𐌳𐌰𐌹𐌻𐌰𐌹, 𐌹𐌸 𐌸𐌰𐌽 𐌿𐍆𐌺𐌿𐌽𐌽𐌰....');
INSERT INTO `Wulfila_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, '');
